#!/usr/bin/env bash
# mili 0.1.0 - single-file build (do not edit; generated by build.sh)
# Source: https://github.com/yaldoughie/mili
MILI_BUNDLED=1

# ===== lib/ui.sh =====
# shellcheck shell=bash
# mili :: ui.sh - colors, banner, boxes, menus, prompts, spinner, badges
# Pure functions. No top-level side effects except ui_init() when called.

# ---- color capability detection ------------------------------------------
# Sets MILI_COLORMODE = truecolor | 256 | 16 | none and defines palette vars.
ui_init() {
  local force="${MILI_COLOR:-auto}"   # auto|always|never
  MILI_COLORMODE=none
  if [[ "$force" == never || -n "${NO_COLOR:-}" ]]; then
    MILI_COLORMODE=none
  elif [[ "$force" == always ]]; then
    MILI_COLORMODE=truecolor
  elif [[ -t 1 ]]; then
    case "${COLORTERM:-}" in
      truecolor|24bit) MILI_COLORMODE=truecolor ;;
      *)
        local n; n=$(tput colors 2>/dev/null || echo 0)
        if   (( n >= 256 )); then MILI_COLORMODE=256
        elif (( n >= 8   )); then MILI_COLORMODE=16
        else MILI_COLORMODE=none; fi ;;
    esac
  fi

  if [[ "$MILI_COLORMODE" == none ]]; then
    C_RST=''; C_B=''; C_DIM=''; C_IT=''; C_UL=''
    C_RED=''; C_GRN=''; C_YEL=''; C_BLU=''; C_MAG=''; C_CYN=''; C_WHT=''; C_GRY=''
    C_ORA=''; C_PNK=''; C_TEAL=''; C_LIME=''
    return 0
  fi

  C_RST=$'\e[0m'; C_B=$'\e[1m'; C_DIM=$'\e[2m'; C_IT=$'\e[3m'; C_UL=$'\e[4m'
  if [[ "$MILI_COLORMODE" == truecolor ]]; then
    C_RED=$'\e[38;2;255;85;85m';   C_GRN=$'\e[38;2;80;220;130m'
    C_YEL=$'\e[38;2;245;205;80m';  C_BLU=$'\e[38;2;90;160;255m'
    C_MAG=$'\e[38;2;200;120;255m'; C_CYN=$'\e[38;2;90;220;230m'
    C_WHT=$'\e[38;2;240;240;245m'; C_GRY=$'\e[38;2;150;155;165m'
    C_ORA=$'\e[38;2;255;160;70m';  C_PNK=$'\e[38;2;255;120;180m'
    C_TEAL=$'\e[38;2;60;200;190m'; C_LIME=$'\e[38;2;170;230;90m'
  elif [[ "$MILI_COLORMODE" == 256 ]]; then
    C_RED=$'\e[38;5;203m'; C_GRN=$'\e[38;5;114m'; C_YEL=$'\e[38;5;221m'
    C_BLU=$'\e[38;5;75m';  C_MAG=$'\e[38;5;177m'; C_CYN=$'\e[38;5;80m'
    C_WHT=$'\e[38;5;255m'; C_GRY=$'\e[38;5;245m'; C_ORA=$'\e[38;5;215m'
    C_PNK=$'\e[38;5;211m'; C_TEAL=$'\e[38;5;43m'; C_LIME=$'\e[38;5;149m'
  else
    C_RED=$'\e[31m'; C_GRN=$'\e[32m'; C_YEL=$'\e[33m'; C_BLU=$'\e[34m'
    C_MAG=$'\e[35m'; C_CYN=$'\e[36m'; C_WHT=$'\e[37m'; C_GRY=$'\e[90m'
    C_ORA=$'\e[33m'; C_PNK=$'\e[35m'; C_TEAL=$'\e[36m'; C_LIME=$'\e[32m'
  fi
}

# visible width of a string (strip ANSI)
ui_width() { local s="$1"; s=$(printf '%s' "$s" | sed -E $'s/\x1b\\[[0-9;]*m//g'); printf '%s' "${#s}"; }

# truecolor gradient banner for the word MILI
ui_banner() {
  local sub="${1:-}"
  if [[ "$MILI_COLORMODE" == none ]]; then
    printf '%s\n' "=== M I L I ==="
    [[ -n "$sub" ]] && printf '%s\n' "$sub"
    return
  fi
  local -a rows
  rows=(
    'MM    MM  II  LL      II'
    'MMM  MMM  II  LL      II'
    'MM MM MM  II  LL      II'
    'MM    MM  II  LL      II'
    'MM    MM  II  LLLLLL  II'
  )
  local row out ch n i r g b
  for row in "${rows[@]}"; do
    out=''; n=${#row}
    for (( i=0; i<n; i++ )); do
      ch="${row:i:1}"
      if [[ "$ch" == ' ' ]]; then out+=' '; continue; fi
      if [[ "$MILI_COLORMODE" == truecolor ]]; then
        r=$(( 130 + i*110/(n>1?n-1:1) ))
        g=$(( 90  + i*50 /(n>1?n-1:1) ))
        b=$(( 235 - i*70 /(n>1?n-1:1) ))
        out+=$'\e[1;38;2;'"$r;$g;$b"'m'"$ch"
      else
        out+="$C_B$C_MAG$ch"
      fi
    done
    printf '  %s%s\n' "$out" "$C_RST"
  done
  [[ -n "$sub" ]] && printf '  %s%s%s\n' "$C_GRY" "$sub" "$C_RST"
}

# horizontal rule
ui_hr() { local w="${1:-64}" ch="${2:--}" out='' i; for ((i=0;i<w;i++)); do out+="$ch"; done; printf '%s%s%s\n' "$C_GRY" "$out" "$C_RST"; }

# section header
ui_head() { printf '\n%s[ %s ]%s\n' "$C_B$C_CYN" "$1" "$C_RST"; ui_hr 64; }

# status glyphs
ui_ok()   { printf '%s[OK]%s %s\n'   "$C_GRN" "$C_RST" "$*"; }
ui_warn() { printf '%s[!]%s %s\n'    "$C_YEL" "$C_RST" "$*"; }
ui_err()  { printf '%s[x]%s %s\n'    "$C_RED" "$C_RST" "$*"; }
ui_info() { printf '%s[*]%s %s\n'    "$C_BLU" "$C_RST" "$*"; }
ui_note() { printf '%s    %s%s\n'    "$C_GRY" "$*" "$C_RST"; }

# colored badge:  ui_badge <text> <color>
ui_badge() { local t="$1" c="${2:-$C_BLU}"; printf '%s %s %s' "$c$C_B" "$t" "$C_RST"; }

# key/value line
ui_kv() { printf '  %s%-18s%s %s\n' "$C_GRY" "$1" "$C_RST" "$2"; }

# numbered menu item:  ui_item <num> <label> [hint] [star]
ui_item() {
  local n="$1" label="$2" hint="${3:-}" star="${4:-}"
  local s=''; [[ -n "$star" ]] && s="$C_YEL*$C_RST "
  if [[ -n "$hint" ]]; then
    printf '   %s%2s%s) %s%s%-26s%s %s%s%s\n' "$C_B$C_CYN" "$n" "$C_RST" "$s" "$C_WHT" "$label" "$C_RST" "$C_GRY" "$hint" "$C_RST"
  else
    printf '   %s%2s%s) %s%s%s\n' "$C_B$C_CYN" "$n" "$C_RST" "$s$C_WHT" "$label" "$C_RST"
  fi
}

# ============================================================================
# arrow-key selector (live pointer, up/down + Enter). Returns 1-based index in
# global SEL (0 = cancelled). Items may embed a hint as "label\thint".
# Falls back to a numbered prompt when stdin/stdout is not a TTY or NO_COLOR.
# ============================================================================
declare -ga UISEL_ITEMS=()
UISEL_SEL=0

_ui_sel_row() {  # <index>  -- rows are truncated so they NEVER wrap (wrap would
                 #             desync the relative cursor math and "repeat" rows)
  local i="$1" raw="${UISEL_ITEMS[$1]}" label hint cols hmax
  label="${raw%%$'\t'*}"; hint=''
  [[ "$raw" == *$'\t'* ]] && hint="${raw#*$'\t'}"
  cols="${COLUMNS:-0}"; (( cols < 1 )) && cols="$(tput cols 2>/dev/null || echo 80)"; (( cols < 40 )) && cols=40
  # reserve: 5 (marker+indent) + 30 (label field) + 2 (gap) => hint budget
  hmax=$(( cols - 40 )); (( hmax < 0 )) && hmax=0
  [[ ${#label} -gt 32 ]] && label="${label:0:31}…"
  [[ -n "$hint" && ${#hint} -gt $hmax ]] && hint="${hint:0:hmax}"
  if (( i == UISEL_SEL )); then
    printf '\e[2K   %s▶ %s%-32s%s%s%s%s\n' \
      "$C_B$C_CYN" "$C_B$C_WHT" "$label" "$C_RST" "${hint:+  $C_CYN}" "$hint" "$C_RST"
  else
    printf '\e[2K     %s%-32s%s%s%s%s\n' \
      "$C_WHT" "$label" "$C_RST" "${hint:+  $C_GRY}" "$hint" "$C_RST"
  fi
}

_ui_sel_render() { local i; for i in "${!UISEL_ITEMS[@]}"; do _ui_sel_row "$i"; done; }

# ui_select <preselect-index> <item> [item...]   -> sets SEL (1-based; 0=cancel)
ui_select() {
  local pre="${1:-0}"; shift
  UISEL_ITEMS=("$@"); UISEL_SEL="$pre"
  local n=${#UISEL_ITEMS[@]} key esc
  (( n == 0 )) && { SEL=0; return; }
  (( UISEL_SEL < 0 || UISEL_SEL >= n )) && UISEL_SEL=0

  # fallback: no TTY / no color -> numbered prompt
  if [[ ! -t 0 || ! -t 1 || "$MILI_COLORMODE" == none ]]; then
    local i; for i in "${!UISEL_ITEMS[@]}"; do
      printf '   %s%2d%s) %s\n' "$C_B$C_CYN" $((i+1)) "$C_RST" "${UISEL_ITEMS[$i]%%$'\t'*}"
    done
    local pick; read -r -p "$(printf '%s>%s ' "$C_CYN" "$C_RST")" pick || true
    [[ "$pick" =~ ^[0-9]+$ ]] && SEL="$pick" || SEL=0
    return
  fi

  # Each item is exactly one (truncated) physical line, so the list always
  # occupies the bottom n lines; moving up n and reprinting is scroll-safe.
  tput civis 2>/dev/null || true
  _ui_sel_render
  while :; do
    IFS= read -rsn1 key 2>/dev/null || { SEL=0; break; }
    case "$key" in
      $'\x1b') read -rsn2 -t 0.05 esc 2>/dev/null
               case "$esc" in
                 '[A'|'OA') (( UISEL_SEL = (UISEL_SEL - 1 + n) % n )) ;;
                 '[B'|'OB') (( UISEL_SEL = (UISEL_SEL + 1) % n )) ;;
                 '') SEL=0; break ;;   # bare ESC = cancel
               esac ;;
      ''|$'\n'|$'\r') SEL=$(( UISEL_SEL + 1 )); break ;;
      k|K) (( UISEL_SEL = (UISEL_SEL - 1 + n) % n )) ;;
      j|J) (( UISEL_SEL = (UISEL_SEL + 1) % n )) ;;
      q|Q) SEL=0; break ;;
      [1-9]) (( key >= 1 && key <= n )) && UISEL_SEL=$(( key - 1 )) ;;
    esac
    printf '\e[%dA' "$n"   # back to top of the list (n single lines)
    _ui_sel_render
  done
  tput cnorm 2>/dev/null || true
}

# ---- prompts ---------------------------------------------------------------
# ask <prompt> <default> -> echoes answer
ui_ask() {
  local p="$1" def="${2:-}" ans
  if [[ -n "$def" ]]; then
    read -r -p "$(printf '%s? %s%s %s[%s]%s: ' "$C_CYN" "$C_RST" "$p" "$C_GRY" "$def" "$C_RST")" ans || true
    printf '%s' "${ans:-$def}"
  else
    read -r -p "$(printf '%s? %s%s: ' "$C_CYN" "$C_RST" "$p")" ans || true
    printf '%s' "$ans"
  fi
}

# ask_secret <prompt> -> echoes answer (no echo while typing)
ui_ask_secret() {
  local p="$1" ans
  read -r -s -p "$(printf '%s? %s%s: ' "$C_CYN" "$C_RST" "$p")" ans || true
  printf '\n' >&2
  printf '%s' "$ans"
}

# confirm <prompt> [default y|n] -> returns 0 for yes
ui_confirm() {
  local p="$1" def="${2:-n}" ans hint='[y/N]'
  [[ "$def" == y ]] && hint='[Y/n]'
  read -r -p "$(printf '%s? %s%s %s%s%s ' "$C_YEL" "$C_RST" "$p" "$C_GRY" "$hint" "$C_RST")" ans || true
  ans="${ans:-$def}"
  [[ "$ans" =~ ^[Yy]$ ]]
}

# pause until Enter
ui_pause() { read -r -p "$(printf '%s    press Enter to continue%s' "$C_GRY" "$C_RST")" _ || true; }

# spinner around a background pid:  ui_spin <pid> <msg>
ui_spin() {
  local pid="$1" msg="${2:-working}" frames='|/-\' i=0 rc
  if [[ "$MILI_COLORMODE" == none || ! -t 1 ]]; then
    wait "$pid" 2>/dev/null; return $?
  fi
  tput civis 2>/dev/null || true
  while kill -0 "$pid" 2>/dev/null; do
    printf '\r%s%s%s %s ' "$C_CYN" "${frames:i++%${#frames}:1}" "$C_RST" "$msg"
    sleep 0.1
  done
  wait "$pid" 2>/dev/null; rc=$?
  tput cnorm 2>/dev/null || true
  printf '\r\033[K'
  return $rc
}

ui_clear() { [[ -t 1 && "$MILI_COLORMODE" != none ]] && printf '\033[2J\033[H' || true; }

# ===== lib/log.sh =====
# shellcheck shell=bash
# mili :: log.sh - logging, error trap, die

MILI_LOGDIR="${MILI_LOGDIR:-/var/log/mili}"
MILI_LOGFILE="${MILI_LOGFILE:-$MILI_LOGDIR/mili.log}"

_log_write() {
  local lvl="$1"; shift
  local ts; ts=$(date '+%Y-%m-%d %H:%M:%S')
  # best-effort; never fail the caller because logging failed
  if [[ -d "$MILI_LOGDIR" ]] || mkdir -p "$MILI_LOGDIR" 2>/dev/null; then
    printf '%s [%s] %s\n' "$ts" "$lvl" "$*" >>"$MILI_LOGFILE" 2>/dev/null || true
  fi
}

log()  { _log_write INFO  "$*"; }
log_warn() { _log_write WARN "$*"; ui_warn "$*"; }
log_err()  { _log_write ERROR "$*"; ui_err  "$*" >&2; }
log_ok()   { _log_write INFO  "$*"; ui_ok   "$*"; }
log_info() { _log_write INFO  "$*"; ui_info "$*"; }

# die <msg> [code]
die() {
  local msg="$1" code="${2:-1}"
  _log_write FATAL "$msg"
  ui_err "$msg" >&2
  exit "$code"
}

# require_root - abort unless EUID 0
require_root() {
  [[ "${EUID:-$(id -u)}" -eq 0 ]] || die "mili must run as root (use sudo)." 1
}

# ERR trap installer (opt-in; interactive menus do NOT use set -e)
mili_trap_on() {
  set -o pipefail
  trap '_log_write ERROR "unexpected error at ${BASH_SOURCE[0]:-?}:${LINENO} (rc=$?) cmd: ${BASH_COMMAND}"' ERR
}

# ===== lib/sys.sh =====
# shellcheck shell=bash
# mili :: sys.sh - OS/arch detect, deps, network facts, run wrapper

# run <cmd...> : single choke point for system-changing commands.
# MILI_DRYRUN=1 -> print instead of execute (golden tests, previews).
run() {
  if [[ "${MILI_DRYRUN:-0}" == 1 ]]; then
    printf '%s[dry]%s %s\n' "${C_GRY:-}" "${C_RST:-}" "$*" >&2
    return 0
  fi
  _log_write CMD "$*"
  "$@"
}

# run_q <cmd...> : like run but swallow stdout/stderr (status still matters)
run_q() {
  if [[ "${MILI_DRYRUN:-0}" == 1 ]]; then
    printf '%s[dry]%s %s\n' "${C_GRY:-}" "${C_RST:-}" "$*" >&2
    return 0
  fi
  _log_write CMD "$*"
  "$@" >/dev/null 2>&1
}

sys_detect_os() {
  MILI_OS=unknown; MILI_OS_VER=0; MILI_OS_NAME=unknown
  if [[ -r /etc/os-release ]]; then
    # shellcheck disable=SC1091
    . /etc/os-release
    MILI_OS="${ID:-unknown}"
    MILI_OS_VER="${VERSION_ID:-0}"
    MILI_OS_NAME="${PRETTY_NAME:-$ID}"
  fi
}

# verify supported distro; returns 1 (warn) if not
sys_os_supported() {
  case "$MILI_OS" in
    ubuntu) awk "BEGIN{exit !(${MILI_OS_VER%%.*} >= 20)}" 2>/dev/null ;;
    debian) awk "BEGIN{exit !(${MILI_OS_VER%%.*} >= 11)}" 2>/dev/null ;;
    *) return 1 ;;
  esac
}

sys_detect_arch() {
  local m; m=$(uname -m)
  case "$m" in
    x86_64|amd64)  MILI_ARCH=amd64 ;;
    aarch64|arm64) MILI_ARCH=arm64 ;;
    armv7l|armv7|armhf) MILI_ARCH=armv7 ;;
    *) MILI_ARCH="$m" ;;
  esac
}

sys_has() { command -v "$1" >/dev/null 2>&1; }

# ensure apt packages installed (idempotent, batched)
sys_apt_ensure() {
  local pkgs=("$@") missing=()
  local p
  for p in "${pkgs[@]}"; do
    dpkg -s "$p" >/dev/null 2>&1 || missing+=("$p")
  done
  [[ ${#missing[@]} -eq 0 ]] && return 0
  ui_info "installing deps: ${missing[*]}"
  run env DEBIAN_FRONTEND=noninteractive apt-get update -qq || log_warn "apt-get update failed (continuing)"
  run env DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "${missing[@]}" \
    || die "failed to install packages: ${missing[*]}"
}

# ---- network facts ---------------------------------------------------------
sys_default_iface() {
  ip -4 route show default 2>/dev/null | awk '/default/{print $5; exit}'
}
sys_default_gw() {
  ip -4 route show default 2>/dev/null | awk '/default/{print $3; exit}'
}
sys_gw_mac() {
  local gw ifc; gw=$(sys_default_gw); ifc=$(sys_default_iface)
  [[ -z "$gw" ]] && return 1
  ping -c1 -W1 "$gw" >/dev/null 2>&1 || true
  ip neigh show "$gw" dev "$ifc" 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="lladdr") print $(i+1)}' | head -n1
}
sys_local_ip4() {
  local ifc; ifc=$(sys_default_iface)
  ip -4 addr show dev "$ifc" 2>/dev/null | awk '/inet /{sub(/\/.*/,"",$2); print $2; exit}'
}

# public IP; cached for the whole run (first call ~1-2s max, rest instant).
# Tries the fast local route hint first, then two quick HTTP resolvers.
sys_public_ip4() {
  [[ -n "${MILI_PUBIP4:-}" ]] && { printf '%s' "$MILI_PUBIP4"; return 0; }
  local urls=(https://api.ipify.org https://ipv4.icanhazip.com) u ip
  for u in "${urls[@]}"; do
    ip=$(curl -4 -fsS --connect-timeout 2 --max-time 3 "$u" 2>/dev/null | tr -d '[:space:]')
    [[ "$ip" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] && { MILI_PUBIP4="$ip"; printf '%s' "$ip"; return 0; }
  done
  ip="$(sys_local_ip4)"; MILI_PUBIP4="${ip:-unknown}"; printf '%s' "$MILI_PUBIP4"
}
# IPv6 is opt-in / lazy: single quick probe, cached. Empty if none.
sys_public_ip6() {
  [[ -n "${MILI_PUBIP6:-}" ]] && { printf '%s' "$MILI_PUBIP6"; [[ "$MILI_PUBIP6" == none ]] && return 1 || return 0; }
  local ip; ip=$(curl -6 -fsS --connect-timeout 2 --max-time 3 https://ipv6.icanhazip.com 2>/dev/null | tr -d '[:space:]')
  if [[ "$ip" == *:* ]]; then MILI_PUBIP6="$ip"; printf '%s' "$ip"; return 0; fi
  MILI_PUBIP6=none; return 1
}

# validate an IPv4 literal
sys_is_ip4() { [[ "$1" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; }
# validate hostname/domain (loose)
sys_is_host() { [[ "$1" =~ ^[a-zA-Z0-9]([a-zA-Z0-9.-]{0,251}[a-zA-Z0-9])?$ ]]; }

# random hex / token helpers
sys_rand_hex() { local n="${1:-8}"; head -c "$((n*2))" /dev/urandom 2>/dev/null | od -An -tx1 | tr -d ' \n' | cut -c1-"$((n*2))"; }
sys_rand_token() { tr -dc 'A-Za-z0-9' </dev/urandom 2>/dev/null | head -c "${1:-16}"; }
sys_rand_port() { local lo="${1:-20000}" hi="${2:-29999}"; echo $(( lo + RANDOM % (hi-lo+1) )); }

# ===== lib/state.sh =====
# shellcheck shell=bash
# mili :: state.sh - tunnel registry CRUD + type dispatcher
#
# Each tunnel is a flat key=value file: /etc/mili/tunnels/<name>.conf
# Values written with printf %q (safe to re-source). Loaded into assoc array ST.

MILI_ETC="${MILI_ETC:-/etc/mili}"
MILI_TUNDIR="${MILI_TUNDIR:-$MILI_ETC/tunnels}"
MILI_CONF="${MILI_CONF:-$MILI_ETC/mili.conf}"

declare -gA ST   # current loaded tunnel record

st_dir_init() {
  # mili's own dirs; creating them is benign and must succeed even in dry-run
  mkdir -p "$MILI_ETC" "$MILI_TUNDIR" "$MILI_ETC/engines" "$MILI_ETC/pki" "$MILI_ETC/backups" 2>/dev/null || true
  chmod 700 "$MILI_ETC" "$MILI_TUNDIR" "$MILI_ETC/pki" 2>/dev/null || true
}

# valid tunnel name: lowercase alnum, 1..10 chars (keeps iface names within IFNAMSIZ)
st_valid_name() { [[ "$1" =~ ^[a-z0-9]{1,10}$ ]]; }

st_exists() { [[ -f "$MILI_TUNDIR/$1.conf" ]]; }

# list all tunnel names
st_list() {
  [[ -d "$MILI_TUNDIR" ]] || return 0
  local f
  for f in "$MILI_TUNDIR"/*.conf; do
    [[ -e "$f" ]] || continue
    basename "$f" .conf
  done
}

st_count() { st_list | grep -c . ; }

# load <name> into ST assoc array
st_load() {
  local name="$1" f="$MILI_TUNDIR/$1.conf"
  [[ -f "$f" ]] || return 1
  ST=()
  local k v line
  while IFS= read -r line; do
    [[ "$line" =~ ^[[:space:]]*# ]] && continue
    [[ "$line" =~ ^([A-Za-z_][A-Za-z0-9_]*)=(.*)$ ]] || continue
    k="${BASH_REMATCH[1]}"; v="${BASH_REMATCH[2]}"
    # strip one layer of surrounding single quotes from printf %q output
    eval "v=$v" 2>/dev/null || v="${BASH_REMATCH[2]}"
    ST["$k"]="$v"
  done <"$f"
  ST[name]="$name"
  return 0
}

# save current ST array to disk (atomic)
st_save() {
  local name="${ST[name]:?st_save needs ST[name]}" f tmp
  st_valid_name "$name" || die "invalid tunnel name '$name'"
  st_dir_init
  f="$MILI_TUNDIR/$name.conf"
  tmp="$(mktemp "$MILI_TUNDIR/.$name.XXXXXX")" || die "mktemp failed"
  {
    printf '# mili tunnel record: %s\n' "$name"
    printf '# saved %s\n' "$(date -Iseconds 2>/dev/null || date)"
    local k
    for k in $(printf '%s\n' "${!ST[@]}" | sort); do
      printf '%s=%q\n' "$k" "${ST[$k]}"
    done
  } >"$tmp"
  run chmod 600 "$tmp" 2>/dev/null || true
  if [[ "${MILI_DRYRUN:-0}" == 1 ]]; then
    ui_info "[dry] would write $f"; cat "$tmp"; rm -f "$tmp"
  else
    mv -f "$tmp" "$f"
  fi
}

# get a field with default:  st_get <key> [default]
st_get() { local k="$1" d="${2:-}"; printf '%s' "${ST[$k]:-$d}"; }
st_set() { ST["$1"]="$2"; }

st_delete_file() {
  local name="$1"
  [[ -f "$MILI_TUNDIR/$name.conf" ]] && run rm -f "$MILI_TUNDIR/$name.conf"
}

# ---- type dispatcher -------------------------------------------------------
# All tunnel modules expose functions named t_<type>_<op>.
# t_has <type> <op> -> true if function defined.
t_has() { declare -F "t_$1_$2" >/dev/null 2>&1; }

# t_call <type> <op> [args...] ; fails loudly if missing
t_call() {
  local type="$1" op="$2"; shift 2
  if t_has "$type" "$op"; then
    "t_${type}_${op}" "$@"
  else
    die "tunnel type '$type' has no operation '$op'"
  fi
}

# registered tunnel types (populated by modules via t_register)
declare -ga MILI_TYPES=()
# t_register <type> ; modules call this at load
t_register() { MILI_TYPES+=("$1"); }

# resolve meta field:  t_meta_field <type> <field>
# modules' t_<type>_meta prints "key=value" lines.
t_meta_field() {
  local type="$1" field="$2"
  t_has "$type" meta || return 1
  "t_${type}_meta" | awk -F= -v k="$field" '$1==k{sub(/^[^=]*=/,""); print; exit}'
}

# ===== lib/sysctl.sh =====
# shellcheck shell=bash
# mili :: sysctl.sh - sysctl ONLY under /etc/sysctl.d/90-mili*.conf
# Never touches /etc/sysctl.conf or x-ui's 99-bbr-x-ui.conf.

MILI_SYSCTL_PORTS="/etc/sysctl.d/90-mili-ports.conf"
MILI_SYSCTL_FWD="/etc/sysctl.d/90-mili-forward.conf"
MILI_SYSCTL_TUNE="/etc/sysctl.d/91-mili-tune.conf"

_sysctl_reload() {
  if [[ -f "$1" ]]; then run sysctl -p "$1" >/dev/null 2>&1 || true; fi
}

# enable IPv4/IPv6 forwarding (needed for L3 exit / MASQUERADE / DNAT)
sysctl_enable_forward() {
  run bash -c "cat > '$MILI_SYSCTL_FWD' <<EOF
# mili: packet forwarding for tunnels (safe, additive)
net.ipv4.ip_forward = 1
net.ipv6.conf.all.forwarding = 1
EOF"
  _sysctl_reload "$MILI_SYSCTL_FWD"
}

# write reserved local ports so the kernel's ephemeral allocator never
# steals a mili port. $1 = comma list like "20000-20010,10801"
sysctl_set_reserved_ports() {
  local list="$1"
  if [[ -z "$list" ]]; then
    [[ -f "$MILI_SYSCTL_PORTS" ]] && run rm -f "$MILI_SYSCTL_PORTS"
    return 0
  fi
  run bash -c "cat > '$MILI_SYSCTL_PORTS' <<EOF
# mili: reserve tunnel ports from the ephemeral range (managed, do not edit)
net.ipv4.ip_local_reserved_ports = $list
EOF"
  _sysctl_reload "$MILI_SYSCTL_PORTS"
}

# per-interface rp_filter loosening (needed for asymmetric routing via tunnels)
# $1 = iface
sysctl_rpfilter_loose() {
  local ifc="$1"
  [[ -z "$ifc" ]] && return 0
  run sysctl -qw "net.ipv4.conf.$ifc.rp_filter=2" 2>/dev/null || true
  # persist additively in the forward file footer
  if [[ -f "$MILI_SYSCTL_FWD" ]] && ! grep -q "conf.$ifc.rp_filter" "$MILI_SYSCTL_FWD" 2>/dev/null; then
    run bash -c "printf 'net.ipv4.conf.%s.rp_filter = 2\n' '$ifc' >> '$MILI_SYSCTL_FWD'"
  fi
}

sysctl_remove_all() {
  run rm -f "$MILI_SYSCTL_PORTS" "$MILI_SYSCTL_FWD" "$MILI_SYSCTL_TUNE" 2>/dev/null || true
}

# ===== lib/ports.sh =====
# shellcheck shell=bash
# mili :: ports.sh - port registry, conflict detection, allocators,
#                    inner-subnet / gre-key / route-table pools.
#
# ports.db line format:  name|proto|port|bind
#   proto = tcp|udp|both ; bind = 127.0.0.1 | 0.0.0.0 | <inner-ip>

MILI_PORTSDB="${MILI_PORTSDB:-$MILI_ETC/ports.db}"

# pools
MILI_PUB_LO=20000; MILI_PUB_HI=29999      # public tunnel ports (below ephemeral)
MILI_SOCKS_LO=10800; MILI_SOCKS_HI=10999  # loopback SOCKS
MILI_INT_LO=30000; MILI_INT_HI=30999      # internal/helper ports
MILI_RESERVED=(22 53 80 443 2053 2096 62789 11111)  # 443 confirm-only

ports_db_init() { [[ -f "$MILI_PORTSDB" ]] || { st_dir_init; : >"$MILI_PORTSDB" 2>/dev/null || true; }; }

# ---- observation sources ---------------------------------------------------
# live listening ports (tcp+udp), one per line
ports_live() {
  if sys_has ss; then
    ss -Hlntu 2>/dev/null | awk '{print $5}' | sed -E 's/.*:([0-9]+)$/\1/' | grep -E '^[0-9]+$' | sort -un
  elif sys_has netstat; then
    netstat -lntu 2>/dev/null | awk '{print $4}' | sed -E 's/.*:([0-9]+)$/\1/' | grep -E '^[0-9]+$' | sort -un
  fi
}

# x-ui inbound ports (read-only sqlite) + panel/sub port (read-only CLI)
ports_xui() {
  local db=/etc/x-ui/x-ui.db
  if [[ -r "$db" ]] && sys_has sqlite3; then
    sqlite3 -readonly "$db" 'select port from inbounds;' 2>/dev/null | grep -E '^[0-9]+$'
  fi
  if [[ -x /usr/local/x-ui/x-ui ]]; then
    /usr/local/x-ui/x-ui setting -show true 2>/dev/null \
      | grep -iE 'port' | grep -oE '[0-9]{2,5}' || true
  fi
}

# sshd listening port(s)
ports_sshd() {
  if sys_has sshd; then
    sshd -T 2>/dev/null | awk '/^port /{print $2}'
  else
    awk '/^[[:space:]]*Port[[:space:]]+[0-9]+/{print $2}' /etc/ssh/sshd_config 2>/dev/null
  fi
  echo 22
}

# mili-claimed ports (all tunnels, incl. stopped)
ports_claimed() {
  [[ -f "$MILI_PORTSDB" ]] || return 0
  awk -F'|' 'NF>=3 && $3 ~ /^[0-9]+$/ {print $3}' "$MILI_PORTSDB" | sort -un
}

# claimed ports owned by a specific tunnel
ports_claimed_by() {
  [[ -f "$MILI_PORTSDB" ]] || return 0
  awk -F'|' -v n="$1" '$1==n{print}' "$MILI_PORTSDB"
}

# ---- conflict test ---------------------------------------------------------
# ports_in_use <port> [exclude-tunnel] -> 0 if used/unavailable
ports_in_use() {
  local port="$1" excl="${2:-}"
  local p
  for p in "${MILI_RESERVED[@]}"; do [[ "$p" == "$port" ]] && return 0; done
  ports_live   | grep -qx "$port" && return 0
  ports_xui    | grep -qx "$port" && return 0
  ports_sshd   | grep -qx "$port" && return 0
  # claimed by another tunnel?
  if [[ -f "$MILI_PORTSDB" ]]; then
    awk -F'|' -v pt="$port" -v ex="$excl" '$3==pt && $1!=ex{found=1} END{exit !found}' "$MILI_PORTSDB" && return 0
  fi
  return 1
}

# allocate a free port in a range:  ports_alloc <lo> <hi> [exclude]
ports_alloc() {
  local lo="$1" hi="$2" excl="${3:-}" p
  for (( p=lo; p<=hi; p++ )); do
    ports_in_use "$p" "$excl" || { printf '%s' "$p"; return 0; }
  done
  return 1
}
ports_alloc_public()   { ports_alloc "$MILI_PUB_LO"   "$MILI_PUB_HI"   "$1"; }
ports_alloc_socks()    { ports_alloc "$MILI_SOCKS_LO" "$MILI_SOCKS_HI" "$1"; }
ports_alloc_internal() { ports_alloc "$MILI_INT_LO"   "$MILI_INT_HI"   "$1"; }

# ---- claim / release -------------------------------------------------------
ports_claim() {   # <name> <proto> <port> <bind>
  ports_db_init
  local name="$1" proto="$2" port="$3" bind="${4:-0.0.0.0}"
  ports_release_one "$name" "$port"
  printf '%s|%s|%s|%s\n' "$name" "$proto" "$port" "$bind" >>"$MILI_PORTSDB"
  ports_sync_reserved
}
ports_release() {  # <name> : drop all claims for a tunnel
  [[ -f "$MILI_PORTSDB" ]] || return 0
  local name="$1" tmp; tmp="$(mktemp)"
  awk -F'|' -v n="$name" '$1!=n' "$MILI_PORTSDB" >"$tmp" && mv -f "$tmp" "$MILI_PORTSDB"
  ports_sync_reserved
}
ports_release_one() {  # <name> <port>
  [[ -f "$MILI_PORTSDB" ]] || return 0
  local name="$1" port="$2" tmp; tmp="$(mktemp)"
  awk -F'|' -v n="$name" -v pt="$port" '!($1==n && $3==pt)' "$MILI_PORTSDB" >"$tmp" && mv -f "$tmp" "$MILI_PORTSDB"
}

# write reserved-ports sysctl from all public/internal claims (not loopback)
ports_sync_reserved() {
  [[ -f "$MILI_PORTSDB" ]] || return 0
  local list
  list=$(awk -F'|' '$4!="127.0.0.1" && $3 ~ /^[0-9]+$/ {print $3}' "$MILI_PORTSDB" | sort -un | paste -sd, -)
  sysctl_set_reserved_ports "$list"
}

# ---- audit: later clashes (user added x-ui inbound on a mili port, etc.) ---
# prints conflict lines; returns 1 if any found
ports_audit() {
  ports_db_init
  local rc=0 line name proto port bind
  local live xui
  live=$(ports_live); xui=$(ports_xui)
  while IFS='|' read -r name proto port bind; do
    [[ "$port" =~ ^[0-9]+$ ]] || continue
    # is a NON-mili listener occupying our public port?
    if [[ "$bind" != "127.0.0.1" ]] && grep -qx "$port" <<<"$xui"; then
      printf '%sCONFLICT%s port %s claimed by tunnel %s also used by x-ui inbound\n' \
        "${C_RED:-}" "${C_RST:-}" "$port" "$name"
      rc=1
    fi
  done < <(cat "$MILI_PORTSDB" 2>/dev/null)
  return $rc
}

# ---- inner subnet / gre key / route table / iface pools --------------------
# inner /30 blocks from 10.77.N.0/30 ; returns next free "10.77.N" base
pool_inner_subnet() {
  local used n base
  used=$(awk -F'|' '/^INNER/{print $2}' "$MILI_PORTSDB" 2>/dev/null)
  for (( n=0; n<=255; n++ )); do
    base="10.77.$n"
    grep -qx "$n" <<<"$used" && continue
    # also skip if that subnet is already routed on the host
    if ! ip route 2>/dev/null | grep -q "$base\." && ! ip addr 2>/dev/null | grep -q "$base\."; then
      printf '%s' "$n"; return 0
    fi
  done
  return 1
}
pool_inner_claim()  { ports_db_init; printf 'INNER|%s|%s\n' "$1" "$2" >>"$MILI_PORTSDB"; }   # <N> <name>
pool_inner_release(){ local tmp; tmp="$(mktemp)"; awk -F'|' -v n="$1" '!(/^INNER/ && $3==n)' "$MILI_PORTSDB" >"$tmp" && mv -f "$tmp" "$MILI_PORTSDB"; }

# unique gre key (uint32)
pool_gre_key() {
  local used k
  used=$(grep -E '^GREKEY' "$MILI_PORTSDB" 2>/dev/null | awk -F'|' '{print $2}')
  for k in $(seq 1 65535); do grep -qx "$k" <<<"$used" || { printf '%s' "$k"; return 0; }; done
}
# unique route table id in 7700..7799
pool_table_id() {
  local used t
  used=$(grep -E '^RTABLE' "$MILI_PORTSDB" 2>/dev/null | awk -F'|' '{print $2}')
  for (( t=7700; t<=7799; t++ )); do grep -qx "$t" <<<"$used" || { printf '%s' "$t"; return 0; }; done
}
pool_meta_claim()  { ports_db_init; printf '%s|%s|%s\n' "$1" "$2" "$3" >>"$MILI_PORTSDB"; }  # <KIND> <val> <name>
pool_meta_release(){ local tmp; tmp="$(mktemp)"; awk -F'|' -v n="$1" '!($3==n && ($1=="GREKEY"||$1=="RTABLE"||$1=="INNER"))' "$MILI_PORTSDB" >"$tmp" && mv -f "$tmp" "$MILI_PORTSDB"; }

# ===== lib/fw.sh =====
# shellcheck shell=bash
# mili :: fw.sh - own iptables/ip6tables chains. NEVER flush, NEVER change policy.
# All rules tagged with -m comment --comment "mili:<name>" for clean removal.
# Guarantee = jump to MILI-IN inserted at top of INPUT. ufw/firewalld mirrored.

FW_TAGPFX="mili"

_ipt()  { run iptables  "$@"; }
_ipt6() { run ip6tables "$@"; }
# quiet check variants (status matters, output not)
_iptq()  { iptables  "$@" >/dev/null 2>&1; }
_ipt6q() { ip6tables "$@" >/dev/null 2>&1; }

# create our chains if absent and hook them (idempotent)
fw_init() {
  sys_has iptables || sys_apt_ensure iptables
  local t chain
  # filter
  for chain in MILI-IN; do
    _iptq -t filter -nL "$chain" || _ipt -t filter -N "$chain"
    _ipt6q -t filter -nL "$chain" || _ipt6 -t filter -N "$chain"
  done
  # nat
  for chain in MILI-PRE MILI-POST; do
    _iptq -t nat -nL "$chain" || _ipt -t nat -N "$chain"
    _ipt6q -t nat -nL "$chain" || _ipt6 -t nat -N "$chain"
  done
  # mangle (MSS clamp + paqet out), raw (paqet notrack)
  for chain in MILI-MSS MILI-OUT; do
    _iptq -t mangle -nL "$chain" || _ipt -t mangle -N "$chain"
    _ipt6q -t mangle -nL "$chain" || _ipt6 -t mangle -N "$chain"
  done
  _iptq -t raw -nL MILI-RAW || _ipt -t raw -N MILI-RAW
  _ipt6q -t raw -nL MILI-RAW || _ipt6 -t raw -N MILI-RAW
  fw_rehook
}

# ensure jump rules reference our chains (re-inserted if missing)
fw_rehook() {
  # filter INPUT -> MILI-IN at position 1
  _iptq  -t filter -C INPUT -j MILI-IN || _ipt  -t filter -I INPUT 1 -j MILI-IN
  _ipt6q -t filter -C INPUT -j MILI-IN || _ipt6 -t filter -I INPUT 1 -j MILI-IN
  # nat PREROUTING/POSTROUTING
  _iptq  -t nat -C PREROUTING  -j MILI-PRE  || _ipt  -t nat -I PREROUTING 1 -j MILI-PRE
  _ipt6q -t nat -C PREROUTING  -j MILI-PRE  || _ipt6 -t nat -I PREROUTING 1 -j MILI-PRE
  _iptq  -t nat -C POSTROUTING -j MILI-POST || _ipt  -t nat -I POSTROUTING 1 -j MILI-POST
  _ipt6q -t nat -C POSTROUTING -j MILI-POST || _ipt6 -t nat -I POSTROUTING 1 -j MILI-POST
  # mangle FORWARD -> MSS clamp
  _iptq  -t mangle -C FORWARD -j MILI-MSS || _ipt  -t mangle -I FORWARD 1 -j MILI-MSS
  _ipt6q -t mangle -C FORWARD -j MILI-MSS || _ipt6 -t mangle -I FORWARD 1 -j MILI-MSS
  # raw PREROUTING -> MILI-RAW  (paqet NOTRACK)
  _iptq  -t raw -C PREROUTING -j MILI-RAW || _ipt  -t raw -I PREROUTING 1 -j MILI-RAW
  # mangle OUTPUT -> MILI-OUT (paqet RST drop)
  _iptq  -t mangle -C OUTPUT -j MILI-OUT || _ipt -t mangle -I OUTPUT 1 -j MILI-OUT
}

# add a filter ACCEPT:  fw_allow <name> <proto> <port|range> [src]
fw_allow() {
  local name="$1" proto="$2" port="$3" src="${4:-}" tag="$FW_TAGPFX:$1"
  local -a a=(-t filter -A MILI-IN -p "$proto")
  [[ -n "$src" && "$src" != any ]] && a+=(-s "$src")
  [[ -n "$port" && "$port" != - ]] && a+=(--dport "$port")
  a+=(-m comment --comment "$tag" -j ACCEPT)
  _iptq -t filter -C MILI-IN -p "$proto" ${src:+-s "$src"} ${port:+--dport "$port"} -m comment --comment "$tag" -j ACCEPT \
    || _ipt "${a[@]}"
}

# allow GRE (proto 47) / FOU udp from a specific peer
fw_allow_proto() {  # <name> <protonum> <src>
  local name="$1" protonum="$2" src="$3" tag="$FW_TAGPFX:$1"
  _iptq -t filter -C MILI-IN -p "$protonum" -s "$src" -m comment --comment "$tag" -j ACCEPT \
    || _ipt -t filter -A MILI-IN -p "$protonum" -s "$src" -m comment --comment "$tag" -j ACCEPT
}

# DNAT a local public port to a remote target:  fw_dnat <name> <proto> <lport> <dst-ip> <dport>
fw_dnat() {
  local name="$1" proto="$2" lport="$3" dip="$4" dport="$5" tag="$FW_TAGPFX:$1"
  _iptq -t nat -C MILI-PRE -p "$proto" --dport "$lport" -m comment --comment "$tag" -j DNAT --to-destination "$dip:$dport" \
    || _ipt -t nat -A MILI-PRE -p "$proto" --dport "$lport" -m comment --comment "$tag" -j DNAT --to-destination "$dip:$dport"
  _iptq -t nat -C MILI-POST -p "$proto" -d "$dip" --dport "$dport" -m comment --comment "$tag" -j MASQUERADE \
    || _ipt -t nat -A MILI-POST -p "$proto" -d "$dip" --dport "$dport" -m comment --comment "$tag" -j MASQUERADE
}

# MASQUERADE an inner subnet out the default iface (L3 exit, foreign side)
fw_masq() {  # <name> <cidr>
  local name="$1" cidr="$2" tag="$FW_TAGPFX:$1"
  _iptq -t nat -C MILI-POST -s "$cidr" -m comment --comment "$tag" -j MASQUERADE \
    || _ipt -t nat -A MILI-POST -s "$cidr" -m comment --comment "$tag" -j MASQUERADE
}

# MSS clamp on a tunnel iface
fw_mss() {  # <name> <iface> [mss|pmtu]
  local name="$1" ifc="$2" mss="${3:-pmtu}" tag="$FW_TAGPFX:$1"
  local setspec=(--clamp-mss-to-pmtu)
  [[ "$mss" != pmtu ]] && setspec=(--set-mss "$mss")
  _iptq -t mangle -C MILI-MSS -o "$ifc" -p tcp --tcp-flags SYN,RST SYN -j TCPMSS "${setspec[@]}" \
    || _ipt -t mangle -A MILI-MSS -o "$ifc" -p tcp --tcp-flags SYN,RST SYN -j TCPMSS "${setspec[@]}"
}

# loopback guard for a SOCKS port an engine binds on 0.0.0.0 but should be local
fw_loopback_guard() {  # <name> <proto> <port>
  local name="$1" proto="$2" port="$3" tag="$FW_TAGPFX:$1"
  _iptq -t filter -C MILI-IN -p "$proto" --dport "$port" ! -i lo -m comment --comment "$tag" -j DROP \
    || _ipt -t filter -A MILI-IN -p "$proto" --dport "$port" ! -i lo -m comment --comment "$tag" -j DROP
}

# paqet: NOTRACK a raw-socket port so conntrack doesn't interfere
fw_raw_notrack() {  # <name> <proto> <port>
  local name="$1" proto="$2" port="$3" tag="$FW_TAGPFX:$1"
  _iptq -t raw -C MILI-RAW -p "$proto" --dport "$port" -m comment --comment "$tag" -j NOTRACK \
    || _ipt -t raw -A MILI-RAW -p "$proto" --dport "$port" -m comment --comment "$tag" -j NOTRACK
  _iptq -t raw -C MILI-RAW -p "$proto" --sport "$port" -m comment --comment "$tag" -j NOTRACK \
    || _ipt -t raw -A MILI-RAW -p "$proto" --sport "$port" -m comment --comment "$tag" -j NOTRACK
}

# paqet: drop kernel-generated RST for a tcp port (userspace owns the flow)
fw_drop_rst() {  # <name> <port>
  local name="$1" port="$2" tag="$FW_TAGPFX:$1"
  _iptq -t mangle -C MILI-OUT -p tcp --sport "$port" --tcp-flags RST RST -m comment --comment "$tag" -j DROP \
    || _ipt -t mangle -A MILI-OUT -p tcp --sport "$port" --tcp-flags RST RST -m comment --comment "$tag" -j DROP
}

# delete every rule tagged mili:<name> across all our chains (v4+v6)
fw_remove() {
  local name="$1" tag="$FW_TAGPFX:$1" table chain line
  for table in filter nat mangle raw; do
    for chain in MILI-IN MILI-PRE MILI-POST MILI-MSS MILI-OUT MILI-RAW; do
      _iptq -t "$table" -nL "$chain" || continue
      # repeatedly delete matching rules by spec
      while iptables -t "$table" -S "$chain" 2>/dev/null | grep -q "comment \"$tag\""; do
        line=$(iptables -t "$table" -S "$chain" 2>/dev/null | grep -m1 "comment \"$tag\"" | sed 's/^-A /-D /')
        # shellcheck disable=SC2086
        _ipt -t "$table" $line || break
      done
      while ip6tables -t "$table" -S "$chain" 2>/dev/null | grep -q "comment \"$tag\""; do
        line=$(ip6tables -t "$table" -S "$chain" 2>/dev/null | grep -m1 "comment \"$tag\"" | sed 's/^-A /-D /')
        # shellcheck disable=SC2086
        _ipt6 -t "$table" $line || break
      done
    done
  done
  fw_ufw_remove "$name"
}

# wipe all mili chains entirely (uninstall)
fw_teardown() {
  local table chain
  # unhook jumps first
  _iptq  -t filter -D INPUT -j MILI-IN; _ipt6q -t filter -D INPUT -j MILI-IN
  _iptq  -t nat -D PREROUTING -j MILI-PRE; _ipt6q -t nat -D PREROUTING -j MILI-PRE
  _iptq  -t nat -D POSTROUTING -j MILI-POST; _ipt6q -t nat -D POSTROUTING -j MILI-POST
  _iptq  -t mangle -D FORWARD -j MILI-MSS; _ipt6q -t mangle -D FORWARD -j MILI-MSS
  _iptq  -t raw -D PREROUTING -j MILI-RAW
  _iptq  -t mangle -D OUTPUT -j MILI-OUT
  for table in filter nat mangle raw; do
    for chain in MILI-IN MILI-PRE MILI-POST MILI-MSS MILI-OUT MILI-RAW; do
      _iptq  -t "$table" -F "$chain"; _iptq  -t "$table" -X "$chain"
      _ipt6q -t "$table" -F "$chain"; _ipt6q -t "$table" -X "$chain"
    done
  done
}

# ---- ufw / firewalld mirror (so later "enable ufw" doesn't kill tunnels) ---
fw_ufw_mirror() {  # <name> <proto> <port> [src]
  sys_has ufw || return 0
  local name="$1" proto="$2" port="$3" src="${4:-}"
  local cmt="mili:$name"
  if [[ -n "$src" && "$src" != any ]]; then
    run ufw allow from "$src" to any port "$port" proto "$proto" comment "$cmt" >/dev/null 2>&1 || true
  else
    run ufw allow "$port/$proto" comment "$cmt" >/dev/null 2>&1 || true
  fi
}
fw_ufw_allow_gre() {  # <name> <peer>
  sys_has ufw || return 0
  run ufw allow proto gre from "$2" comment "mili:$1" >/dev/null 2>&1 || true
}
fw_ufw_remove() {  # <name> : best-effort remove ufw rules we added
  sys_has ufw || return 0
  local name="$1" num
  # delete by matching comment, highest rule number first
  while read -r num; do
    [[ -n "$num" ]] && run bash -c "yes | ufw delete $num" >/dev/null 2>&1 || true
  done < <(ufw status numbered 2>/dev/null | grep "mili:$name" | grep -oE '^\[[ ]*[0-9]+\]' | grep -oE '[0-9]+' | sort -rn)
}

# ===== lib/svc.sh =====
# shellcheck shell=bash
# mili :: svc.sh - systemd units. Template units installed once; instances
# enabled per tunnel. All names mili-* (never collide with x-ui).

MILI_UNITDIR="/etc/systemd/system"
MILI_BIN="/usr/local/bin/mili"

_svc_reload() { run systemctl daemon-reload; }

# write a unit file only if content changed
svc_write_unit() {  # <unit-filename> <content>
  local name="$1" content="$2" path="$MILI_UNITDIR/$1"
  if [[ -f "$path" ]] && [[ "$(cat "$path" 2>/dev/null)" == "$content" ]]; then
    return 0
  fi
  if [[ "${MILI_DRYRUN:-0}" == 1 ]]; then
    ui_info "[dry] would write unit $path"; printf '%s\n' "$content"; return 0
  fi
  printf '%s\n' "$content" >"$path"
  _svc_reload
}

# install all template units (idempotent). ExecStart uses a per-type launcher
# script that mili renders into /etc/mili/engines. For engine daemons we point
# at the installed core via /opt/mili/bin symlinks.
svc_install_templates() {
  # Restart*/limits live in [Service]; StartLimitIntervalSec belongs in [Unit].
  local common="Restart=always
RestartSec=3
LimitNOFILE=1048576"

  # generic engine template: mili-<engine>@<name>
  # launched via: mili _svc <engine> <name>  (reads config, execs core)
  local engines=(frps frpc backhaul paqet rathole hy2 singbox gost socks)
  local e
  for e in "${engines[@]}"; do
    svc_write_unit "mili-$e@.service" "[Unit]
Description=mili $e tunnel instance %i
After=network-online.target mili-fw.service
Wants=network-online.target
StartLimitIntervalSec=0

[Service]
Type=simple
ExecStart=$MILI_BIN _svc $e %i
$common

[Install]
WantedBy=multi-user.target"
  done

  # L3 oneshot (GRE / WG up & down)
  svc_write_unit "mili-l3@.service" "[Unit]
Description=mili L3 tunnel %i
After=network-online.target mili-fw.service
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=$MILI_BIN _l3 up %i
ExecStop=$MILI_BIN _l3 down %i

[Install]
WantedBy=multi-user.target"

  # NOTE: Hedioum is NOT run by a mili unit. The hedioum-tunnel binary installs
  # and manages its own `hedioum.service`; mili drives it via its CLI.
  # Clean up the deprecated singleton unit from older builds, if present.
  if [[ -f "$MILI_UNITDIR/mili-hedioum.service" ]]; then
    run systemctl disable --now mili-hedioum.service >/dev/null 2>&1 || true
    run rm -f "$MILI_UNITDIR/mili-hedioum.service"
    _svc_reload
  fi

  # firewall restore at boot (rebuilds chains from state)
  svc_write_unit "mili-fw.service" "[Unit]
Description=mili firewall chains restore
After=network-online.target ufw.service firewalld.service
Wants=network-online.target
Before=mili-l3@.service

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=$MILI_BIN _fw-restore

[Install]
WantedBy=multi-user.target"

  # watchdog service + timer
  svc_write_unit "mili-watchdog.service" "[Unit]
Description=mili watchdog (health, self-heal, port audit)
After=network-online.target

[Service]
Type=oneshot
ExecStart=$MILI_BIN _watchdog"

  svc_write_unit "mili-watchdog.timer" "[Unit]
Description=mili watchdog timer

[Timer]
OnBootSec=60
OnUnitActiveSec=60
AccuracySec=10

[Install]
WantedBy=timers.target"

  run systemctl enable --now mili-fw.service       >/dev/null 2>&1 || true
  run systemctl enable --now mili-watchdog.timer   >/dev/null 2>&1 || true
}

# instance control helpers
svc_unit_for() {  # <engine> <name> -> unit string
  printf 'mili-%s@%s.service' "$1" "$2"
}
svc_enable()  { run systemctl enable  "$1" >/dev/null 2>&1 || true; }
svc_start()   { run systemctl start   "$1"; }
svc_stop()    { run systemctl stop    "$1" 2>/dev/null || true; }
svc_restart() { run systemctl restart "$1"; }
svc_disable() { run systemctl disable "$1" >/dev/null 2>&1 || true; }
svc_up()      { svc_enable "$1"; svc_start "$1"; }
svc_down()    { svc_stop "$1"; svc_disable "$1"; }
svc_active()  { systemctl is-active --quiet "$1"; }
svc_status()  { systemctl is-active "$1" 2>/dev/null || echo inactive; }
svc_logs()    { run journalctl -u "$1" -n "${2:-80}" --no-pager; }
svc_logs_follow() { journalctl -u "$1" -f --no-pager; }

# ===== lib/features.sh =====
# shellcheck shell=bash
# mili :: features.sh - feature registry with free/premium tiers + license stub.
# v1: everything free. Flipping a feature to premium = one line in a module.

MILI_LICENSE="${MILI_LICENSE:-$MILI_ETC/license}"
declare -gA FEAT_TIER=()   # id -> free|premium

feature() { FEAT_TIER["$1"]="${2:-free}"; }   # register

# is the premium license valid? (stub -> always false until real impl)
license_valid() {
  [[ -r "$MILI_LICENSE" ]] || return 1
  # future: verify signature / expiry. For now any non-empty file != valid.
  return 1
}

mili_edition() { license_valid && echo "Premium" || echo "Free"; }

mili_edition_badge() {
  if license_valid; then
    ui_badge "PREMIUM" "$C_YEL"
  else
    ui_badge "FREE" "$C_TEAL"
  fi
}

# feature_gate <id> : 0 if allowed, else prints notice and returns 1
feature_gate() {
  local id="$1" tier="${FEAT_TIER[$1]:-free}"
  [[ "$tier" == free ]] && return 0
  license_valid && return 0
  ui_warn "'$id' is a Premium feature - coming soon."
  return 1
}

feature_is_premium() { [[ "${FEAT_TIER[$1]:-free}" == premium ]]; }

# ===== lib/fetch.sh =====
# shellcheck shell=bash
# mili :: fetch.sh - multi-source downloader + checksum verify + bundle + peer.
#
# Source chain (order from settings, default below):
#   github -> github proxy prefixes -> MILI_MIRROR -> custom URL -> local -> peer
# Each core manifest supplies a github asset URL; this layer tries alternatives.

MILI_CACHE="${MILI_CACHE:-$MILI_ETC/cache}"
# editable in settings; space-separated prefixes prepended to a github URL
MILI_GH_PROXIES="${MILI_GH_PROXIES:-https://ghproxy.net/ https://mirror.ghproxy.com/ https://gh-proxy.com/}"
MILI_MIRROR="${MILI_MIRROR:-}"          # user's own releases base (placeholder)
MILI_LOCAL_DIR="${MILI_LOCAL_DIR:-$MILI_ETC/offline}"

_dl() {  # <url> <out> -> 0 on success
  local url="$1" out="$2"
  # short, bounded: a dead/404 source fails fast instead of hanging minutes
  curl -fL --connect-timeout 8 --max-time 90 --retry 1 --retry-max-time 20 -o "$out" "$url" 2>/dev/null
}

# fetch_url <github-url> <out> : try chain until one works
fetch_url() {
  local ghurl="$1" out="$2" base name p
  name="$(basename "$ghurl")"
  mkdir -p "$(dirname "$out")" 2>/dev/null || true

  ui_info "fetching $name"
  # 1. direct github
  _dl "$ghurl" "$out" && { ui_ok "got $name (github)"; return 0; }
  # 2. github proxies
  for p in $MILI_GH_PROXIES; do
    _dl "${p}${ghurl}" "$out" && { ui_ok "got $name (proxy ${p%%/*})"; return 0; }
  done
  # 3. own mirror
  if [[ -n "$MILI_MIRROR" ]]; then
    _dl "${MILI_MIRROR%/}/$name" "$out" && { ui_ok "got $name (mirror)"; return 0; }
  fi
  # 4. local offline dir
  if [[ -f "$MILI_LOCAL_DIR/$name" ]]; then
    cp -f "$MILI_LOCAL_DIR/$name" "$out" && { ui_ok "got $name (offline)"; return 0; }
  fi
  ui_err "all sources failed for $name"
  return 1
}

# fetch with explicit custom URL override
fetch_custom() { _dl "$1" "$2" && ui_ok "got $(basename "$2") (custom url)"; }

# verify_sha256 <file> <expected-hex>  ('' or 'skip' = skip)
verify_sha256() {
  local file="$1" want="$2" got
  [[ -z "$want" || "$want" == skip ]] && { ui_note "checksum skipped for $(basename "$file")"; return 0; }
  got=$(sha256sum "$file" 2>/dev/null | awk '{print $1}')
  if [[ "$got" == "$want" ]]; then ui_ok "sha256 verified"; return 0; fi
  ui_err "sha256 mismatch for $(basename "$file")"
  ui_note "want $want"
  ui_note "got  $got"
  return 1
}

# ---- offline bundle --------------------------------------------------------
# bundle every installed core into a tar for air-gapped transfer
fetch_bundle() {  # [out.tar.gz]
  local out="${1:-/root/mili-cores-$(date +%Y%m%d).tar.gz}"
  [[ -d /opt/mili/bin ]] || { ui_err "no cores installed"; return 1; }
  run tar -czf "$out" -C /opt/mili bin store && ui_ok "bundle -> $out"
}
fetch_bundle_import() {  # <tar.gz>
  local tar="$1"
  [[ -f "$tar" ]] || { ui_err "no such file: $tar"; return 1; }
  run mkdir -p /opt/mili
  run tar -xzf "$tar" -C /opt/mili && ui_ok "cores imported from $tar"
}

# ---- peer serve / pull (polished in pass 2; basic path here) ---------------
# foreign: serve /opt/mili/bin over a temporary authenticated http (gost);
# prints a mili-cores: code. iran: pull by code. Requires gost core present.
fetch_peer_serve() {
  local port user pass code gost=/opt/mili/bin/gost
  [[ -x "$gost" ]] || { ui_warn "gost core required for peer serve (install in Cores menu)"; return 1; }
  port=$(ports_alloc_internal) || { ui_err "no free port"; return 1; }
  user=mili; pass=$(sys_rand_token 20)
  ui_info "serving /opt/mili/bin on :$port for 10 minutes"
  fw_allow "coreserve" tcp "$port"
  ( "$gost" -L "http://$user:$pass@0.0.0.0:$port/?dir=/opt/mili/bin" >/dev/null 2>&1 &
    local sp=$!; sleep 600; kill "$sp" 2>/dev/null ) &
  code=$(printf 'mili-cores:%s|%s|%s|%s' "$(sys_public_ip4)" "$port" "$user" "$pass" | base64 -w0 2>/dev/null || \
         printf 'mili-cores:%s|%s|%s|%s' "$(sys_public_ip4)" "$port" "$user" "$pass" | base64)
  echo
  ui_ok "share this pull code (valid 10 min):"
  printf '  %s%s%s\n' "$C_YEL" "$code" "$C_RST"
}
fetch_peer_pull() {  # <code>
  local code="${1#mili-cores:}" dec ip port user pass
  dec=$(printf '%s' "${1#mili-cores:}" | base64 -d 2>/dev/null) || dec="$1"
  IFS='|' read -r ip port user pass <<<"${dec#mili-cores:}"
  [[ -n "$ip" && -n "$port" ]] || { ui_err "bad pull code"; return 1; }
  ui_info "pulling cores from $ip:$port"
  run mkdir -p /opt/mili/bin
  curl -fsSL "http://$user:$pass@$ip:$port/" 2>/dev/null | grep -oE 'href="[^"]+"' | sed 's/href="//;s/"//' \
    | while read -r item; do
        [[ "$item" == ../ || -z "$item" ]] && continue
        curl -fsSL "http://$user:$pass@$ip:$port/$item" -o "/opt/mili/bin/$item" 2>/dev/null && ui_ok "pulled $item"
      done
}

# ===== lib/cores.sh =====
# shellcheck shell=bash
# mili :: cores.sh - core binary manifest + install / update / rollback.
#
# Layout:  /opt/mili/bin/<core>/<ver>/<binary>   (versioned)
#          /opt/mili/bin/<core>  -> symlink to active binary (rollback = repoint)
# Manifest fields resolved per core + arch. Versions are PINNED & tested.
# NOTE: asset-name patterns flagged "verify" in the plan are confirmed at
# install time by the multi-source fetcher; adjust here if upstream renames.

MILI_OPT="/opt/mili"
MILI_COREBIN="$MILI_OPT/bin"      # symlinks ONLY (one per binary)
MILI_STORE="$MILI_OPT/store"      # versioned binaries: store/<core>/<ver>/<bin>

# cores_manifest <core> -> prints: VER REPO ASSET ARCHMAP EXTRACT BINARIES
# ASSET uses %V (version without v) and %A (mapped arch). BINARIES space list.
cores_version() {
  case "$1" in
    frp)      echo "0.71.1" ;;
    backhaul) echo "0.7.2" ;;
    paqet)    echo "1.0.0-alpha.21" ;;
    hedioum)  echo "0.11.0" ;;
    gost)     echo "3.3.0" ;;
    rathole)  echo "0.5.0" ;;
    hysteria) echo "2.13.0" ;;
    singbox)  echo "1.10.3" ;;
    *) return 1 ;;
  esac
}

# map mili arch -> core-specific arch token
_core_arch() {  # <core> <miliarch>
  local core="$1" a="$2"
  case "$core" in
    frp|gost|hysteria|singbox|paqet)
      case "$a" in amd64) echo amd64;; arm64) echo arm64;; armv7) echo arm;; *) echo "$a";; esac ;;
    backhaul)
      case "$a" in amd64) echo amd64;; arm64) echo arm64;; *) echo "$a";; esac ;;
    rathole)
      case "$a" in amd64) echo x86_64;; arm64) echo aarch64;; armv7) echo armv7;; *) echo "$a";; esac ;;
    *) echo "$a" ;;
  esac
}

# download URL (github) for a core
cores_url() {  # <core>
  local core="$1" v a; v=$(cores_version "$core") || return 1
  a=$(_core_arch "$core" "$MILI_ARCH")
  case "$core" in
    frp)      echo "https://github.com/fatedier/frp/releases/download/v$v/frp_${v}_linux_${a}.tar.gz" ;;
    backhaul) echo "https://github.com/Musixal/Backhaul/releases/download/v$v/backhaul_linux_${a}.tar.gz" ;;
    gost)     echo "https://github.com/go-gost/gost/releases/download/v$v/gost_${v}_linux_${a}.tar.gz" ;;
    paqet)    echo "https://github.com/hanselime/paqet/releases/download/v$v/paqet_linux_${a}.tar.gz" ;;
    hedioum)  # raw binaries (no archive): amd64='hedioum-tunnel', else suffixed
              case "$MILI_ARCH" in
                amd64) echo "https://github.com/hedioum/Hedioum-Pool-Tunnel/releases/download/v$v/hedioum-tunnel" ;;
                arm64) echo "https://github.com/hedioum/Hedioum-Pool-Tunnel/releases/download/v$v/hedioum-tunnel-arm64" ;;
                armv7) echo "https://github.com/hedioum/Hedioum-Pool-Tunnel/releases/download/v$v/hedioum-tunnel-armv7" ;;
                *) echo "https://github.com/hedioum/Hedioum-Pool-Tunnel/releases/download/v$v/hedioum-tunnel" ;;
              esac ;;
    rathole)  echo "https://github.com/rapiz1/rathole/releases/download/v$v/rathole-${a}-unknown-linux-musl.zip" ;;
    hysteria) echo "https://github.com/apernet/hysteria/releases/download/app/v$v/hysteria-linux-${a}" ;;
    singbox)  echo "https://github.com/SagerNet/sing-box/releases/download/v$v/sing-box-${v}-linux-${a}.tar.gz" ;;
    *) return 1 ;;
  esac
}

# binaries produced by a core and their final symlink names
cores_binaries() {  # <core>
  case "$1" in
    frp)      echo "frps frpc" ;;
    backhaul) echo "backhaul" ;;
    gost)     echo "gost" ;;
    paqet)    echo "paqet" ;;
    hedioum)  echo "hedioum-tunnel" ;;
    rathole)  echo "rathole" ;;
    hysteria) echo "hysteria" ;;
    singbox)  echo "sing-box" ;;
    *) return 1 ;;
  esac
}

cores_installed_version() {  # <core> -> prints installed ver or empty
  local core="$1" first link
  first=$(cores_binaries "$core" | awk '{print $1}')
  link="$MILI_COREBIN/$first"
  [[ -L "$link" ]] || return 1
  readlink "$link" 2>/dev/null | sed -E "s#.*/store/$core/([^/]+)/.*#\1#"
}

cores_is_installed() {  # <core>
  local first; first=$(cores_binaries "$1" | awk '{print $1}')
  [[ -x "$MILI_COREBIN/$first" ]]
}

# install (or reinstall) a core at its pinned version.
# Versioned binaries live in store/<core>/<ver>/; symlinks go in bin/ (never
# collide, even when the binary name equals the core name, e.g. gost/backhaul).
cores_install() {  # <core>
  local core="$1" v url bins b dst tmp f found
  v=$(cores_version "$core") || { ui_err "unknown core: $core"; return 1; }
  url=$(cores_url "$core")   || { ui_err "no url for: $core"; return 1; }
  bins=$(cores_binaries "$core")
  dst="$MILI_STORE/$core/$v"
  mkdir -p "$dst" "$MILI_COREBIN"
  tmp="$(mktemp -d)"; f="$tmp/dl_$(basename "$url")"

  fetch_url "$url" "$f" || { rm -rf "$tmp"; return 1; }

  case "$f" in
    *.tar.gz|*.tgz) tar -xzf "$f" -C "$tmp" 2>/dev/null || { ui_err "extract failed"; rm -rf "$tmp"; return 1; } ;;
    *.zip)          unzip -oq "$f" -d "$tmp" 2>/dev/null || { ui_err "unzip failed"; rm -rf "$tmp"; return 1; } ;;
    *)              cp -f "$f" "$tmp/$(echo "$bins" | awk '{print $1}')" ;;  # raw binary (hedioum/hysteria)
  esac

  for b in $bins; do
    found=$(find "$tmp" -type f -name "$b" 2>/dev/null | head -n1)
    [[ -z "$found" ]] && found=$(find "$tmp" -type f -iname "$b*" 2>/dev/null | grep -vi '\.txt$\|\.md$' | head -n1)
    if [[ -z "$found" ]]; then ui_err "binary '$b' not found in $core download"; rm -rf "$tmp"; return 1; fi
    install -m 0755 "$found" "$dst/$b"
    ln -sfn "$dst/$b" "$MILI_COREBIN/$b"
  done
  rm -rf "$tmp"
  ui_ok "$core $v installed"
}

cores_ensure() { cores_is_installed "$1" || cores_install "$1"; }

cores_versions_present() {  # <core>
  ls -1 "$MILI_STORE/$1" 2>/dev/null || true
}
cores_rollback() {  # <core> <ver>
  local core="$1" ver="$2" b
  [[ -d "$MILI_STORE/$core/$ver" ]] || { ui_err "version $ver not present"; return 1; }
  for b in $(cores_binaries "$core"); do
    [[ -f "$MILI_STORE/$core/$ver/$b" ]] && ln -sfn "$MILI_STORE/$core/$ver/$b" "$MILI_COREBIN/$b"
  done
  ui_ok "$core rolled back to $ver"
}

# path to a BINARY symlink (argument is a binary name, e.g. gost, frps, hedioum-tunnel)
cores_path() { printf '%s' "$MILI_COREBIN/$1"; }
cores_bin_ok() { [[ -x "$MILI_COREBIN/$1" && ! -d "$MILI_COREBIN/$1" ]]; }

# ===== lib/pair.sh =====
# shellcheck shell=bash
# mili :: pair.sh - pairing code encode/decode (+ optional passphrase) + QR.
#
# Payload = flat "key=value" lines (one record describing what side B needs).
# Wire:   mili1:  <base64url(gzip(payload))>              (plain)
#         mili1e: <base64url(openssl aes-256 pbkdf2 ..)>   (passphrase)
# A checksum line (CKSUM=) is injected so import can detect corruption.

_b64url_enc() { base64 -w0 2>/dev/null | tr '+/' '-_' | tr -d '='; }
_b64url_dec() {
  local s; s="$(printf '%s' "$1" | tr '\-_' '+/')"
  local pad=$(( ${#s} % 4 )); (( pad )) && s="$s$(printf '=%.0s' $(seq $((4-pad))))"
  printf '%s' "$s" | base64 -d 2>/dev/null
}

# checksum is newline-insensitive (grep re-adds a trailing newline on decode)
_payload_cksum() { tr -d '\n' | sha256sum | awk '{print substr($1,1,16)}'; }

# pair_encode <passphrase-or-empty> < payload-on-stdin  -> prints code
pair_encode() {
  local pass="${1:-}" payload cks
  payload="$(cat)"
  cks="$(printf '%s' "$payload" | _payload_cksum)"
  payload="$payload
CKSUM=$cks"
  if [[ -n "$pass" ]]; then
    local enc
    enc="$(printf '%s' "$payload" | gzip -c | openssl enc -aes-256-cbc -pbkdf2 -salt -pass "pass:$pass" 2>/dev/null | _b64url_enc)"
    printf 'mili1e:%s' "$enc"
  else
    printf 'mili1:%s' "$(printf '%s' "$payload" | gzip -c | _b64url_enc)"
  fi
}

# pair_decode <code> [passphrase] -> prints payload (without CKSUM line), verifies
pair_decode() {
  local code="$1" pass="${2:-}" body raw cks_have cks_calc
  case "$code" in
    mili1:*)  body="${code#mili1:}"
              raw="$(_b64url_dec "$body" | gunzip -c 2>/dev/null)" ;;
    mili1e:*) [[ -z "$pass" ]] && { ui_err "encrypted code needs a passphrase"; return 2; }
              body="${code#mili1e:}"
              raw="$(_b64url_dec "$body" | openssl enc -d -aes-256-cbc -pbkdf2 -pass "pass:$pass" 2>/dev/null | gunzip -c 2>/dev/null)" ;;
    *) ui_err "not a mili pairing code"; return 2 ;;
  esac
  [[ -z "$raw" ]] && { ui_err "failed to decode (wrong passphrase or corrupt code)"; return 2; }
  cks_have="$(printf '%s' "$raw" | grep '^CKSUM=' | cut -d= -f2)"
  cks_calc="$(printf '%s' "$raw" | grep -v '^CKSUM=' | _payload_cksum)"
  if [[ -n "$cks_have" && "$cks_have" != "$cks_calc" ]]; then
    ui_err "pairing code checksum mismatch"; return 3
  fi
  printf '%s' "$raw" | grep -v '^CKSUM='
}

# read a field out of a decoded payload:  pair_field <payload> <key>
pair_field() { printf '%s\n' "$1" | awk -F= -v k="$2" '$1==k{sub(/^[^=]*=/,""); print; exit}'; }

# show code as text + QR (if qrencode present)
pair_present() {  # <code> [title]
  local code="$1" title="${2:-Pairing code}"
  ui_head "$title"
  ui_warn "this code contains secrets - share only with the paired server"
  echo
  printf '%s%s%s\n' "${C_YEL:-}" "$code" "${C_RST:-}"
  echo
  if sys_has qrencode && [[ -t 1 ]]; then
    qrencode -t ANSIUTF8 "$code" 2>/dev/null || true
  fi
}

# ===== lib/socks.sh =====
# shellcheck shell=bash
# mili :: socks.sh - exit-SOCKS helper (gost) used by forward-only / L3 tunnels.
#
# Forward-only engines (Backhaul, FRP, GRE+FRP) and L3 (GRE) do not speak SOCKS
# themselves. On the FOREIGN side mili runs a gost SOCKS5 server; the tunnel
# forwards an Iran localhost port to it. On Iran that localhost port IS the
# SOCKS endpoint the user adds to x-ui as an outbound.
#
# Config file per tunnel: /etc/mili/engines/socks/<name>.env
#   SOCKS_BIND, SOCKS_PORT, SOCKS_USER, SOCKS_PASS

MILI_SOCKS_DIR="$MILI_ETC/engines/socks"

# write a socks helper config (foreign side). bind defaults to inner IP or 127.0.0.1
socks_render() {  # <name> <bind> <port> <user> <pass>
  run mkdir -p "$MILI_SOCKS_DIR"
  local name="$1" bind="$2" port="$3" user="$4" pass="$5"
  local f; f="$MILI_SOCKS_DIR/$name.env"
  if [[ "${MILI_DRYRUN:-0}" == 1 ]]; then
    ui_info "[dry] would write $f (socks $bind:$port)"; return 0
  fi
  cat >"$f" <<EOF
SOCKS_BIND=$bind
SOCKS_PORT=$port
SOCKS_USER=$user
SOCKS_PASS=$pass
EOF
  chmod 600 "$f"
}

# build the gost command for mili-socks@<name> (called by _svc dispatcher)
socks_exec() {  # <name>
  local name="$1" gost f; f="$MILI_SOCKS_DIR/$name.env"
  [[ -f "$f" ]] || die "socks config missing: $f"
  # shellcheck disable=SC1090
  . "$f"
  gost="$(cores_path gost)"
  [[ -x "$gost" ]] || die "gost core not installed"
  exec "$gost" -L "socks5://${SOCKS_USER}:${SOCKS_PASS}@${SOCKS_BIND}:${SOCKS_PORT}?udp=true"
}

socks_remove() { run rm -f "$MILI_SOCKS_DIR/$1.env" 2>/dev/null || true; }

# the gost client URL string a forwarder points at (for frpc socks5 plugin etc.)
socks_url() {  # <bind> <port> <user> <pass>
  printf 'socks5://%s:%s@%s:%s?udp=true' "$3" "$4" "$1" "$2"
}

# ===== lib/xui.sh =====
# shellcheck shell=bash
# mili :: xui.sh - READ-ONLY 3x-ui detection + copy-ready outbound JSON/steps.
# mili NEVER writes to x-ui DB/API/service. It only reads and prints guidance.

XUI_DB=/etc/x-ui/x-ui.db
XUI_BIN=/usr/local/x-ui/x-ui

xui_installed() { [[ -x "$XUI_BIN" || -f "$XUI_DB" ]]; }
xui_running()   { systemctl is-active --quiet x-ui 2>/dev/null; }

xui_panel_port() {
  [[ -x "$XUI_BIN" ]] || return 1
  "$XUI_BIN" setting -show true 2>/dev/null | awk -F': *' '/[Pp]ort/{print $2; exit}'
}

# list inbound tags + ports (read-only). prints "tag|port|protocol"
xui_inbounds() {
  [[ -r "$XUI_DB" ]] && sys_has sqlite3 || return 1
  sqlite3 -readonly "$XUI_DB" \
    "select tag||'|'||port||'|'||protocol from inbounds;" 2>/dev/null
}

xui_status_line() {
  if ! xui_installed; then printf 'not installed'; return; fi
  local p st; p=$(xui_panel_port 2>/dev/null)
  st=$(xui_running && echo running || echo stopped)
  printf '%s (panel:%s)' "$st" "${p:-?}"
}

# compact, copyable "what to put in the x-ui outbound" box (shown in info)
xui_outbound_box() {  # <addr> <port> [user] [pass]
  ui_hr 64
  printf '  %s▶ SET THIS IN 3x-ui OUTBOUND%s  (or use the "3x-ui JSON helper" action)\n' "$C_B$C_GRN" "$C_RST"
  ui_kv "protocol" "socks  (SOCKS5)"
  ui_kv "address"  "$1"
  ui_kv "port"     "$2"
  if [[ -n "${3:-}" ]]; then ui_kv "username" "$3"; ui_kv "password" "$4"; else ui_kv "auth" "none (no user/pass)"; fi
  ui_hr 64
}

# produce a SOCKS outbound JSON block for a tunnel's local SOCKS endpoint
xui_socks_json() {  # <tag> <addr> <port> <user> <pass>
  local tag="$1" addr="$2" port="$3" user="$4" pass="$5"
  cat <<EOF
{
  "tag": "$tag",
  "protocol": "socks",
  "settings": {
    "servers": [
      {
        "address": "$addr",
        "port": $port,
        "users": [ { "user": "$user", "pass": "$pass" } ]
      }
    ]
  }
}
EOF
}

# freedom outbound bound to an inner IP (for L3 exit via sendThrough)
xui_freedom_json() {  # <tag> <inner-ip>
  cat <<EOF
{
  "tag": "$1",
  "protocol": "freedom",
  "sendThrough": "$2",
  "settings": {}
}
EOF
}

# routing rule skeleton that steers inbound tags to the mili outbound
xui_routing_json() {  # <outbound-tag> <inboundTag1,inboundTag2,...>
  local ob="$1" inbs="$2" arr
  arr=$(printf '%s' "$inbs" | awk -F, '{for(i=1;i<=NF;i++){printf "\"%s\"%s",$i,(i<NF?", ":"")}}')
  cat <<EOF
{
  "type": "field",
  "inboundTag": [ $arr ],
  "outboundTag": "$ob"
}
EOF
}

# full on-screen helper for one tunnel (SOCKS mode)
xui_help_socks() {  # <name> <addr> <port> <user> <pass>
  local name="$1" addr="$2" port="$3" user="$4" pass="$5"
  ui_head "Use tunnel '$name' with 3x-ui (SOCKS outbound)"
  if ! xui_installed; then
    ui_warn "3x-ui not detected on this server. Steps still apply once installed."
  else
    ui_kv "x-ui status" "$(xui_status_line)"
    echo; ui_info "detected inbound tags you can route:"
    xui_inbounds 2>/dev/null | while IFS='|' read -r t p pr; do ui_note "- $t  (port $p, $pr)"; done
  fi
  echo; ui_info "1) Outbound JSON  (Panel -> Xray Configs -> Outbounds -> + -> JSON):"
  xui_socks_json "mili-$name" "$addr" "$port" "$user" "$pass"
  echo; ui_info "2) Routing rule  (place BEFORE the geoip:private -> blocked rule):"
  xui_routing_json "mili-$name" "<your-inbound-tag>"
  echo; ui_note "3) Save -> Restart Xray. 4) Test from menu (curl --socks5-hostname)."
}

# ===== lib/watchdog.sh =====
# shellcheck shell=bash
# mili :: watchdog.sh - health loop, auto-restart, fw/ufw self-heal, port audit.
# Invoked by mili-watchdog.timer every 60s via `mili _watchdog`.

MILI_WDLOG="${MILI_WDLOG:-$MILI_LOGDIR/watchdog.log}"
MILI_WD_FAILS="$MILI_ETC/.wdfails"   # name -> consecutive fail count

_wd_log() { mkdir -p "$MILI_LOGDIR" 2>/dev/null || true; printf '%s %s\n' "$(date '+%F %T')" "$*" >>"$MILI_WDLOG" 2>/dev/null || true; }
_wd_fails_get() { grep -E "^$1 " "$MILI_WD_FAILS" 2>/dev/null | awk '{print $2}'; }
_wd_fails_set() {
  local name="$1" n="$2" tmp; tmp="$(mktemp)"
  { grep -vE "^$name " "$MILI_WD_FAILS" 2>/dev/null; printf '%s %s\n' "$name" "$n"; } >"$tmp"
  mv -f "$tmp" "$MILI_WD_FAILS"
}

watchdog_run() {
  # 1. self-heal firewall hooks (cheap, idempotent)
  fw_rehook 2>/dev/null || true

  # 2. per-tunnel health
  local name type cur fails
  while read -r name; do
    [[ -z "$name" ]] && continue
    st_load "$name" || continue
    # only watch tunnels the operator started (never revive a stopped one)
    [[ "$(st_get state)" == up ]] || continue
    type="$(st_get type)"
    t_has "$type" health || continue
    if t_call "$type" health "$name" >/dev/null 2>&1; then
      _wd_fails_set "$name" 0
    else
      fails=$(_wd_fails_get "$name"); fails=$(( ${fails:-0} + 1 ))
      _wd_fails_set "$name" "$fails"
      _wd_log "health fail $name ($fails)"
      if (( fails >= 3 )); then
        _wd_log "restarting $name after $fails fails"
        # restart the UNIT only (never re-run the wizard/setup path)
        local u=''; t_has "$type" unit && u="$(t_call "$type" unit "$name" 2>/dev/null)"
        [[ -n "$u" ]] && systemctl restart "$u" >/dev/null 2>&1 || true
        _wd_fails_set "$name" 0
      fi
    fi
  done < <(st_list)

  # 3. port audit (clash with newly-added x-ui inbound etc.)
  if ! ports_audit >/dev/null 2>&1; then
    _wd_log "PORT CONFLICT detected (see 'mili ports')"
  fi

  # 4. note x-ui appearance (ensures ufw mirrors still present next run)
  if xui_installed 2>/dev/null; then
    : # future: re-mirror ufw rules if missing; fw_rehook already guarantees chains
  fi
}

# ===== lib/doctor.sh =====
# shellcheck shell=bash
# mili :: doctor.sh - diagnostics, MTU finder, socks/connectivity tests, bundle.

doctor_run() {
  ui_head "mili doctor"
  ui_kv "OS"        "$MILI_OS_NAME ($MILI_OS $MILI_OS_VER)"
  ui_kv "Arch"      "$MILI_ARCH"
  sys_os_supported || ui_warn "distro not in tested matrix (Ubuntu 20.04+/Debian 11+)"
  ui_kv "Public v4" "$(sys_public_ip4)"
  local v6; v6=$(sys_public_ip6 2>/dev/null) && ui_kv "Public v6" "$v6"
  ui_kv "Default if" "$(sys_default_iface) via $(sys_default_gw)"

  echo; ui_info "dependencies:"
  local d
  for d in iproute2:ip iptables:iptables curl:curl jq:jq sqlite3:sqlite3 openssl:openssl tar:tar; do
    local pkg="${d%%:*}" cmd="${d##*:}"
    if sys_has "$cmd"; then ui_ok "$pkg"; else ui_warn "$pkg missing"; fi
  done

  echo; ui_info "kernel features:"
  modprobe ip_gre 2>/dev/null && ui_ok "GRE module available" || ui_warn "ip_gre not loadable (GRE may be unavailable)"
  modprobe fou 2>/dev/null && ui_ok "FOU module available" || ui_note "fou not loadable (GRE+FOU mode unavailable)"
  [[ "$(sysctl -n net.ipv4.ip_forward 2>/dev/null)" == 1 ]] && ui_ok "ip_forward on" || ui_note "ip_forward off (set when an L3/forward tunnel is created)"
  sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null | grep -q bbr && ui_ok "BBR active" || ui_note "BBR not active (see Network optimizer)"

  echo; ui_info "3x-ui:"
  ui_kv "status" "$(xui_status_line)"

  echo; ui_info "tunnels:"
  local name
  while read -r name; do
    [[ -z "$name" ]] && continue
    st_load "$name" || continue
    local type st; type="$(st_get type)"
    if t_has "$type" health && t_call "$type" health "$name" >/dev/null 2>&1; then st="${C_GRN}up${C_RST}"; else st="${C_RED}down${C_RST}"; fi
    printf '  %-12s %-10s %b\n' "$name" "$type" "$st"
  done < <(st_list)
}

# MTU finder: largest payload that passes unfragmented to a host
doctor_mtu() {  # <host>
  local host="${1:-}" lo=1200 hi=1500 best=0 mid
  [[ -z "$host" ]] && { ui_err "usage: doctor_mtu <host-or-ip>"; return 1; }
  ui_info "probing path MTU to $host (binary search)"
  while (( lo <= hi )); do
    mid=$(( (lo+hi)/2 ))
    if ping -c1 -W2 -M do -s $(( mid-28 )) "$host" >/dev/null 2>&1; then
      best=$mid; lo=$(( mid+1 ))
    else
      hi=$(( mid-1 ))
    fi
  done
  if (( best > 0 )); then
    ui_ok "path MTU to $host = $best (suggest tunnel MTU $(( best-40 )) for GRE)"
  else
    ui_warn "could not determine MTU (host may block ICMP)"
  fi
}

# test a SOCKS endpoint: reachability + exit IP
doctor_socks() {  # <addr> <port> [user] [pass]
  local addr="$1" port="$2" user="${3:-}" pass="${4:-}" auth=''
  [[ -n "$user" ]] && auth="$user:$pass@"
  ui_info "testing SOCKS $addr:$port"
  if curl -fsS --max-time 8 --socks5-hostname "${auth}${addr}:${port}" https://www.gstatic.com/generate_204 -o /dev/null 2>/dev/null; then
    ui_ok "connectivity OK"
    local xip; xip=$(curl -fsS --max-time 8 --socks5-hostname "${auth}${addr}:${port}" https://api.ipify.org 2>/dev/null)
    ui_kv "exit IP" "${xip:-unknown}"
  else
    ui_err "SOCKS test failed"
    return 1
  fi
}

# collect a support bundle (logs + state, secrets redacted)
doctor_bundle() {
  local out="/root/mili-doctor-$(date +%Y%m%d-%H%M%S).tar.gz" tmp
  tmp="$(mktemp -d)"
  mkdir -p "$tmp/mili"
  cp -r "$MILI_LOGDIR" "$tmp/mili/logs" 2>/dev/null || true
  cp -r "$MILI_ETC" "$tmp/mili/etc" 2>/dev/null || true
  # redact secrets
  find "$tmp/mili/etc" -type f 2>/dev/null | while read -r f; do
    sed -i -E 's/(PASS|SECRET|KEY|TOKEN|PSK|privatekey)=.*/\1=<redacted>/I' "$f" 2>/dev/null || true
  done
  { echo "=== systemd mili units ==="; systemctl list-units 'mili*' --no-pager 2>/dev/null
    echo "=== iptables mili ==="; iptables-save 2>/dev/null | grep -i mili
    echo "=== ss ==="; ss -lntu 2>/dev/null; } >"$tmp/mili/system.txt"
  tar -czf "$out" -C "$tmp" mili 2>/dev/null
  rm -rf "$tmp"
  ui_ok "doctor bundle -> $out (secrets redacted)"
}

# ===== lib/optimize.sh =====
# shellcheck shell=bash
# mili :: optimize.sh - optional, reversible network tuning (BBR + fq + buffers).
# Writes ONLY /etc/sysctl.d/91-mili-tune.conf. qdisc only ever 'fq'.
# Never touches /etc/sysctl.conf or x-ui's 99-bbr-x-ui.conf.

optimize_status() {
  ui_kv "congestion" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null || echo ?)"
  ui_kv "qdisc"      "$(sysctl -n net.core.default_qdisc 2>/dev/null || echo ?)"
  if [[ -f "$MILI_SYSCTL_TUNE" ]]; then ui_ok "mili tuning profile active ($MILI_SYSCTL_TUNE)"; else ui_note "mili tuning profile not applied"; fi
}

optimize_apply() {
  if ! modprobe tcp_bbr 2>/dev/null && ! sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null | grep -qw bbr; then
    ui_warn "BBR not available in this kernel; applying buffer tuning only"
  fi
  run bash -c "cat > '$MILI_SYSCTL_TUNE' <<EOF
# mili network tuning (reversible: delete this file + sysctl --system)
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
net.core.rmem_max = 16777216
net.core.wmem_max = 16777216
net.ipv4.tcp_rmem = 4096 87380 16777216
net.ipv4.tcp_wmem = 4096 65536 16777216
net.ipv4.tcp_mtu_probing = 1
net.ipv4.tcp_fastopen = 3
net.core.netdev_max_backlog = 5000
EOF"
  run sysctl --system >/dev/null 2>&1 || true
  ui_ok "tuning applied"
  optimize_status
}

optimize_revert() {
  [[ -f "$MILI_SYSCTL_TUNE" ]] && run rm -f "$MILI_SYSCTL_TUNE"
  run sysctl --system >/dev/null 2>&1 || true
  ui_ok "mili tuning removed (x-ui/system sysctl untouched)"
}

# ===== lib/backup.sh =====
# shellcheck shell=bash
# mili :: backup.sh - backup/restore of /etc/mili (state, configs, pki).

backup_create() {  # [out.tar.gz]
  local out="${1:-$MILI_ETC/backups/mili-$(date +%Y%m%d-%H%M%S).tar.gz}"
  run mkdir -p "$(dirname "$out")"
  run tar -czf "$out" -C "$(dirname "$MILI_ETC")" "$(basename "$MILI_ETC")" \
    --exclude='*/backups/*' --exclude='*/cache/*' 2>/dev/null
  ui_ok "backup -> $out"
  printf '%s' "$out"
}

backup_list() {
  ls -1t "$MILI_ETC/backups"/*.tar.gz 2>/dev/null || ui_note "no backups found"
}

# restore: extract state then re-render + re-apply firewall/services
backup_restore() {  # <tar.gz>
  local tar="$1"
  [[ -f "$tar" ]] || { ui_err "no such backup: $tar"; return 1; }
  ui_warn "restore overwrites current /etc/mili state"
  ui_confirm "proceed with restore from $(basename "$tar")?" n || return 1
  run tar -xzf "$tar" -C "$(dirname "$MILI_ETC")"
  ui_ok "state restored; re-applying firewall + services"
  fw_init
  # re-render and bring up every tunnel from restored state
  local name type
  while read -r name; do
    [[ -z "$name" ]] && continue
    st_load "$name" || continue
    type="$(st_get type)"
    t_has "$type" render && t_call "$type" render "$name" || true
    t_has "$type" up && t_call "$type" up "$name" || true
  done < <(st_list)
  ui_ok "restore complete"
}

# ===== tunnels/backhaul.sh =====
# shellcheck shell=bash
# mili :: tunnels/backhaul.sh - Musixal/Backhaul (open-source only).
# server = IRAN (listens public tunnel port), client = FOREIGN (dials).
# SOCKS mode: foreign runs mili-socks (gost); Backhaul forwards an Iran port to
# it. skip_optz=true ALWAYS (protects the ephemeral range used by xray).
#
# roles: iran (server) | foreign (client)
# config: /etc/mili/engines/backhaul/<name>.toml

t_register backhaul
feature "tunnel.backhaul" free

MILI_BH_ETC="$MILI_ETC/engines/backhaul"

t_backhaul_meta() {
  echo "id=backhaul"
  echo "title=Backhaul  (reverse mux)"
  echo "tier=free"
  echo "layer=fwd"
  echo "roles=iran foreign"
  echo "primary=iran"     # iran = server (listener) generates; foreign dials in
  echo "twoway=no"        # foreign only needs iran's IP (carried in the code)
  echo "cores=backhaul"
}

t_backhaul_wizard() {  # <role> <level>  (runs on iran = the listener/generator)
  local role="$1" level="$2"
  ST[my_ip]="$(sys_public_ip4)"
  [[ "$level" == advanced ]] && ST[my_ip]="$(ui_ask 'This Iran server public IP (auto-detected)' "${ST[my_ip]}")"
  ui_ok "this Iran server's public IP: ${ST[my_ip]}  (foreign will dial it)"
  ST[tunnel_port]="$(ui_ask 'Public tunnel port (Iran listens)' "${ST[tunnel_port]:-$(ports_alloc_public)}")"
  [[ -z "${ST[token]:-}" ]] && ST[token]="$(sys_rand_token 24)"

  echo; ui_info "transport: tcp tcpmux ws wss wsmux wssmux udp"
  ST[transport]="$(ui_ask 'transport' "${ST[transport]:-tcp}")"

  echo; ui_info "Usage mode: 1) socks  2) forward"
  local um; um="$(ui_ask 'mode' "${ST[mode]:-1}")"
  case "$um" in 2) ST[mode]=forward;; *) ST[mode]=socks;; esac
  case "${ST[mode]}" in
    socks)
      ST[iran_socks]="${ST[iran_socks]:-$(ports_alloc_socks)}"
      ST[foreign_socks]="${ST[foreign_socks]:-$(sys_rand_port 10800 10999)}"
      [[ -z "${ST[socks_user]:-}" ]] && ST[socks_user]="mili"
      [[ -z "${ST[socks_pass]:-}" ]] && ST[socks_pass]="$(sys_rand_token 18)" ;;
    forward)
      ST[fwd]="$(ui_ask 'ports spec (backhaul syntax, comma)  e.g. 8443=443,2083=127.0.0.1:2083' "${ST[fwd]:-}")" ;;
  esac

  if [[ "$level" == advanced ]]; then
    ST[nodelay]="$(ui_ask 'nodelay true/false' "${ST[nodelay]:-true}")"
    ST[keepalive]="$(ui_ask 'keepalive_period (s)' "${ST[keepalive]:-75}")"
    ST[heartbeat]="$(ui_ask 'heartbeat (s)' "${ST[heartbeat]:-40}")"
    ST[mux_con]="$(ui_ask 'mux_con' "${ST[mux_con]:-8}")"
    ST[conn_pool]="$(ui_ask 'connection_pool' "${ST[conn_pool]:-8}")"
    [[ "${ST[transport]}" == wss* ]] && ST[domain]="$(ui_ask 'TLS domain (optional, blank=self-signed)' "${ST[domain]:-}")"
  else
    ST[nodelay]="${ST[nodelay]:-true}"; ST[keepalive]="${ST[keepalive]:-75}"
    ST[heartbeat]="${ST[heartbeat]:-40}"; ST[mux_con]="${ST[mux_con]:-8}"; ST[conn_pool]="${ST[conn_pool]:-8}"
  fi
  return 0
}

_bh_ports_line() {  # build the ports = [...] array contents
  st_load "$1"
  if [[ "${ST[mode]}" == socks ]]; then
    printf '"%s=%s"' "${ST[iran_socks]}" "${ST[foreign_socks]}"
  else
    local item out='' first=1
    IFS=',' read -ra items <<<"${ST[fwd]}"
    for item in "${items[@]}"; do
      [[ -z "$item" ]] && continue
      [[ $first -eq 1 ]] && first=0 || out+=", "
      out+="\"$item\""
    done
    printf '%s' "$out"
  fi
}

_bh_tls() {  # emit tls cert/key lines for wss* transports
  st_load "$1"
  [[ "${ST[transport]}" == wss* ]] || return 0
  local crt key dir="$MILI_ETC/pki/$1"
  if [[ -n "${ST[domain]:-}" && -f "/root/cert/${ST[domain]}/fullchain.pem" ]]; then
    crt="/root/cert/${ST[domain]}/fullchain.pem"; key="/root/cert/${ST[domain]}/privkey.pem"
  else
    crt="$dir/cert.pem"; key="$dir/key.pem"
    if [[ ! -f "$crt" && "${MILI_DRYRUN:-0}" != 1 ]]; then
      mkdir -p "$dir"
      openssl req -x509 -newkey rsa:2048 -keyout "$key" -out "$crt" -days 3650 -nodes \
        -subj "/CN=${ST[domain]:-mili.local}" >/dev/null 2>&1 || true
    fi
  fi
  printf 'tls_cert = "%s"\ntls_key = "%s"\n' "$crt" "$key"
}

t_backhaul_render() {  # <name>
  st_load "$1"; local name="$1" f; f="$MILI_BH_ETC/$name.toml"
  run mkdir -p "$MILI_BH_ETC"
  [[ "${MILI_DRYRUN:-0}" == 1 ]] && { ui_info "[dry] backhaul config for $name (role ${ST[role]})"; return 0; }
  if [[ "${ST[role]}" == iran ]]; then
    {
      echo "# mili Backhaul server (Iran) tunnel $name"
      echo "[server]"
      echo "bind_addr = \"0.0.0.0:${ST[tunnel_port]}\""
      echo "transport = \"${ST[transport]}\""
      echo "token = \"${ST[token]}\""
      echo "keepalive_period = ${ST[keepalive]}"
      echo "nodelay = ${ST[nodelay]}"
      echo "heartbeat = ${ST[heartbeat]}"
      echo "mux_con = ${ST[mux_con]}"
      echo "channel_size = 2048"
      echo "sniffer = false"
      echo "web_port = 0"
      echo "skip_optz = true"
      _bh_tls "$name"
      echo "ports = [ $(_bh_ports_line "$name") ]"
    } >"$f"
  else
    {
      echo "# mili Backhaul client (Foreign) tunnel $name"
      echo "[client]"
      echo "remote_addr = \"${ST[iran_ip]}:${ST[tunnel_port]}\""
      echo "transport = \"${ST[transport]}\""
      echo "token = \"${ST[token]}\""
      echo "keepalive_period = ${ST[keepalive]}"
      echo "nodelay = ${ST[nodelay]}"
      echo "connection_pool = ${ST[conn_pool]}"
      echo "sniffer = false"
      echo "web_port = 0"
      echo "skip_optz = true"
      [[ "${ST[transport]}" == wss* ]] && echo "edge_ip = \"\""
    } >"$f"
  fi
  chmod 600 "$f"
}

t_backhaul_unit() { echo "mili-backhaul@$1.service"; }

t_backhaul_fw_apply() {  # <name>
  st_load "$1"; local name="$1"
  if [[ "${ST[role]}" == iran ]]; then
    fw_allow "$name" tcp "${ST[tunnel_port]}"; fw_ufw_mirror "$name" tcp "${ST[tunnel_port]}"
    if [[ "${ST[mode]}" == socks ]]; then
      fw_loopback_guard "$name" tcp "${ST[iran_socks]}"
    else
      local item lport proto=tcp
      IFS=',' read -ra items <<<"${ST[fwd]}"
      for item in "${items[@]}"; do
        [[ -z "$item" ]] && continue
        lport="${item%%=*}"
        fw_allow "$name" tcp "$lport"; fw_ufw_mirror "$name" tcp "$lport"
      done
    fi
  fi
}

t_backhaul_up() {  # <name>
  st_load "$1"; local name="$1"
  require_root; cores_ensure backhaul
  t_backhaul_render "$name"
  t_backhaul_fw_apply "$name"
  svc_up "mili-backhaul@$name.service"
  if [[ "${ST[role]}" == iran ]]; then
    ports_claim "$name" tcp "${ST[tunnel_port]}" "0.0.0.0"
    [[ "${ST[mode]}" == socks ]] && ports_claim "$name" tcp "${ST[iran_socks]}" "127.0.0.1"
  else
    if [[ "${ST[mode]}" == socks ]]; then
      cores_ensure gost
      socks_render "$name" "127.0.0.1" "${ST[foreign_socks]}" "${ST[socks_user]}" "${ST[socks_pass]}"
      svc_up "mili-socks@$name.service"
      ports_claim "$name" tcp "${ST[foreign_socks]}" "127.0.0.1"
    fi
  fi
}

t_backhaul_down() {  # <name>
  st_load "$1"; local name="$1"
  svc_down "mili-backhaul@$name.service" 2>/dev/null || true
  svc_down "mili-socks@$name.service" 2>/dev/null || true
  fw_remove "$name"
}

t_backhaul_purge() { run rm -f "$MILI_BH_ETC/$1.toml" 2>/dev/null || true; }

t_backhaul_health() {  # <name>
  st_load "$1"
  if [[ "${ST[role]}" == iran ]]; then
    ss -Hlnt 2>/dev/null | awk '{print $4}' | grep -qE ":${ST[tunnel_port]}\$"
  else
    svc_active "mili-backhaul@$1.service"
  fi
}

t_backhaul_ports() {
  st_load "$1"
  if [[ "${ST[role]}" == iran ]]; then
    echo "tcp:${ST[tunnel_port]}:0.0.0.0"
    [[ "${ST[mode]}" == socks ]] && echo "tcp:${ST[iran_socks]}:127.0.0.1"
  else
    [[ "${ST[mode]}" == socks ]] && echo "tcp:${ST[foreign_socks]}:127.0.0.1"
  fi
}

t_backhaul_info() {
  st_load "$1"
  ui_kv "role/mode" "${ST[role]} / ${ST[mode]}"
  ui_kv "transport" "${ST[transport]}"
  if [[ "${ST[role]}" == iran ]]; then
    ui_kv "listen" "0.0.0.0:${ST[tunnel_port]}"
    [[ "${ST[mode]}" == socks ]] && { echo; xui_outbound_box "127.0.0.1" "${ST[iran_socks]}" "${ST[socks_user]}" "${ST[socks_pass]}"; }
    [[ "${ST[mode]}" == forward ]] && ui_kv "ports" "${ST[fwd]}"
  else
    ui_kv "dials" "${ST[iran_ip]}:${ST[tunnel_port]}"
    [[ "${ST[mode]}" == socks ]] && ui_kv "egress socks" "127.0.0.1:${ST[foreign_socks]}"
  fi
}

t_backhaul_xui() {
  st_load "$1"; local name="$1"
  if [[ "${ST[mode]}" == socks && "${ST[role]}" == iran ]]; then
    xui_help_socks "$name" "127.0.0.1" "${ST[iran_socks]}" "${ST[socks_user]}" "${ST[socks_pass]}"
  elif [[ "${ST[mode]}" == socks ]]; then
    ui_warn "SOCKS endpoint is on the IRAN server (127.0.0.1:${ST[iran_socks]}); run helper there."
  else
    ui_head "Use '$name' with 3x-ui (port forward)"; ui_note "Foreign ports published on Iran: ${ST[fwd]}"
  fi
}

t_backhaul_test() {
  st_load "$1"
  if [[ "${ST[mode]}" == socks && "${ST[role]}" == iran ]]; then
    doctor_socks 127.0.0.1 "${ST[iran_socks]}" "${ST[socks_user]}" "${ST[socks_pass]}"
  else
    t_backhaul_health "$1" && ui_ok "backhaul up" || ui_err "backhaul down"
  fi
}

t_backhaul_pair_export() {
  st_load "$1"
  local peerrole; [[ "${ST[role]}" == iran ]] && peerrole=foreign || peerrole=iran
  cat <<EOF
type=backhaul
name=${ST[name]}
role=$peerrole
mode=${ST[mode]}
transport=${ST[transport]}
tunnel_port=${ST[tunnel_port]}
token=${ST[token]}
iran_ip=${ST[my_ip]:-${ST[iran_ip]:-}}
iran_socks=${ST[iran_socks]:-}
foreign_socks=${ST[foreign_socks]:-}
socks_user=${ST[socks_user]:-}
socks_pass=${ST[socks_pass]:-}
fwd=${ST[fwd]:-}
nodelay=${ST[nodelay]}
keepalive=${ST[keepalive]}
heartbeat=${ST[heartbeat]:-40}
mux_con=${ST[mux_con]:-8}
conn_pool=${ST[conn_pool]:-8}
domain=${ST[domain]:-}
EOF
}

t_backhaul_pair_import() {
  local p="$1" name role k
  name="$(pair_field "$p" name)"; role="$(pair_field "$p" role)"
  ST=(); ST[name]="$name"; ST[type]=backhaul; ST[role]="$role"
  for k in mode transport tunnel_port token iran_ip iran_socks foreign_socks socks_user socks_pass fwd nodelay keepalive heartbeat mux_con conn_pool domain; do
    ST[$k]="$(pair_field "$p" "$k")"
  done
  [[ "$role" == iran ]] && ST[my_ip]="$(sys_public_ip4)"
  st_save
  t_backhaul_up "$name"; st_set state up; st_save
}

# ===== tunnels/frp.sh =====
# shellcheck shell=bash
# mili :: tunnels/frp.sh - reverse FRP tunnel (fatedier/frp).
# frps listens on IRAN (public), frpc dials from FOREIGN. Foreign egress is
# exposed back to Iran. SOCKS mode uses frp's built-in socks5 plugin (no gost).
#
# roles: iran (frps) | foreign (frpc)
# config: /etc/mili/engines/{frps,frpc}/<name>.toml

t_register frp
feature "tunnel.frp" free

MILI_FRP_ETC_S="$MILI_ETC/engines/frps"
MILI_FRP_ETC_C="$MILI_ETC/engines/frpc"

t_frp_meta() {
  echo "id=frp"
  echo "title=FRP  (reverse, public)"
  echo "tier=free"
  echo "layer=fwd"
  echo "roles=iran foreign"
  echo "primary=iran"     # iran = frps (listener) generates; foreign dials in
  echo "twoway=no"
  echo "cores=frp"
}

t_frp_wizard() {  # <role> <level>  (runs on iran = frps/listener/generator)
  local role="$1" level="$2"
  ST[my_ip]="$(sys_public_ip4)"
  [[ "$level" == advanced ]] && ST[my_ip]="$(ui_ask 'This Iran server public IP (auto-detected)' "${ST[my_ip]}")"
  ui_ok "this Iran server's public IP: ${ST[my_ip]}  (foreign will dial it)"
  ST[bind_port]="$(ui_ask 'frps public bind port (Iran)' "${ST[bind_port]:-$(ports_alloc_public)}")"
  [[ -z "${ST[token]:-}" ]] && ST[token]="$(sys_rand_token 24)"

  echo; ui_info "Usage mode:"
  ui_item 1 "socks" "SOCKS5 egress on foreign, reachable at Iran 127.0.0.1:<port>"
  ui_item 2 "forward" "expose foreign port on Iran public port"
  local um; um="$(ui_ask 'mode' "${ST[mode]:-1}")"
  case "$um" in 2) ST[mode]=forward;; *) ST[mode]=socks;; esac

  case "${ST[mode]}" in
    socks)
      ST[remote_port]="$(ui_ask 'Iran-side SOCKS port (loopback)' "${ST[remote_port]:-$(ports_alloc_socks)}")"
      [[ -z "${ST[socks_user]:-}" ]] && ST[socks_user]="mili"
      [[ -z "${ST[socks_pass]:-}" ]] && ST[socks_pass]="$(sys_rand_token 18)" ;;
    forward)
      ST[fwd]="$(ui_ask 'Forward spec  iranPublic=foreignLocal/proto  e.g. 8443=443/tcp' "${ST[fwd]:-}")" ;;
  esac

  if [[ "$level" == advanced ]]; then
    echo; ui_info "transport: tcp | kcp | quic | websocket"
    ST[transport]="$(ui_ask 'transport protocol' "${ST[transport]:-tcp}")"
    ST[tls]="$(ui_ask 'enable TLS (true/false)' "${ST[tls]:-true}")"
    ST[pool]="$(ui_ask 'poolCount' "${ST[pool]:-5}")"
  else
    ST[transport]="${ST[transport]:-tcp}"; ST[tls]="${ST[tls]:-true}"; ST[pool]="${ST[pool]:-5}"
  fi
  return 0
}

t_frp_render() {  # <name>
  st_load "$1"; local name="$1"
  if [[ "${ST[role]}" == iran ]]; then
    run mkdir -p "$MILI_FRP_ETC_S"
    local f="$MILI_FRP_ETC_S/$name.toml"
    if [[ "${MILI_DRYRUN:-0}" == 1 ]]; then ui_info "[dry] frps config:"; else
    cat >"$f" <<EOF
# mili frps (Iran) for tunnel $name
bindAddr = "0.0.0.0"
bindPort = ${ST[bind_port]}
auth.method = "token"
auth.token = "${ST[token]}"
webServer.addr = "127.0.0.1"
transport.maxPoolCount = 50
log.to = "/var/log/mili/frps-$name.log"
log.level = "info"
EOF
    chmod 600 "$f"; fi
  else
    run mkdir -p "$MILI_FRP_ETC_C"
    local f="$MILI_FRP_ETC_C/$name.toml"
    if [[ "${MILI_DRYRUN:-0}" == 1 ]]; then ui_info "[dry] frpc config:"; else
    {
      cat <<EOF
# mili frpc (Foreign) for tunnel $name
serverAddr = "${ST[iran_ip]}"
serverPort = ${ST[bind_port]}
auth.method = "token"
auth.token = "${ST[token]}"
transport.protocol = "${ST[transport]}"
transport.tls.enable = ${ST[tls]}
transport.poolCount = ${ST[pool]}
log.to = "/var/log/mili/frpc-$name.log"
log.level = "info"
EOF
      if [[ "${ST[mode]}" == socks ]]; then
        cat <<EOF

[[proxies]]
name = "$name-socks"
type = "tcp"
remotePort = ${ST[remote_port]}
[proxies.plugin]
type = "socks5"
username = "${ST[socks_user]}"
password = "${ST[socks_pass]}"
EOF
      else
        local item lport rport proto i=0
        IFS=',' read -ra items <<<"${ST[fwd]}"
        for item in "${items[@]}"; do
          [[ -z "$item" ]] && continue
          proto="${item##*/}"; item="${item%/*}"
          lport="${item%%=*}"; rport="${item##*=}"
          [[ "$proto" != udp ]] && proto=tcp
          cat <<EOF

[[proxies]]
name = "$name-fwd$i"
type = "$proto"
localIP = "127.0.0.1"
localPort = $rport
remotePort = $lport
EOF
          i=$((i+1))
        done
      fi
    } >"$f"
    chmod 600 "$f"; fi
  fi
}

t_frp_unit() { st_load "$1"; [[ "${ST[role]}" == iran ]] && echo "mili-frps@$1.service" || echo "mili-frpc@$1.service"; }

t_frp_fw_apply() {  # <name>
  st_load "$1"; local name="$1"
  if [[ "${ST[role]}" == iran ]]; then
    fw_allow "$name" tcp "${ST[bind_port]}"
    fw_ufw_mirror "$name" tcp "${ST[bind_port]}"
    if [[ "${ST[mode]}" == socks ]]; then
      # SOCKS remote port must stay loopback-only on Iran
      fw_loopback_guard "$name" tcp "${ST[remote_port]}"
    else
      local item lport proto
      IFS=',' read -ra items <<<"${ST[fwd]}"
      for item in "${items[@]}"; do
        [[ -z "$item" ]] && continue
        proto="${item##*/}"; item="${item%/*}"; lport="${item%%=*}"
        [[ "$proto" != udp ]] && proto=tcp
        fw_allow "$name" "$proto" "$lport"; fw_ufw_mirror "$name" "$proto" "$lport"
      done
    fi
  fi
}

t_frp_up() {  # <name>
  st_load "$1"; local name="$1"
  require_root; cores_ensure frp
  t_frp_render "$name"
  t_frp_fw_apply "$name"
  if [[ "${ST[role]}" == iran ]]; then
    svc_up "mili-frps@$name.service"
    ports_claim "$name" tcp "${ST[bind_port]}" "0.0.0.0"
    [[ "${ST[mode]}" == socks ]] && ports_claim "$name" tcp "${ST[remote_port]}" "127.0.0.1"
  else
    svc_up "mili-frpc@$name.service"
  fi
}

t_frp_down() {  # <name>
  st_load "$1"; local name="$1"
  svc_down "mili-frps@$name.service" 2>/dev/null || true
  svc_down "mili-frpc@$name.service" 2>/dev/null || true
  fw_remove "$name"
}

t_frp_purge() {
  st_load "$1"
  run rm -f "$MILI_FRP_ETC_S/$1.toml" "$MILI_FRP_ETC_C/$1.toml" 2>/dev/null || true
}

t_frp_health() {  # <name>
  st_load "$1"
  if [[ "${ST[role]}" == iran ]]; then
    ss -Hlnt 2>/dev/null | awk '{print $4}' | grep -qE ":${ST[bind_port]}\$"
  else
    svc_active "mili-frpc@$1.service"
  fi
}

t_frp_ports() {
  st_load "$1"
  [[ "${ST[role]}" == iran ]] || return 0
  echo "tcp:${ST[bind_port]}:0.0.0.0"
  [[ "${ST[mode]}" == socks ]] && echo "tcp:${ST[remote_port]}:127.0.0.1"
}

t_frp_info() {
  st_load "$1"
  ui_kv "role" "${ST[role]}"
  ui_kv "mode" "${ST[mode]}"
  ui_kv "transport" "${ST[transport]} tls=${ST[tls]}"
  if [[ "${ST[role]}" == iran ]]; then
    ui_kv "frps bind" "0.0.0.0:${ST[bind_port]}"
    [[ "${ST[mode]}" == socks ]] && { echo; xui_outbound_box "127.0.0.1" "${ST[remote_port]}" "${ST[socks_user]}" "${ST[socks_pass]}"; }
    [[ "${ST[mode]}" == forward ]] && ui_kv "forward" "${ST[fwd]}"
  else
    ui_kv "dials" "${ST[iran_ip]}:${ST[bind_port]}"
  fi
}

t_frp_xui() {
  st_load "$1"; local name="$1"
  if [[ "${ST[mode]}" == socks && "${ST[role]}" == iran ]]; then
    xui_help_socks "$name" "127.0.0.1" "${ST[remote_port]}" "${ST[socks_user]}" "${ST[socks_pass]}"
  elif [[ "${ST[mode]}" == socks ]]; then
    ui_warn "SOCKS endpoint lives on the IRAN server (127.0.0.1:${ST[remote_port]}). Run this helper there."
  else
    ui_head "Use '$name' with 3x-ui (port forward)"
    ui_note "Foreign ports are published on the Iran public ports: ${ST[fwd]}"
  fi
}

t_frp_test() {
  st_load "$1"
  if [[ "${ST[mode]}" == socks && "${ST[role]}" == iran ]]; then
    doctor_socks 127.0.0.1 "${ST[remote_port]}" "${ST[socks_user]}" "${ST[socks_pass]}"
  else
    t_frp_health "$1" && ui_ok "frp link healthy" || ui_err "frp link down"
  fi
}

t_frp_pair_export() {
  st_load "$1"
  local peerrole; [[ "${ST[role]}" == iran ]] && peerrole=foreign || peerrole=iran
  cat <<EOF
type=frp
name=${ST[name]}
role=$peerrole
mode=${ST[mode]}
bind_port=${ST[bind_port]}
token=${ST[token]}
transport=${ST[transport]}
tls=${ST[tls]}
pool=${ST[pool]}
iran_ip=${ST[my_ip]:-${ST[iran_ip]:-}}
remote_port=${ST[remote_port]:-}
socks_user=${ST[socks_user]:-}
socks_pass=${ST[socks_pass]:-}
fwd=${ST[fwd]:-}
EOF
}

t_frp_pair_import() {
  local p="$1" name role
  name="$(pair_field "$p" name)"; role="$(pair_field "$p" role)"
  ST=(); ST[name]="$name"; ST[type]=frp; ST[role]="$role"
  ST[mode]="$(pair_field "$p" mode)"
  ST[bind_port]="$(pair_field "$p" bind_port)"
  ST[token]="$(pair_field "$p" token)"
  ST[transport]="$(pair_field "$p" transport)"
  ST[tls]="$(pair_field "$p" tls)"
  ST[pool]="$(pair_field "$p" pool)"
  ST[iran_ip]="$(pair_field "$p" iran_ip)"
  ST[remote_port]="$(pair_field "$p" remote_port)"
  ST[socks_user]="$(pair_field "$p" socks_user)"
  ST[socks_pass]="$(pair_field "$p" socks_pass)"
  ST[fwd]="$(pair_field "$p" fwd)"
  [[ "$role" == iran ]] && ST[my_ip]="$(sys_public_ip4)"
  st_save
  t_frp_up "$name"; st_set state up; st_save
}

# ===== tunnels/gre.sh =====
# shellcheck shell=bash
# mili :: tunnels/gre.sh - GRE layer-3 tunnel (kernel iproute2).
# Variants: gre (v4), gre+fou (GRE-in-UDP, evades proto-47 blocks), ip6gre (v6).
# Usage modes: socks (gost on foreign inner IP) | forward (DNAT) | l3 (full exit).
#
# Inner addressing: 10.77.<N>.0/30  -> iran .1, foreign .2  (+ optional ULA).
# This side's role (iran|foreign) decides local vs peer inner IP.

t_register gre
feature "tunnel.gre" free

t_gre_meta() {
  echo "id=gre"
  echo "title=GRE  (kernel L3)"
  echo "tier=free"
  echo "layer=l3"
  echo "roles=iran foreign"
  echo "primary=iran"     # iran generates; foreign imports + replies
  echo "twoway=yes"       # both ends need each other's IP (reply code)
  echo "cores="
}

_gre_if()   { printf 'mgre-%s' "$1"; }
_gre_inner_local() { local n="$1" role="$2"; [[ "$role" == iran ]] && echo "10.77.$n.1" || echo "10.77.$n.2"; }
_gre_inner_peer()  { local n="$1" role="$2"; [[ "$role" == iran ]] && echo "10.77.$n.2" || echo "10.77.$n.1"; }

t_gre_wizard() {  # <role> <level>  (runs on the GENERATOR = iran side)
  local role="$1" level="$2" n
  # own public IP is auto-detected; no manual entry. Peer IP arrives via the
  # reply code (no typing). Advanced may override the detected own IP.
  ST[my_ip]="$(sys_public_ip4)"
  if [[ "$level" == advanced ]]; then
    ST[my_ip]="$(ui_ask "This server's public IP (auto-detected)" "${ST[my_ip]}")"
  fi
  ui_ok "this server's public IP: ${ST[my_ip]}"
  ST[peer_ip]="${ST[peer_ip]:-}"   # filled later by the peer's reply code

  # variant
  echo; ui_info "GRE variant:"
  ui_item 1 "gre" "plain GRE over IPv4 (proto 47)"
  ui_item 2 "gre+fou" "GRE-in-UDP (recommended where proto 47 is blocked)"
  ui_item 3 "ip6gre" "native IPv6 (needs public IPv6 both sides)"
  local gv; gv="$(ui_ask 'variant' "${ST[variant]:-2}")"
  case "$gv" in 1) ST[variant]=gre;; 3) ST[variant]=ip6gre;; *) ST[variant]=fou;; esac
  if [[ "${ST[variant]}" == fou ]]; then
    ST[fou_port]="${ST[fou_port]:-$(sys_rand_port 20000 29999)}"
  fi

  # usage mode
  echo; ui_info "Usage mode:"
  ui_item 1 "socks" "SOCKS5 on foreign inner IP (recommended for x-ui outbound)"
  ui_item 2 "forward" "port-forward Iran public ports -> foreign target"
  ui_item 3 "l3" "full L3 exit (policy-routed egress via foreign)"
  local um; um="$(ui_ask 'mode' "${ST[mode]:-1}")"
  case "$um" in 2) ST[mode]=forward;; 3) ST[mode]=l3;; *) ST[mode]=socks;; esac

  # allocate inner subnet + key (only if not already set, e.g. edit)
  if [[ -z "${ST[inner_n]:-}" ]]; then
    n="$(pool_inner_subnet)" || { ui_err "no free inner subnet"; return 1; }
    ST[inner_n]="$n"
  fi
  [[ -z "${ST[key]:-}" ]] && ST[key]="$(pool_gre_key)"
  ST[inner_local]="$(_gre_inner_local "${ST[inner_n]}" "$role")"
  ST[inner_peer]="$(_gre_inner_peer  "${ST[inner_n]}" "$role")"

  # mode-specific params
  case "${ST[mode]}" in
    socks)
      [[ -z "${ST[socks_port]:-}" ]] && ST[socks_port]="$(sys_rand_port 10800 10999)"
      [[ -z "${ST[socks_user]:-}" ]] && ST[socks_user]="mili"
      [[ -z "${ST[socks_pass]:-}" ]] && ST[socks_pass]="$(sys_rand_token 18)" ;;
    forward)
      ST[fwd]="$(ui_ask 'Forward spec  (lport=rport/proto, comma list)  e.g. 8443=443/tcp,53=53/udp' "${ST[fwd]:-}")" ;;
    l3)
      [[ "$role" == iran ]] && ST[table]="${ST[table]:-$(pool_table_id)}" ;;
  esac

  if [[ "$level" == advanced ]]; then
    ST[mtu]="$(ui_ask 'Tunnel MTU' "${ST[mtu]:-1400}")"
    ST[ttl]="$(ui_ask 'TTL' "${ST[ttl]:-255}")"
  else
    ST[mtu]="${ST[mtu]:-1400}"; ST[ttl]="${ST[ttl]:-255}"
  fi
  return 0
}

# raw interface bring-up (called by mili-l3@ unit via `mili _l3 up <name>`)
t_gre_ifup() {  # <name>
  st_load "$1"
  local name="$1" ifc; ifc="$(_gre_if "$name")"
  run modprobe ip_gre 2>/dev/null || true
  case "${ST[variant]}" in
    fou)
      run modprobe fou 2>/dev/null || true
      run ip fou add port "${ST[fou_port]}" ipproto 47 2>/dev/null || true
      run ip link add "$ifc" type gre local "${ST[my_ip]}" remote "${ST[peer_ip]}" \
        key "${ST[key]}" ttl "${ST[ttl]}" encap fou encap-sport auto encap-dport "${ST[fou_port]}" 2>/dev/null \
        || run ip link add "$ifc" type gre local "${ST[my_ip]}" remote "${ST[peer_ip]}" key "${ST[key]}" ttl "${ST[ttl]}" ;;
    ip6gre)
      run modprobe ip6_gre 2>/dev/null || true
      run ip link add "$ifc" type ip6gre local "${ST[my_ip]}" remote "${ST[peer_ip]}" key "${ST[key]}" ttl "${ST[ttl]}" ;;
    *)
      run ip link add "$ifc" type gre local "${ST[my_ip]}" remote "${ST[peer_ip]}" key "${ST[key]}" ttl "${ST[ttl]}" ;;
  esac
  run ip addr add "${ST[inner_local]}/30" dev "$ifc" 2>/dev/null || true
  run ip link set "$ifc" mtu "${ST[mtu]}" up
  # L3 exit policy routing / masquerade
  if [[ "${ST[mode]}" == l3 ]]; then
    if [[ "${ST[role]}" == foreign ]]; then
      sysctl_enable_forward
      fw_masq "$name" "10.77.${ST[inner_n]}.0/30"
    else
      sysctl_rpfilter_loose "$ifc"
      run ip rule add from "${ST[inner_local]}" table "${ST[table]}" 2>/dev/null || true
      run ip route add default via "${ST[inner_peer]}" dev "$ifc" table "${ST[table]}" 2>/dev/null || true
    fi
  fi
}

t_gre_ifdown() {  # <name>
  st_load "$1"
  local name="$1" ifc; ifc="$(_gre_if "$name")"
  if [[ "${ST[mode]}" == l3 && "${ST[role]}" == iran ]]; then
    run ip rule del from "${ST[inner_local]}" table "${ST[table]}" 2>/dev/null || true
    run ip route flush table "${ST[table]}" 2>/dev/null || true
  fi
  run ip link del "$ifc" 2>/dev/null || true
  [[ "${ST[variant]}" == fou ]] && run ip fou del port "${ST[fou_port]}" 2>/dev/null || true
}

# firewall rules for this tunnel (idempotent; also called by _fw-restore)
t_gre_fw_apply() {  # <name>
  st_load "$1"; local name="$1"
  case "${ST[variant]}" in
    fou) fw_allow "$name" udp "${ST[fou_port]}" "${ST[peer_ip]}"
         fw_ufw_mirror "$name" udp "${ST[fou_port]}" "${ST[peer_ip]}" ;;
    *)   fw_allow_proto "$name" 47 "${ST[peer_ip]}"
         fw_ufw_allow_gre "$name" "${ST[peer_ip]}" ;;
  esac
  fw_mss "$name" "$(_gre_if "$name")" pmtu
  case "${ST[mode]}" in
    socks)
      # SOCKS reachable only across the tunnel (from peer inner IP)
      fw_allow "$name" tcp "${ST[socks_port]}" "${ST[inner_peer]}" ;;
    forward)
      _gre_apply_forwards "$name" ;;
  esac
}

_gre_apply_forwards() {  # <name> : parse ST[fwd] and DNAT to foreign inner IP
  st_load "$1"; local name="$1" spec item lport rport proto
  IFS=',' read -ra items <<<"${ST[fwd]}"
  for item in "${items[@]}"; do
    [[ -z "$item" ]] && continue
    proto="${item##*/}"; item="${item%/*}"
    lport="${item%%=*}"; rport="${item##*=}"
    [[ "$proto" != tcp && "$proto" != udp ]] && proto=tcp
    fw_dnat "$name" "$proto" "$lport" "${ST[inner_peer]}" "$rport"
    fw_allow "$name" "$proto" "$lport"
    fw_ufw_mirror "$name" "$proto" "$lport"
  done
}

t_gre_render() { :; }   # no engine config file; all kernel state

t_gre_up() {  # <name>
  st_load "$1"; local name="$1" unit; unit="mili-l3@$name.service"
  require_root
  # not yet paired with the peer's address -> stay pending until the reply code
  if [[ -z "${ST[peer_ip]:-}" ]]; then
    ui_warn "waiting for the peer's reply code before the GRE link can come up"
    ui_note "import the REPLY code from the other server to finish '$name'."
    return 0
  fi
  t_gre_fw_apply "$name"
  svc_up "$unit"
  # foreign-side SOCKS helper
  if [[ "${ST[mode]}" == socks && "${ST[role]}" == foreign ]]; then
    cores_ensure gost
    socks_render "$name" "${ST[inner_local]}" "${ST[socks_port]}" "${ST[socks_user]}" "${ST[socks_pass]}"
    svc_up "mili-socks@$name.service"
  fi
  # record port claims
  [[ "${ST[variant]}" == fou ]] && ports_claim "$name" udp "${ST[fou_port]}" "0.0.0.0"
  [[ "${ST[mode]}" == socks && "${ST[role]}" == foreign ]] && ports_claim "$name" tcp "${ST[socks_port]}" "${ST[inner_local]}"
}

t_gre_down() {  # <name>
  st_load "$1"; local name="$1"
  svc_down "mili-l3@$name.service"
  [[ "${ST[mode]}" == socks && "${ST[role]}" == foreign ]] && svc_down "mili-socks@$name.service"
  t_gre_ifdown "$name" 2>/dev/null || true
  fw_remove "$name"
}

t_gre_purge() { st_load "$1"; pool_inner_release "${ST[inner_n]}"; pool_meta_release "$1"; }

t_gre_unit() { echo "mili-l3@$1.service"; }

t_gre_health() {  # <name> : ping inner peer across tunnel
  st_load "$1"
  ping -c1 -W2 -I "$(_gre_if "$1")" "${ST[inner_peer]}" >/dev/null 2>&1
}

t_gre_ports() {  # <name> : proto:port:bind list
  st_load "$1"
  [[ "${ST[variant]}" == fou ]] && echo "udp:${ST[fou_port]}:0.0.0.0"
  [[ "${ST[mode]}" == socks ]] && echo "tcp:${ST[socks_port]}:${ST[inner_local]}"
}

t_gre_info() {  # <name>
  st_load "$1"
  ui_kv "variant" "${ST[variant]}"
  ui_kv "mode"    "${ST[mode]}"
  ui_kv "role"    "${ST[role]}"
  ui_kv "peer"    "${ST[peer_ip]}"
  ui_kv "inner"   "${ST[inner_local]} <-> ${ST[inner_peer]} (/30)"
  ui_kv "mtu/ttl" "${ST[mtu]}/${ST[ttl]}"
  [[ "${ST[variant]}" == fou ]] && ui_kv "fou udp" "${ST[fou_port]}"
  case "${ST[mode]}" in
    socks)
      # the SOCKS server runs on the FOREIGN inner IP; Iran reaches it over the tunnel
      local saddr; [[ "${ST[role]}" == iran ]] && saddr="${ST[inner_peer]}" || saddr="${ST[inner_local]}"
      echo; xui_outbound_box "$saddr" "${ST[socks_port]}" "${ST[socks_user]}" "${ST[socks_pass]}" ;;
    forward) ui_kv "forward" "${ST[fwd]}" ;;
    l3)      ui_kv "exit" "via foreign MASQUERADE (freedom outbound, sendThrough ${ST[inner_local]})" ;;
  esac
}

t_gre_xui() {  # <name> : 3x-ui outbound helper
  st_load "$1"; local name="$1"
  case "${ST[mode]}" in
    socks)
      # Iran points x-ui at the FOREIGN inner IP (reachable over tunnel)
      local addr; [[ "${ST[role]}" == iran ]] && addr="${ST[inner_peer]}" || addr="${ST[inner_local]}"
      xui_help_socks "$name" "$addr" "${ST[socks_port]}" "${ST[socks_user]}" "${ST[socks_pass]}" ;;
    l3)
      ui_head "Use tunnel '$name' with 3x-ui (L3 exit)"
      ui_info "Freedom outbound bound to this server's inner IP:"
      xui_freedom_json "mili-$name" "${ST[inner_local]}"
      ui_note "Then route selected inbounds to outbound 'mili-$name'." ;;
    forward)
      ui_head "Use tunnel '$name' with 3x-ui (port forward)"
      ui_note "Iran public ports ${ST[fwd]} reach the foreign target over GRE."
      ui_note "Point your subscription Host/address at this Iran server's IP + the local port." ;;
  esac
}

t_gre_test() {  # <name>
  st_load "$1"
  ui_info "ping inner peer ${ST[inner_peer]} over $(_gre_if "$1")"
  if t_gre_health "$1"; then ui_ok "tunnel reachable"; else ui_err "no reply over tunnel"; fi
  if [[ "${ST[mode]}" == socks ]]; then
    local addr; [[ "${ST[role]}" == iran ]] && addr="${ST[inner_peer]}" || addr="${ST[inner_local]}"
    doctor_socks "$addr" "${ST[socks_port]}" "${ST[socks_user]}" "${ST[socks_pass]}"
  fi
}

# ---- pairing (iran generates; foreign imports + replies; iran finalizes) ----
# forward code: iran -> foreign. Carries the generator's (iran) public IP as
# gen_ip so foreign can set its remote. foreign auto-detects its own IP.
t_gre_pair_export() {  # <name>
  st_load "$1"
  cat <<EOF
type=gre
name=${ST[name]}
role=foreign
variant=${ST[variant]}
mode=${ST[mode]}
inner_n=${ST[inner_n]}
key=${ST[key]}
mtu=${ST[mtu]}
ttl=${ST[ttl]}
fou_port=${ST[fou_port]:-}
gen_ip=${ST[my_ip]}
socks_port=${ST[socks_port]:-}
socks_user=${ST[socks_user]:-}
socks_pass=${ST[socks_pass]:-}
fwd=${ST[fwd]:-}
EOF
}

t_gre_pair_import() {  # <payload>  (runs on foreign)
  local p="$1" name n
  name="$(pair_field "$p" name)"; n="$(pair_field "$p" inner_n)"
  ST=(); ST[name]="$name"; ST[type]=gre; ST[role]=foreign
  ST[variant]="$(pair_field "$p" variant)"; ST[mode]="$(pair_field "$p" mode)"
  ST[inner_n]="$n"; ST[key]="$(pair_field "$p" key)"
  ST[mtu]="$(pair_field "$p" mtu)"; ST[ttl]="$(pair_field "$p" ttl)"
  ST[fou_port]="$(pair_field "$p" fou_port)"
  ST[my_ip]="$(sys_public_ip4)"                 # foreign auto-detects its own IP
  ST[peer_ip]="$(pair_field "$p" gen_ip)"       # peer = iran (from the code)
  ui_ok "this server's public IP: ${ST[my_ip]}  (peer iran: ${ST[peer_ip]})"
  ST[inner_local]="$(_gre_inner_local "$n" foreign)"
  ST[inner_peer]="$(_gre_inner_peer  "$n" foreign)"
  ST[socks_port]="$(pair_field "$p" socks_port)"
  ST[socks_user]="$(pair_field "$p" socks_user)"
  ST[socks_pass]="$(pair_field "$p" socks_pass)"
  ST[fwd]="$(pair_field "$p" fwd)"
  pool_inner_claim "$n" "$name"
  st_save
  t_gre_render "$name"; t_gre_up "$name"
  st_set state up; st_save
}

# reply code: foreign -> iran, carrying foreign's own IP so iran sets its remote
t_gre_pair_reply() {  # <name>  (runs on foreign)
  st_load "$1"
  cat <<EOF
type=gre
name=${ST[name]}
reply=1
peer_ip=${ST[my_ip]}
EOF
}

# finalize on iran: learn foreign's IP, bring the link up
t_gre_pair_finalize() {  # <payload>  (runs on iran)
  local p="$1" name
  name="$(pair_field "$p" name)"
  st_load "$name" || return 1
  ST[peer_ip]="$(pair_field "$p" peer_ip)"
  [[ "${ST[mode]}" == l3 && -z "${ST[table]:-}" ]] && ST[table]="$(pool_table_id)"
  st_save
  t_gre_render "$name"; t_gre_up "$name"
  st_set state up; st_save
}

# ===== tunnels/grefrp.sh =====
# shellcheck shell=bash
# mili :: tunnels/grefrp.sh - GRE + FRP combined.
# A private GRE carries an FRP session: frps binds the IRAN INNER IP, frpc on
# FOREIGN dials it over GRE. No public FRP port is ever exposed -> only GRE/FOU
# is visible on the wire. Optional failover note when GRE is down.
#
# roles: iran (frps) | foreign (frpc)

t_register grefrp
feature "tunnel.grefrp" free

MILI_GRF_S="$MILI_ETC/engines/frps"
MILI_GRF_C="$MILI_ETC/engines/frpc"

t_grefrp_meta() {
  echo "id=grefrp"
  echo "title=GRE + FRP  (private, stealth)"
  echo "tier=free"
  echo "layer=fwd"
  echo "roles=iran foreign"
  echo "primary=iran"     # iran (frps) generates; foreign imports + replies
  echo "twoway=yes"
  echo "cores=frp"
}

_grf_if() { printf 'mgrf-%s' "$1"; }
_grf_inner_local() { local n="$1" r="$2"; [[ "$r" == iran ]] && echo "10.77.$n.1" || echo "10.77.$n.2"; }
_grf_inner_peer()  { local n="$1" r="$2"; [[ "$r" == iran ]] && echo "10.77.$n.2" || echo "10.77.$n.1"; }

t_grefrp_wizard() {  # <role> <level>  (runs on the GENERATOR = iran side)
  local role="$1" level="$2" n
  ST[my_ip]="$(sys_public_ip4)"
  [[ "$level" == advanced ]] && ST[my_ip]="$(ui_ask "This server public IP (auto-detected)" "${ST[my_ip]}")"
  ui_ok "this server's public IP: ${ST[my_ip]}"
  ST[peer_ip]="${ST[peer_ip]:-}"   # arrives via the reply code

  echo; ui_info "GRE variant: 1) gre  2) gre+fou (recommended)"
  local gv; gv="$(ui_ask 'variant' "${ST[variant]:-2}")"
  case "$gv" in 1) ST[variant]=gre;; *) ST[variant]=fou;; esac
  [[ "${ST[variant]}" == fou ]] && ST[fou_port]="${ST[fou_port]:-$(sys_rand_port 20000 29999)}"

  if [[ -z "${ST[inner_n]:-}" ]]; then n="$(pool_inner_subnet)" || { ui_err "no inner subnet"; return 1; }; ST[inner_n]="$n"; fi
  [[ -z "${ST[key]:-}" ]] && ST[key]="$(pool_gre_key)"
  ST[inner_local]="$(_grf_inner_local "${ST[inner_n]}" "$role")"
  ST[inner_peer]="$(_grf_inner_peer  "${ST[inner_n]}" "$role")"
  [[ -z "${ST[bind_port]:-}" ]] && ST[bind_port]="$(ports_alloc_internal)"
  [[ -z "${ST[token]:-}" ]] && ST[token]="$(sys_rand_token 24)"

  echo; ui_info "Usage mode: 1) socks  2) forward"
  local um; um="$(ui_ask 'mode' "${ST[mode]:-1}")"
  case "$um" in 2) ST[mode]=forward;; *) ST[mode]=socks;; esac
  case "${ST[mode]}" in
    socks)
      ST[remote_port]="${ST[remote_port]:-$(ports_alloc_socks)}"
      [[ -z "${ST[socks_user]:-}" ]] && ST[socks_user]="mili"
      [[ -z "${ST[socks_pass]:-}" ]] && ST[socks_pass]="$(sys_rand_token 18)" ;;
    forward)
      ST[fwd]="$(ui_ask 'Forward spec iranPublic=foreignLocal/proto' "${ST[fwd]:-}")" ;;
  esac

  if [[ "$level" == advanced ]]; then
    ST[mtu]="$(ui_ask 'GRE MTU' "${ST[mtu]:-1400}")"
    ST[transport]="$(ui_ask 'frp transport tcp|kcp|quic|websocket' "${ST[transport]:-tcp}")"
    ST[tls]="$(ui_ask 'frp TLS true/false' "${ST[tls]:-true}")"
  else
    ST[mtu]="${ST[mtu]:-1400}"; ST[transport]="${ST[transport]:-tcp}"; ST[tls]="${ST[tls]:-true}"
  fi
  ST[ttl]="${ST[ttl]:-255}"
  return 0
}

# ---- GRE interface (reuses the same plumbing idea as gre.sh) ---------------
t_grefrp_ifup() {  # <name>
  st_load "$1"; local name="$1" ifc; ifc="$(_grf_if "$name")"
  run modprobe ip_gre 2>/dev/null || true
  if [[ "${ST[variant]}" == fou ]]; then
    run modprobe fou 2>/dev/null || true
    run ip fou add port "${ST[fou_port]}" ipproto 47 2>/dev/null || true
    run ip link add "$ifc" type gre local "${ST[my_ip]}" remote "${ST[peer_ip]}" \
      key "${ST[key]}" ttl "${ST[ttl]}" encap fou encap-sport auto encap-dport "${ST[fou_port]}" 2>/dev/null \
      || run ip link add "$ifc" type gre local "${ST[my_ip]}" remote "${ST[peer_ip]}" key "${ST[key]}" ttl "${ST[ttl]}"
  else
    run ip link add "$ifc" type gre local "${ST[my_ip]}" remote "${ST[peer_ip]}" key "${ST[key]}" ttl "${ST[ttl]}"
  fi
  run ip addr add "${ST[inner_local]}/30" dev "$ifc" 2>/dev/null || true
  run ip link set "$ifc" mtu "${ST[mtu]}" up
}
t_grefrp_ifdown() {  # <name>
  st_load "$1"; local ifc; ifc="$(_grf_if "$1")"
  run ip link del "$ifc" 2>/dev/null || true
  [[ "${ST[variant]}" == fou ]] && run ip fou del port "${ST[fou_port]}" 2>/dev/null || true
}

t_grefrp_render() {  # <name> : frp config bound to inner IPs
  st_load "$1"; local name="$1"
  if [[ "${ST[role]}" == iran ]]; then
    run mkdir -p "$MILI_GRF_S"; local f="$MILI_GRF_S/$name.toml"
    [[ "${MILI_DRYRUN:-0}" == 1 ]] && { ui_info "[dry] frps(inner) config for $name"; return 0; }
    cat >"$f" <<EOF
# mili GRE+FRP frps (Iran) bound to inner IP for tunnel $name
bindAddr = "${ST[inner_local]}"
bindPort = ${ST[bind_port]}
auth.method = "token"
auth.token = "${ST[token]}"
webServer.addr = "127.0.0.1"
log.to = "/var/log/mili/frps-$name.log"
log.level = "info"
EOF
    chmod 600 "$f"
  else
    run mkdir -p "$MILI_GRF_C"; local f="$MILI_GRF_C/$name.toml"
    [[ "${MILI_DRYRUN:-0}" == 1 ]] && { ui_info "[dry] frpc(inner) config for $name"; return 0; }
    {
      cat <<EOF
# mili GRE+FRP frpc (Foreign) dialing Iran inner IP over GRE for tunnel $name
serverAddr = "${ST[inner_peer]}"
serverPort = ${ST[bind_port]}
auth.method = "token"
auth.token = "${ST[token]}"
transport.protocol = "${ST[transport]}"
transport.tls.enable = ${ST[tls]}
log.to = "/var/log/mili/frpc-$name.log"
log.level = "info"
EOF
      if [[ "${ST[mode]}" == socks ]]; then
        cat <<EOF

[[proxies]]
name = "$name-socks"
type = "tcp"
remotePort = ${ST[remote_port]}
[proxies.plugin]
type = "socks5"
username = "${ST[socks_user]}"
password = "${ST[socks_pass]}"
EOF
      else
        local item lport rport proto i=0
        IFS=',' read -ra items <<<"${ST[fwd]}"
        for item in "${items[@]}"; do
          [[ -z "$item" ]] && continue
          proto="${item##*/}"; item="${item%/*}"; lport="${item%%=*}"; rport="${item##*=}"
          [[ "$proto" != udp ]] && proto=tcp
          cat <<EOF

[[proxies]]
name = "$name-fwd$i"
type = "$proto"
localIP = "127.0.0.1"
localPort = $rport
remotePort = $lport
EOF
          i=$((i+1))
        done
      fi
    } >"$f"
    chmod 600 "$f"
  fi
}

t_grefrp_fw_apply() {  # <name>
  st_load "$1"; local name="$1"
  # only GRE/FOU is public
  if [[ "${ST[variant]}" == fou ]]; then
    fw_allow "$name" udp "${ST[fou_port]}" "${ST[peer_ip]}"; fw_ufw_mirror "$name" udp "${ST[fou_port]}" "${ST[peer_ip]}"
  else
    fw_allow_proto "$name" 47 "${ST[peer_ip]}"; fw_ufw_allow_gre "$name" "${ST[peer_ip]}"
  fi
  fw_mss "$name" "$(_grf_if "$name")" pmtu
  if [[ "${ST[role]}" == iran ]]; then
    if [[ "${ST[mode]}" == socks ]]; then
      fw_loopback_guard "$name" tcp "${ST[remote_port]}"
    else
      local item lport proto
      IFS=',' read -ra items <<<"${ST[fwd]}"
      for item in "${items[@]}"; do
        [[ -z "$item" ]] && continue
        proto="${item##*/}"; item="${item%/*}"; lport="${item%%=*}"
        [[ "$proto" != udp ]] && proto=tcp
        fw_allow "$name" "$proto" "$lport"; fw_ufw_mirror "$name" "$proto" "$lport"
      done
    fi
  fi
}

t_grefrp_up() {  # <name>
  st_load "$1"; local name="$1"
  require_root
  if [[ -z "${ST[peer_ip]:-}" ]]; then
    ui_warn "waiting for the peer's reply code before GRE+FRP can come up"
    ui_note "import the REPLY code from the other server to finish '$name'."
    return 0
  fi
  cores_ensure frp
  t_grefrp_fw_apply "$name"
  svc_up "mili-l3@$name.service"       # brings GRE iface up (via _l3 -> ifup)
  t_grefrp_render "$name"
  if [[ "${ST[role]}" == iran ]]; then
    svc_up "mili-frps@$name.service"
    [[ "${ST[mode]}" == socks ]] && ports_claim "$name" tcp "${ST[remote_port]}" "127.0.0.1"
  else
    svc_up "mili-frpc@$name.service"
  fi
  [[ "${ST[variant]}" == fou ]] && ports_claim "$name" udp "${ST[fou_port]}" "0.0.0.0"
}

t_grefrp_down() {  # <name>
  st_load "$1"; local name="$1"
  svc_down "mili-frps@$name.service" 2>/dev/null || true
  svc_down "mili-frpc@$name.service" 2>/dev/null || true
  svc_down "mili-l3@$name.service" 2>/dev/null || true
  t_grefrp_ifdown "$name" 2>/dev/null || true
  fw_remove "$name"
}

t_grefrp_purge() {
  st_load "$1"
  run rm -f "$MILI_GRF_S/$1.toml" "$MILI_GRF_C/$1.toml" 2>/dev/null || true
  pool_inner_release "${ST[inner_n]}"; pool_meta_release "$1"
}

t_grefrp_unit() { st_load "$1"; [[ "${ST[role]}" == iran ]] && echo "mili-frps@$1.service" || echo "mili-frpc@$1.service"; }

t_grefrp_health() {  # <name> : GRE reachable AND frp link up
  st_load "$1"
  ping -c1 -W2 -I "$(_grf_if "$1")" "${ST[inner_peer]}" >/dev/null 2>&1 || return 1
  if [[ "${ST[role]}" == iran ]]; then
    ss -Hlnt 2>/dev/null | grep -q "${ST[inner_local]}:${ST[bind_port]}" || \
    ss -Hlnt 2>/dev/null | awk '{print $4}' | grep -qE ":${ST[bind_port]}\$"
  else
    svc_active "mili-frpc@$1.service"
  fi
}

t_grefrp_ports() {
  st_load "$1"
  [[ "${ST[variant]}" == fou ]] && echo "udp:${ST[fou_port]}:0.0.0.0"
  [[ "${ST[role]}" == iran && "${ST[mode]}" == socks ]] && echo "tcp:${ST[remote_port]}:127.0.0.1"
}

t_grefrp_info() {
  st_load "$1"
  ui_kv "variant" "${ST[variant]} (private GRE$([[ ${ST[variant]} == fou ]] && echo '+FOU'))"
  ui_kv "role/mode" "${ST[role]} / ${ST[mode]}"
  ui_kv "inner" "${ST[inner_local]} <-> ${ST[inner_peer]}"
  ui_kv "frp" "inner :${ST[bind_port]} transport=${ST[transport]} tls=${ST[tls]}"
  [[ "${ST[variant]}" == fou ]] && ui_kv "fou udp" "${ST[fou_port]} (only public port)"
  [[ "${ST[role]}" == iran && "${ST[mode]}" == socks ]] && { echo; xui_outbound_box "127.0.0.1" "${ST[remote_port]}" "${ST[socks_user]}" "${ST[socks_pass]}"; }
  [[ "${ST[mode]}" == forward ]] && ui_kv "forward" "${ST[fwd]}"
}

t_grefrp_xui() {
  st_load "$1"; local name="$1"
  if [[ "${ST[mode]}" == socks && "${ST[role]}" == iran ]]; then
    xui_help_socks "$name" "127.0.0.1" "${ST[remote_port]}" "${ST[socks_user]}" "${ST[socks_pass]}"
  elif [[ "${ST[mode]}" == socks ]]; then
    ui_warn "SOCKS endpoint is on the IRAN server (127.0.0.1:${ST[remote_port]}); run helper there."
  else
    ui_head "Use '$name' with 3x-ui (port forward over GRE+FRP)"
    ui_note "Foreign ports published on Iran public ports: ${ST[fwd]}"
  fi
}

t_grefrp_test() {
  st_load "$1"
  ping -c1 -W2 -I "$(_grf_if "$1")" "${ST[inner_peer]}" >/dev/null 2>&1 && ui_ok "GRE up" || ui_err "GRE down"
  [[ "${ST[mode]}" == socks && "${ST[role]}" == iran ]] && doctor_socks 127.0.0.1 "${ST[remote_port]}" "${ST[socks_user]}" "${ST[socks_pass]}"
}

t_grefrp_pair_export() {  # iran -> foreign
  st_load "$1"
  cat <<EOF
type=grefrp
name=${ST[name]}
role=foreign
variant=${ST[variant]}
mode=${ST[mode]}
inner_n=${ST[inner_n]}
key=${ST[key]}
mtu=${ST[mtu]}
ttl=${ST[ttl]}
fou_port=${ST[fou_port]:-}
gen_ip=${ST[my_ip]}
bind_port=${ST[bind_port]}
token=${ST[token]}
transport=${ST[transport]}
tls=${ST[tls]}
remote_port=${ST[remote_port]:-}
socks_user=${ST[socks_user]:-}
socks_pass=${ST[socks_pass]:-}
fwd=${ST[fwd]:-}
EOF
}

t_grefrp_pair_import() {  # runs on foreign
  local p="$1" name n
  name="$(pair_field "$p" name)"; n="$(pair_field "$p" inner_n)"
  ST=(); ST[name]="$name"; ST[type]=grefrp; ST[role]=foreign
  ST[variant]="$(pair_field "$p" variant)"; ST[mode]="$(pair_field "$p" mode)"
  ST[inner_n]="$n"; ST[key]="$(pair_field "$p" key)"
  ST[mtu]="$(pair_field "$p" mtu)"; ST[ttl]="$(pair_field "$p" ttl)"
  ST[fou_port]="$(pair_field "$p" fou_port)"
  ST[my_ip]="$(sys_public_ip4)"
  ST[peer_ip]="$(pair_field "$p" gen_ip)"
  ui_ok "this server's public IP: ${ST[my_ip]}  (peer iran: ${ST[peer_ip]})"
  ST[inner_local]="$(_grf_inner_local "$n" foreign)"
  ST[inner_peer]="$(_grf_inner_peer  "$n" foreign)"
  ST[bind_port]="$(pair_field "$p" bind_port)"; ST[token]="$(pair_field "$p" token)"
  ST[transport]="$(pair_field "$p" transport)"; ST[tls]="$(pair_field "$p" tls)"
  ST[remote_port]="$(pair_field "$p" remote_port)"
  ST[socks_user]="$(pair_field "$p" socks_user)"; ST[socks_pass]="$(pair_field "$p" socks_pass)"
  ST[fwd]="$(pair_field "$p" fwd)"
  pool_inner_claim "$n" "$name"
  st_save
  t_grefrp_up "$name"; st_set state up; st_save
}

t_grefrp_pair_reply() {  # foreign -> iran
  st_load "$1"
  cat <<EOF
type=grefrp
name=${ST[name]}
reply=1
peer_ip=${ST[my_ip]}
EOF
}

t_grefrp_pair_finalize() {  # runs on iran
  local p="$1" name
  name="$(pair_field "$p" name)"
  st_load "$name" || return 1
  ST[peer_ip]="$(pair_field "$p" peer_ip)"
  st_save
  t_grefrp_up "$name"; st_set state up; st_save
}

# ===== tunnels/hedioum.sh =====
# shellcheck shell=bash
# mili :: tunnels/hedioum.sh - hedioum/Hedioum-Pool-Tunnel (mimic SOCKS pool).
#
# NATIVE PAIRING: mili mirrors hedioum's own setup steps and moves ONLY hedioum's
# own v2 pairing token between servers (no mili pairing code).
#   foreign (egress): hedioum-tunnel setup-foreign ...           -> v2 token
#   iran    (hub)   : hedioum-tunnel add-node --alias <name> --token <v2> ...
# hedioum runs its OWN hedioum.service and keeps ONE config per server in
# /etc/hedioum/hedioum.json (role foreign OR iran; an iran hub holds many nodes,
# keyed by alias = the mili tunnel name).
#
# Facts pinned to hedioum v0.11.0 (see cores.sh):
#  - v2 token = base64url_nopad(JSON {v:2, ip, auth(32hex), persona?, sni?, eps{mimic:port}})
#  - setup-*/add-node exit 1 on any error and restart hedioum.service themselves
#  - persona sets are deterministic from the auth key (ported below for preview)

t_register hedioum
feature "tunnel.hedioum" free

HED_CFG="${HED_CFG:-/etc/hedioum/hedioum.json}"
HED_UNIT="hedioum.service"
HED_MIMICS=(ssh tls https-alt smtp imap smtps imaps directadmin docker grafana prometheus cpanel whm webmail postgres mysql)
HED_PERSONAS=(cpanel directadmin devops)

# ============================================================================
# pure helpers (unit-tested in tests/unit/hedioum.bats)
# ============================================================================

_hed_is_hex32() { [[ "$1" =~ ^[A-Fa-f0-9]{32}$ ]]; }
_hed_is_mimic() { [[ " ${HED_MIMICS[*]} " == *" $1 "* ]]; }

_hed_mimic_default_port() {  # <mimic>
  case "$1" in
    ssh) echo 22 ;; tls) echo 443 ;; https-alt) echo 8443 ;; smtp) echo 587 ;;
    imap) echo 143 ;; smtps) echo 465 ;; imaps) echo 993 ;; directadmin) echo 2222 ;;
    docker) echo 5000 ;; grafana) echo 3000 ;; prometheus) echo 9090 ;; cpanel) echo 2083 ;;
    whm) echo 2087 ;; webmail) echo 2096 ;; postgres) echo 5432 ;; mysql) echo 3306 ;;
    *) return 1 ;;
  esac
}
# setup-foreign flag that sets a mimic's public port
_hed_mimic_port_flag() { [[ "$1" == ssh ]] && echo "--listen-port" || echo "--$1-port"; }
# ST key holding a per-mimic port override (state keys can't contain '-')
_hed_port_key() { printf 'port_%s' "${1//-/_}"; }

# ---- hedioum.json readers (Go MarshalIndent layout: top keys at 2 spaces) ----
_hed_cfg_get() {  # <key> [file] -> top-level scalar value
  local f="${2:-$HED_CFG}"
  [[ -r "$f" ]] || return 1
  awk -v k="$1" '
    $0 ~ "^  \"" k "\": " {
      v = $0; sub(/^[^:]*: /, "", v); sub(/,$/, "", v); gsub(/^"|"$/, "", v); print v; exit
    }' "$f"
}
_hed_cfg_role() { _hed_cfg_get role "${1:-$HED_CFG}" 2>/dev/null; }

_hed_cfg_mimics() {  # [file] -> "type port" per configured foreign mimic
  local f="${1:-$HED_CFG}" out
  [[ -r "$f" ]] || return 1
  out="$(awk '
    /^  "mimics": \[/ { m = 1; next }
    m && /^  \]/      { m = 0 }
    m && /^      "type": / { t = $0; sub(/^[^:]*: "/, "", t); sub(/".*$/, "", t) }
    m && /^      "port": / { p = $0; sub(/^[^:]*: /, "", p); sub(/,$/, "", p); if (t != "") print t, p; t = "" }
  ' "$f")"
  if [[ -z "$out" && "$(_hed_cfg_role "$f")" == foreign ]]; then
    # legacy config without mimics: hedioum synthesizes one SSH listener
    local lp; lp="$(_hed_cfg_get foreign_listen_port "$f")"
    out="ssh ${lp:-22}"
  fi
  [[ -n "$out" ]] && printf '%s\n' "$out"
}

_hed_cfg_sni() {  # [file] -> first mimic server_name, else domain (as setup-foreign does)
  local f="${1:-$HED_CFG}" s
  s="$(awk '
    /^  "mimics": \[/ { m = 1; next }
    m && /^  \]/      { m = 0 }
    m && /"server_name": / { v = $0; sub(/^[^:]*: "/, "", v); sub(/".*$/, "", v); if (v != "") { print v; exit } }
  ' "$f" 2>/dev/null)"
  [[ -z "$s" ]] && s="$(_hed_cfg_get domain "$f")"
  printf '%s' "$s"
}

_hed_cfg_nodes() {  # [file] -> one hub node alias per line
  local f="${1:-$HED_CFG}"
  [[ -r "$f" ]] || return 0
  awk '
    /^  "foreign_nodes": \[/ { m = 1; next }
    m && /^  \]/             { m = 0 }
    m && /^      "alias": /  { v = $0; sub(/^[^:]*: "/, "", v); sub(/",?$/, "", v); print v }
  ' "$f"
}
_hed_cfg_has_node()   { _hed_cfg_nodes "${2:-$HED_CFG}" | grep -qxF -- "$1"; }
_hed_cfg_node_count() { _hed_cfg_nodes "${1:-$HED_CFG}" | grep -c . ; }

# ---- v2 pairing token ------------------------------------------------------
# _hed_token_decode <str>
#   0 = valid v2  -> sets HT_IP HT_AUTH HT_PERSONA HT_SNI HT_EPS("type:port ...")
#   2 = legacy v1 bare 32-hex auth key (HT_AUTH set)
#   1 = invalid  -> HT_ERR holds hedioum's own wording
_hed_token_decode() {
  local s json v eps e port
  s="$(printf '%s' "$1" | tr -d '[:space:]')"
  HT_IP='' HT_AUTH='' HT_PERSONA='' HT_SNI='' HT_EPS='' HT_ERR=''
  [[ -z "$s" ]] && { HT_ERR="empty token"; return 1; }
  if _hed_is_hex32 "$s"; then HT_AUTH="$s"; return 2; fi
  [[ "$s" =~ ^[A-Za-z0-9_+/=-]+$ ]] && json="$(_b64url_dec "$s")"
  if [[ "$json" != \{* ]]; then
    HT_ERR="token is neither a v1 hex token nor a valid v2 pairing token"; return 1
  fi
  v="$(printf '%s' "$json" | sed -n 's/.*"v":\([0-9][0-9]*\).*/\1/p')"
  if [[ "$v" != 2 ]]; then
    HT_ERR="unsupported pairing token version ${v:-?} (want 2)"; return 1
  fi
  HT_IP="$(printf '%s' "$json"      | sed -n 's/.*"ip":"\([^"]*\)".*/\1/p')"
  HT_AUTH="$(printf '%s' "$json"    | sed -n 's/.*"auth":"\([^"]*\)".*/\1/p')"
  HT_PERSONA="$(printf '%s' "$json" | sed -n 's/.*"persona":"\([^"]*\)".*/\1/p')"
  HT_SNI="$(printf '%s' "$json"     | sed -n 's/.*"sni":"\([^"]*\)".*/\1/p')"
  eps="$(printf '%s' "$json"        | sed -n 's/.*"eps":{\([^}]*\)}.*/\1/p')"
  HT_EPS="$(printf '%s' "$eps" | tr ',' '\n' | sed -n 's/^"\([a-z-]*\)":\([0-9-]*\)$/\1:\2/p' | paste -sd' ' -)"
  _hed_is_hex32 "$HT_AUTH" || { HT_ERR="pairing token has an invalid auth key"; return 1; }
  [[ -n "$HT_IP" ]]        || { HT_ERR="pairing token has no exit IP"; return 1; }
  [[ -n "$HT_EPS" ]]       || { HT_ERR="pairing token has no endpoints"; return 1; }
  for e in $HT_EPS; do
    port="${e#*:}"
    if ! [[ "$port" =~ ^[0-9]+$ ]] || (( port < 1 || port > 65535 )); then
      HT_ERR="pairing token endpoint \"${e%%:*}\" has invalid port $port"; return 1
    fi
  done
  return 0
}

_hed_eps_count() { local -a a=($1); printf '%s' "${#a[@]}"; }
_hed_eps_pretty() { printf '%s' "$1" | sed 's/ /, /g'; }

# _hed_token_encode <ip> <auth> <persona> <sni> <eps "type:port ...">
# byte-identical to Go json.Marshal(pairing.Token) + base64.RawURLEncoding
_hed_token_encode() {
  local ip="$1" auth="$2" persona="$3" sni="$4" eps="$5" json body='' e
  for e in $(printf '%s\n' $eps | LC_ALL=C sort -t: -k1,1); do
    [[ -n "$body" ]] && body+=','
    body+="\"${e%%:*}\":${e#*:}"
  done
  json="{\"v\":2,\"ip\":\"$ip\",\"auth\":\"$auth\""
  [[ -n "$persona" ]] && json+=",\"persona\":\"$persona\""
  [[ -n "$sni" ]] && json+=",\"sni\":\"$sni\""
  json+=",\"eps\":{$body}}"
  printf '%s' "$json" | _b64url_enc
}

# _hed_token_build <exit-ip> [file] : the token for the foreign config on disk
_hed_token_build() {
  local ip="$1" f="${2:-$HED_CFG}" auth persona sni eps
  [[ -n "$ip" && "$(_hed_cfg_role "$f")" == foreign ]] || return 1
  auth="$(_hed_cfg_get auth_token "$f")"
  persona="$(_hed_cfg_get persona "$f")"
  sni="$(_hed_cfg_sni "$f")"
  eps="$(_hed_cfg_mimics "$f" | awk '{printf "%s%s:%s", (NR>1?" ":""), $1, $2}')"
  [[ -n "$auth" && -n "$eps" ]] || return 1
  _hed_token_encode "$ip" "$auth" "$persona" "$sni" "$eps"
}

# hedioum's own printed token, if present in setup-foreign output (auth must match)
_hed_token_from_output() {  # <file> <auth>
  local line
  while IFS= read -r line; do
    line="$(printf '%s' "$line" | sed -E $'s/\x1b\\[[0-9;]*m//g' | tr -d '[:space:]')"
    [[ "$line" =~ ^[A-Za-z0-9_-]{40,}$ ]] || continue
    _hed_token_decode "$line" && [[ "$HT_AUTH" == "$2" ]] && { printf '%s' "$line"; return 0; }
  done <"$1"
  return 1
}

# ---- persona (port of internal/persona/persona.go) --------------------------
_hed_sha256() { sha256sum | awk '{print $1}'; }

_hed_persona_auto() {  # <seed>
  local h; h="$(printf 'hedioum-persona\0%s' "$1" | _hed_sha256)"
  printf '%s' "${HED_PERSONAS[$(( 16#${h:0:2} % 3 ))]}"
}

_hed_persona_resolve() {  # <name> <seed> -> comma list, ssh first (= persona.Resolve)
  local name="$1" seed="$2" core pool m k sorted
  case "$name" in
    cpanel)      core="tls cpanel whm webmail"
                 pool="https-alt smtp smtps imaps imap postgres mysql docker" ;;
    directadmin) core="tls directadmin"
                 pool="https-alt smtp smtps imaps imap postgres mysql docker grafana" ;;
    devops)      core="tls https-alt docker grafana prometheus"
                 pool="postgres mysql smtp smtps imap imaps" ;;
    *) return 1 ;;
  esac
  local -a set=(ssh $core)
  sorted="$(for m in $pool; do
              k="$(printf 'hedioum-fill\0%s\0%s' "$seed" "$m" | _hed_sha256)"
              printf '%s %s\n' "${k:0:16}" "$m"
            done | LC_ALL=C sort -k1,1 -k2,2 | awk '{print $2}')"
  for m in $sorted; do
    (( ${#set[@]} - 1 >= 9 )) && break
    [[ " ${set[*]} " == *" $m "* ]] || set+=("$m")
  done
  (( ${#set[@]} - 1 == 9 )) || return 1
  local IFS=,; printf '%s' "${set[*]}"
}

# "all" or a comma list -> validated canonical comma list (on error: prints the reason, rc 1)
_hed_expand_mimics() {  # <spec>
  local spec="${1// /}" m out=()
  if [[ "$spec" == all ]]; then local IFS=,; printf '%s' "${HED_MIMICS[*]}"; return 0; fi
  for m in ${spec//,/ }; do
    _hed_is_mimic "$m" || { printf 'unknown mimic "%s" (want one of %s|all)' "$m" "$(IFS='|'; echo "${HED_MIMICS[*]}")"; return 1; }
    [[ " ${out[*]} " == *" $m "* ]] || out+=("$m")
  done
  (( ${#out[@]} )) || { printf 'no mimics selected'; return 1; }
  local IFS=,; printf '%s' "${out[*]}"
}

# ============================================================================
# system helpers
# ============================================================================
_hed_bin() { cores_bin_ok hedioum-tunnel && { cores_path hedioum-tunnel; return 0; }; return 1; }

# binary + hedioum's own systemd unit (idempotent: refreshes the /usr/local/bin copy)
_hed_install() {
  cores_ensure hedioum || { ui_err "could not install the hedioum core"; return 1; }
  local b out
  b="$(_hed_bin)" || { ui_err "hedioum binary missing"; return 1; }
  out="$(run "$b" install 2>&1)" || { ui_err "hedioum-tunnel install failed:"; printf '%s\n' "$out" | tail -n 5 | sed 's/^/    /'; return 1; }
}

# mili hedioum tunnels on this box, optionally by role (reads files; never clobbers ST)
_hed_tunnels() {  # [role] [exclude-name]
  local f n
  for f in "$MILI_TUNDIR"/*.conf; do
    [[ -f "$f" ]] || continue
    grep -qx 'type=hedioum' "$f" || continue
    [[ -n "${1:-}" ]] && ! grep -qx "role=$1" "$f" && continue
    n="${f##*/}"; n="${n%.conf}"
    [[ "$n" == "${2:-}" ]] && continue
    printf '%s\n' "$n"
  done
}

_hed_listening() { ss -Hltn 2>/dev/null | awk '{print $4}' | grep -qE ":$1\$"; }

# who listens on tcp <port>? prints process name ('?' if hidden); rc 1 = free
_hed_port_listener() {
  local line who
  line="$(ss -Hltnp 2>/dev/null | awk -v p="$1" '{n = split($4, a, ":"); if (a[n] == p) { print; exit }}')"
  [[ -z "$line" ]] && return 1
  who="$(printf '%s' "$line" | grep -oE 'users:\(\("[^"]+' | head -n1 | sed 's/^users:(("//')"
  printf '%s' "${who:-?}"
}

# is <port> unavailable for a hedioum mimic? prints the reason. hedioum's own
# listeners don't count (re-setup); MILI_RESERVED is NOT used (443 is a real mimic port)
_hed_port_busy() {  # <port> [exclude-tunnel]
  local port="$1" excl="${2:-}" who
  if who="$(_hed_port_listener "$port")" && [[ "$who" != hedioum* ]]; then
    printf '%s' "$who"; return 0
  fi
  if ports_xui 2>/dev/null | grep -qx "$port"; then printf 'x-ui'; return 0; fi
  if [[ -f "$MILI_PORTSDB" ]] && awk -F'|' -v pt="$port" -v ex="$excl" '$3==pt && $1!=ex {f=1} END {exit !f}' "$MILI_PORTSDB"; then
    printf 'another mili tunnel'; return 0
  fi
  return 1
}

# first free public port not in <taken...>
_hed_free_port() {
  local p t skip
  for (( p = MILI_PUB_LO; p <= MILI_PUB_HI; p++ )); do
    skip=0; for t in "$@"; do [[ "$t" == "$p" ]] && { skip=1; break; }; done
    (( skip )) && continue
    ports_in_use "$p" && continue
    printf '%s' "$p"; return 0
  done
  return 1
}

_hed_sshd_port() { ports_sshd 2>/dev/null | head -n1; }

# the operator's SSH session is proxied by hedioum's SSH mimic (sshd sees 127.0.0.1)
_hed_via_mimic() { [[ "${SSH_CONNECTION:-}" == 127.0.0.1\ * || "${SSH_CONNECTION:-}" == ::1\ * ]]; }

# run a root shell snippet detached from this session after <delay>s (survives a dropped SSH)
_hed_detached() {  # <delay> <script>
  local delay="$1" script="$2"
  if [[ "${MILI_DRYRUN:-0}" == 1 ]]; then printf '%s[dry]%s detached(%ss): %s\n' "${C_GRY:-}" "${C_RST:-}" "$delay" "$script" >&2; return 0; fi
  if sys_has systemd-run; then
    systemd-run --quiet --collect --unit "mili-hedioum-$(date +%s)-$RANDOM" \
      --on-active="${delay}s" /bin/bash -c "$script" >/dev/null 2>&1 && return 0
  fi
  setsid /bin/bash -c "sleep $delay; $script" </dev/null >/dev/null 2>&1 &
}

# systemctl on hedioum.service; detached when it would cut the operator's session
_hed_svc() {  # <systemctl args...>
  if [[ "${ST[role]:-}" == foreign ]] && _hed_via_mimic; then
    ui_warn "you are connected through the hedioum SSH mimic: this session drops in ~5s."
    ui_note "reconnect the same way after ~10s (or straight to OpenSSH: ssh -p ${ST[decoy_port]:-2022} ...)."
    _hed_detached 5 "systemctl $*"
    return 0
  fi
  run systemctl "$@" >/dev/null 2>&1
}

_hed_wait_active() {  # [seconds]
  local i
  for (( i = 0; i < ${1:-8}; i++ )); do svc_active "$HED_UNIT" && return 0; sleep 1; done
  svc_active "$HED_UNIT"
}

_hed_alias() { printf '%s' "${ST[alias]:-${ST[name]}}"; }

# planned foreign endpoints from the wizard answers ("type:port ...")
_hed_plan_eps() {
  local m p k out=()
  for m in ${ST[mimics]//,/ }; do
    if [[ "$m" == ssh ]]; then p="${ST[ssh_port]:-22}"
    else k="$(_hed_port_key "$m")"; p="${ST[$k]:-$(_hed_mimic_default_port "$m")}"; fi
    out+=("$m:$p")
  done
  printf '%s' "${out[*]}"
}

# foreign token: the stored one while it still matches the config, else rebuilt
_hed_foreign_token() {
  local built stored="${ST[token]:-}" bip beps bauth ip
  ip="${ST[public_ip]:-${ST[my_ip]:-}}"            # my_ip = states from before native pairing
  [[ -z "$ip" ]] && ip="$(sys_public_ip4)"
  [[ -z "${ST[public_ip]:-}" && -n "$ip" ]] && ST[public_ip]="$ip"
  built="$(_hed_token_build "$ip" 2>/dev/null)"
  if [[ -n "$built" ]]; then
    if [[ -n "$stored" ]] && _hed_token_decode "$built"; then
      bip="$HT_IP" beps="$HT_EPS" bauth="$HT_AUTH"
      if _hed_token_decode "$stored" && [[ "$HT_IP" == "$bip" && "$HT_EPS" == "$beps" && "$HT_AUTH" == "$bauth" ]]; then
        printf '%s' "$stored"; return 0
      fi
    fi
    if [[ "$built" != "$stored" ]]; then ST[token]="$built"; st_save; fi
    printf '%s' "$built"; return 0
  fi
  # no config readable: only hand out a stored token that is a real v2 token
  if [[ -n "$stored" ]] && _hed_token_decode "$stored"; then printf '%s' "$stored"; return 0; fi
  return 1
}

# ============================================================================
# meta
# ============================================================================
t_hedioum_meta() {
  echo "id=hedioum"
  echo "title=Hedioum  (mimic SOCKS pool)"
  echo "tier=free"
  echo "layer=socks"
  echo "roles=foreign iran"
  echo "primary=foreign"
  echo "twoway=no"
  echo "cores=hedioum"
  echo "pairing=native"                 # hedioum's own token is the only pairing artifact
  echo "handoff_label=Show Hedioum token"
  echo "first_hint=Set up the FOREIGN server first: it prints the Hedioum token you paste on Iran."
}

t_hedioum_unit() { echo "$HED_UNIT"; }

# a pasted string that hedioum's hub accepts -> the role that consumes it
t_hedioum_accepts_token() {  # <str>
  local rc; _hed_token_decode "$1"; rc=$?
  (( rc == 0 || rc == 2 )) && { echo iran; return 0; }
  return 1
}

# ============================================================================
# wizard (mirrors hedioum's own setup wizard, question for question)
# ============================================================================
t_hedioum_wizard() {  # <role> [level]
  if [[ "$1" == foreign ]]; then _hed_wizard_foreign; else _hed_wizard_iran; fi
}

_hed_ask_port() {  # <prompt> <default>
  local v
  while :; do
    v="$(ui_ask "$1" "$2")"
    [[ "$v" =~ ^[0-9]+$ ]] && (( v >= 1 && v <= 65535 )) && { printf '%s' "$v"; return 0; }
    ui_err "port must be 1-65535" >&2
  done
}
_hed_ask_int() {  # <prompt> <default> <min>
  local v
  while :; do
    v="$(ui_ask "$1" "$2")"
    [[ "$v" =~ ^[0-9]+$ ]] && (( v >= $3 )) && { printf '%s' "$v"; return 0; }
    ui_err "enter a whole number >= $3" >&2
  done
}

_hed_wizard_foreign() {
  local crole other
  crole="$(_hed_cfg_role)"
  if [[ "$crole" == iran ]]; then
    ui_err "this server is already a hedioum IRAN hub — one server can't be both roles."; return 1
  fi
  other="$(_hed_tunnels foreign "${ST[name]}" | head -n1)"
  if [[ -n "$other" ]]; then
    ui_err "hedioum foreign already runs here as tunnel '$other' (one per server). Edit that one."; return 1
  fi

  # hedioum already configured outside mili -> adopt it or reconfigure it
  if [[ -z "${ST[auth]:-}" && "$crole" == foreign ]]; then
    ui_info "hedioum is already set up as FOREIGN on this server."
    ui_select 0 $'Use existing setup\tkeep its token — Iran hubs stay paired' \
                $'Reconfigure\tanswer the setup questions (same auth key)'
    case "$SEL" in
      1) ST[adopt]=yes
         ST[auth]="$(_hed_cfg_get auth_token)"
         ST[persona]="$(_hed_cfg_get persona)"
         ST[mimics]="$(_hed_cfg_mimics | awk '{printf "%s%s", (NR>1?",":""), $1}')"
         ST[ssh_port]="$(_hed_cfg_mimics | awk '$1=="ssh"{print $2}')"
         ST[decoy_port]="$(_hed_cfg_get decoy_port)"
         ST[domain]="$(_hed_cfg_get domain)"
         ST[egress_mode]="$(_hed_cfg_get egress_ip_mode)"
         ST[decoy_style]="$(_hed_cfg_get decoy_style)"
         # OpenSSH sitting on the decoy port while the SSH mimic has 22 => it was moved
         if [[ "${ST[ssh_port]:-}" == 22 && "$(_hed_sshd_port)" == "${ST[decoy_port]:-x}" ]]; then
           ST[ssh_moved]=yes; ST[sshd_orig_port]=22
         fi
         _hed_ask_ip
         return 0 ;;
      2) ST[auth]="$(_hed_cfg_get auth_token)" ;;
      *) return 1 ;;
    esac
  fi
  unset 'ST[adopt]'

  # 1) public IP (embedded in the token)
  _hed_ask_ip

  # 2) persona — seeded from the auth key, so mili can show the exact set now
  ST[auth]="${ST[auth]:-$(sys_rand_hex 16)}"
  local pre=0 c set name
  case "${ST[persona_choice]:-auto}" in auto) pre=0 ;; cpanel) pre=1 ;; directadmin) pre=2 ;; devops) pre=3 ;; custom) pre=4 ;; esac
  echo; ui_info "Server persona (shapes the whole on-wire footprint):"
  ui_select "$pre" $'auto\trecommended — coherent persona from the token' \
                   $'cpanel\tcPanel hosting box' $'directadmin\tDirectAdmin hosting box' \
                   $'devops\tdocker / grafana / prometheus box' $'custom\tchoose mimics yourself'
  case "$SEL" in 1) c=auto ;; 2) c=cpanel ;; 3) c=directadmin ;; 4) c=devops ;; 5) c=custom ;; *) return 1 ;; esac
  ST[persona_choice]="$c"
  if [[ "$c" == custom ]]; then
    ui_note "mimics: ${HED_MIMICS[*]}  (or 'all')"
    local r
    while :; do
      set="$(ui_ask 'Mimics (comma list or all)' "${ST[mimics]:-ssh,tls}")"
      if r="$(_hed_expand_mimics "$set")"; then set="$r"; break; fi
      ui_err "$r"
    done
    if [[ ",$set," =~ ,(cpanel|whm|webmail), && ",$set," == *,directadmin,* ]]; then
      ui_warn "incoherent mimic set: cPanel family and DirectAdmin on one host (proceeding anyway)."
    fi
    ST[persona]=''; ST[mimics]="$set"
    ui_ok "Custom mimics: ${set//,/, }"
  else
    name="$c"; [[ "$c" == auto ]] && name="$(_hed_persona_auto "${ST[auth]}")"
    set="$(_hed_persona_resolve "$name" "${ST[auth]}")" || { ui_err "persona $name failed to resolve"; return 1; }
    ST[persona]="$name"; ST[mimics]="$set"
    ui_ok "Persona \"$name\": ${set//,/, }"
  fi

  # 3) SSH mimic (only when ssh is in the set)
  local taken=() lp sshd dp who
  if [[ ",${ST[mimics]}," == *,ssh,* ]]; then
    sshd="$(_hed_sshd_port)"
    while :; do
      lp="$(_hed_ask_port 'SSH mimic public port' "${ST[ssh_port]:-22}")"
      if [[ "$lp" == "$sshd" ]]; then
        if ui_confirm "Move OpenSSH off port $lp to free it for the SSH mimic?" y; then
          while :; do
            dp="$(_hed_ask_port 'Decoy sshd port (OpenSSH is moved here)' "${ST[decoy_port]:-2022}")"
            if [[ "$dp" == "$lp" ]]; then ui_err "decoy port must differ from $lp"; continue; fi
            if who="$(_hed_port_busy "$dp" "${ST[name]}")"; then ui_err "port $dp is busy ($who)"; continue; fi
            break
          done
          ST[move_ssh]=yes; ST[ssh_moved]=yes; ST[sshd_orig_port]="$lp"; ST[decoy_port]="$dp"
          ui_note "OpenSSH moves to $dp; the mimic on $lp forwards real SSH logins there."
          break
        fi
        ui_err "port $lp is OpenSSH's — pick another SSH mimic port (or move OpenSSH)."
        continue
      fi
      if who="$(_hed_port_busy "$lp" "${ST[name]}")"; then
        ui_err "port $lp is busy ($who)."; continue
      fi
      # OpenSSH stays put: the mimic's decoy backend IS the real sshd, so probes see real OpenSSH
      ST[move_ssh]=no; ST[decoy_port]="$sshd"
      [[ "$lp" != 22 ]] && ui_warn "SSH mimic on port $lp: it is most convincing on 22."
      break
    done
    ST[ssh_port]="$lp"; taken+=("$lp" "${ST[decoy_port]}")
  else
    ST[move_ssh]=no
  fi

  # 4) every other mimic port must be free (x-ui/xray/nginx often hold 443 etc.)
  local m k p def alt
  for m in ${ST[mimics]//,/ }; do
    [[ "$m" == ssh ]] && continue
    k="$(_hed_port_key "$m")"; def="$(_hed_mimic_default_port "$m")"; p="${ST[$k]:-$def}"
    while :; do
      who=''
      if [[ " ${taken[*]} " == *" $p "* ]]; then who="used by another mimic"
      else who="$(_hed_port_busy "$p" "${ST[name]}")" || who=''; fi
      [[ -z "$who" ]] && break
      alt="$(_hed_free_port "${taken[@]}")"
      ui_warn "$m mimic port $p is busy ($who)."
      p="$(_hed_ask_port "Port for the $m mimic" "$alt")"
    done
    taken+=("$p")
    if [[ "$p" == "$def" ]]; then unset "ST[$k]"; else ST[$k]="$p"; fi
  done

  # 5) IPv6 egress (opt-in, only when this server has IPv6)
  local v6
  ST[egress_mode]="${ST[egress_mode]:-ipv4}"
  if v6="$(sys_public_ip6 2>/dev/null)"; then
    if ui_confirm "Detected IPv6 ($v6). Allow outbound traffic over IPv6 too?" "$([[ "${ST[egress_mode]}" != ipv4 ]] && echo y || echo n)"; then
      ui_select "$([[ "${ST[egress_mode]}" == ipv6 ]] && echo 1 || echo 0)" \
        $'Dual\tprefer IPv4, fall back to IPv6' $'IPv6 only'
      [[ "$SEL" == 2 ]] && ST[egress_mode]=ipv6 || ST[egress_mode]=dual
    else
      ST[egress_mode]=ipv4
    fi
  fi

  # 6) TLS certificate
  echo; ui_info "TLS certificate"
  ui_note "A domain pointed at THIS server gets a real Let's Encrypt cert (much harder"
  ui_note "to fingerprint). Without one everything works with a self-signed cert."
  local d
  while :; do
    d="$(ui_ask "Domain for a real certificate (blank = self-signed${ST[domain]:+, - to clear})" "${ST[domain]:-}")"
    [[ "$d" == - ]] && d=''
    [[ -z "$d" ]] || sys_is_host "$d" || { ui_err "not a valid domain"; continue; }
    break
  done
  ST[domain]="$d"
  if [[ -n "$d" ]]; then
    ST[acme_email]="$(ui_ask "Let's Encrypt account email (optional)" "${ST[acme_email]:-}")"
    if ! getent ahostsv4 "$d" 2>/dev/null | awk '{print $1}' | grep -qx "${ST[public_ip]}"; then
      ui_warn "$d does not resolve to ${ST[public_ip]} yet — the cert is issued once DNS points here."
    fi
  else
    unset 'ST[acme_email]'
    ui_warn "Using a self-signed certificate. A domain is recommended when possible."
  fi

  # 7) web-decoy style
  echo; ui_info "Web-decoy style for unauthorized probes:"
  ui_select "$([[ "${ST[decoy_style]:-apache}" == directadmin ]] && echo 1 || echo 0)" \
    $'apache\tApache default page' $'directadmin\tDirectAdmin hosting box'
  [[ "$SEL" == 2 ]] && ST[decoy_style]=directadmin || ST[decoy_style]=apache
  return 0
}

_hed_ask_ip() {
  local ip
  while :; do
    ip="$(ui_ask 'Confirm server public IPv4' "${ST[public_ip]:-$(sys_public_ip4)}")"
    sys_is_ip4 "$ip" && break
    ui_err "enter this server's public IPv4"
  done
  ST[public_ip]="$ip"
}

_hed_wizard_iran() {
  if [[ "$(_hed_cfg_role)" == foreign ]]; then
    ui_err "this server is a hedioum FOREIGN node — one server can't be both roles."; return 1
  fi
  local tok="${MILI_PREFILL_TOKEN:-}" rc
  MILI_PREFILL_TOKEN=''
  if [[ -z "$tok" && -n "${ST[token]:-}" ]]; then
    ui_confirm "Keep the current pairing token?" y && tok="${ST[token]}"
  fi

  # 1) pairing token (hedioum v2; a legacy bare auth key also works)
  while :; do
    if [[ -z "$tok" ]]; then
      ui_info "Paste the Hedioum pairing token printed on the FOREIGN server."
      tok="$(ui_ask 'Pairing token' '')"
      [[ -z "$tok" ]] && return 1
    fi
    _hed_token_decode "$tok"; rc=$?
    case "$rc" in
      0) ui_ok "Pairing token: ${HT_PERSONA:-custom} persona, $(_hed_eps_count "$HT_EPS") endpoints @ $HT_IP"; break ;;
      2) ui_warn "legacy token (bare auth key): the foreign IP and persona must be given."; break ;;
      *) ui_err "$HT_ERR"; tok='' ;;
    esac
  done
  ST[token]="$(printf '%s' "$tok" | tr -d '[:space:]')"
  if (( rc == 0 )); then
    unset 'ST[legacy]'
    ST[exit_ip]="$HT_IP"; ST[persona]="$HT_PERSONA"; ST[eps]="$HT_EPS"
  else
    ST[legacy]=yes
    local ip pname eps='' m
    while :; do
      ip="$(ui_ask 'Foreign egress IP (IPv4 or IPv6) or hostname' "${ST[exit_ip]:-}")"
      [[ -n "$ip" && "$ip" != *[[:space:]/\\]* ]] && break
      ui_err "not a valid IP or hostname"
    done
    ST[exit_ip]="$ip"
    ui_info "Match the foreign's persona:"
    ui_select 0 $'auto\tfrom the token (foreign used auto)' $'cpanel' $'directadmin' $'devops'
    case "$SEL" in 1) pname="$(_hed_persona_auto "$HT_AUTH")" ;; 2) pname=cpanel ;; 3) pname=directadmin ;; 4) pname=devops ;; *) return 1 ;; esac
    for m in $(_hed_persona_resolve "$pname" "$HT_AUTH" | tr ',' ' '); do
      eps+="${eps:+ }$m:$(_hed_mimic_default_port "$m")"
    done
    ST[persona]="$pname"; ST[eps]="$eps"
    ui_ok "Persona \"$pname\" → $(_hed_eps_count "$eps") endpoints toward $ip"
  fi

  # 2) node alias = tunnel name (must be unique on this hub)
  local editing=0 a
  [[ -n "${ST[socks_port]:-}" ]] && editing=1     # Edit of an existing node
  ST[alias]="${ST[alias]:-${ST[name]}}"
  while (( !editing )) && _hed_cfg_has_node "${ST[alias]}"; do
    ui_warn "this hub already has a node named '${ST[alias]}'."
    a="$(ui_ask 'Node alias' "${ST[name]}$(sys_rand_hex 1)")"
    [[ -n "$a" ]] && ST[alias]="$a"
  done

  # 3) local SOCKS5 port (the 3x-ui outbound target)
  local p who
  while :; do
    p="$(_hed_ask_port 'Local SOCKS5 port (for the 3x-ui outbound)' "${ST[socks_port]:-$(ports_alloc_socks "${ST[name]}")}")"
    if [[ "$p" != "${ST[socks_port]:-}" ]] && who="$(_hed_port_listener "$p")"; then ui_err "port $p is busy ($who)"; continue; fi
    if who="$(_hed_port_busy "$p" "${ST[name]}")"; then ui_err "port $p is busy ($who)"; continue; fi
    break
  done
  ST[socks_port]="$p"

  # 4) connection pool (hedioum defaults)
  ST[min]="$(_hed_ask_int 'Min physical connections (warm-up pool)' "${ST[min]:-10}" 1)"
  ST[max]="$(_hed_ask_int 'Max physical connections (scale limit)' "${ST[max]:-20}" "${ST[min]}")"
  ST[bw]="$(_hed_ask_int 'Bandwidth limit per connection (Mbps)' "${ST[bw]:-8}" 1)"
  ST[jitter]="$(_hed_ask_int 'Bandwidth jitter for DPI evasion (Mbps)' "${ST[jitter]:-2}" 0)"

  # 5) optional TUN interface
  if ui_confirm "Also expose this node as a TUN network interface? (advanced; SOCKS stays on)" "$([[ "${ST[tun]:-}" == yes ]] && echo y || echo n)"; then
    ST[tun]=yes
    ST[tun_name]="$(ui_ask 'TUN interface name (blank = auto)' "${ST[tun_name]:-}")"
    ST[tun_addr]="$(ui_ask 'TUN gateway CIDR (blank = auto)' "${ST[tun_addr]:-}")"
    ui_confirm "Run a DNS forwarder on the TUN gateway (:53, resolves through the tunnel)?" "$([[ "${ST[dns]:-}" == yes ]] && echo y || echo n)" && ST[dns]=yes || ST[dns]=no
    ui_confirm "Transparent gateway mode? (forward LAN transit into the tunnel — MikroTik/router)" "$([[ "${ST[gateway]:-}" == yes ]] && echo y || echo n)" && ST[gateway]=yes || ST[gateway]=no
  else
    ST[tun]=no; ST[dns]=no; ST[gateway]=no; unset 'ST[tun_name]' 'ST[tun_addr]'
  fi
  return 0
}

t_hedioum_summary() {
  if [[ "${ST[role]}" == foreign ]]; then
    ui_kv "Role" "Foreign (egress)"
    ui_kv "Public IPv4" "${ST[public_ip]}"
    if [[ "${ST[adopt]:-}" == yes ]]; then
      ui_kv "Setup" "use the existing hedioum config (no changes)"
      return 0
    fi
    ui_kv "Persona" "${ST[persona]:-custom}$([[ "${ST[persona_choice]:-}" == auto ]] && echo ' (auto)')"
    ui_kv "Mimics" "$(_hed_eps_pretty "$(_hed_plan_eps)")"
    if [[ ",${ST[mimics]}," == *,ssh,* ]]; then
      if [[ "${ST[move_ssh]:-}" == yes ]]; then ui_kv "SSH" "mimic :${ST[ssh_port]} · OpenSSH moves to :${ST[decoy_port]}"
      else ui_kv "SSH" "mimic :${ST[ssh_port]} · probes see OpenSSH :${ST[decoy_port]}"; fi
    fi
    ui_kv "Egress" "${ST[egress_mode]:-ipv4}"
    ui_kv "Certificate" "$([[ -n "${ST[domain]:-}" ]] && echo "Let's Encrypt · ${ST[domain]}" || echo self-signed)"
    ui_kv "Web decoy" "${ST[decoy_style]:-apache} · HTTP :80 off (kept free)"
  else
    ui_kv "Role" "Iran (hub)"
    ui_kv "Foreign" "${ST[exit_ip]} · ${ST[persona]:-custom} · $(_hed_eps_count "${ST[eps]}") endpoints"
    ui_kv "Node alias" "$(_hed_alias)"
    ui_kv "SOCKS5" "127.0.0.1:${ST[socks_port]}"
    ui_kv "Pool" "min ${ST[min]} · max ${ST[max]} · ${ST[bw]}±${ST[jitter]} Mbps"
    [[ "${ST[tun]:-}" == yes ]] && ui_kv "TUN" "${ST[tun_name]:-auto} ${ST[tun_addr]:-auto}$([[ "${ST[dns]}" == yes ]] && echo ' +dns')$([[ "${ST[gateway]}" == yes ]] && echo ' +gateway')"
  fi
  return 0
}

# ============================================================================
# provision (create / Edit only) — runs hedioum's own setup commands
# ============================================================================
t_hedioum_provision() {  # <name>   (ST already holds the wizard answers)
  require_root
  # adopting an existing foreign: leave the operator's installed hedioum binary alone
  if [[ "${ST[adopt]:-}" != yes || ! -x /usr/local/bin/hedioum-tunnel ]]; then
    _hed_install || return 1
  fi
  if [[ "${ST[role]}" == foreign ]]; then _hed_provision_foreign "$1"; else _hed_provision_iran "$1"; fi
}

_hed_provision_foreign() {
  local name="$1" b log old="${ST[token]:-}" rc=0 m k e tok out_tok
  b="$(_hed_bin)"; log="$MILI_LOGDIR/hedioum-$name.setup.log"
  mkdir -p "$MILI_LOGDIR" 2>/dev/null || true

  # claim the planned ports up front (state survives a dropped session)
  ports_release "$name"
  for e in $(_hed_plan_eps); do ports_claim "$name" tcp "${e#*:}" 0.0.0.0; done

  if [[ "${ST[adopt]:-}" != yes ]]; then
    local -a a=(setup-foreign --token "${ST[auth]}" --public-ip "${ST[public_ip]}"
                --egress-mode "${ST[egress_mode]:-ipv4}" --decoy-style "${ST[decoy_style]:-apache}"
                --http-decoy-port 0)
    if [[ "${ST[persona_choice]:-}" == custom ]]; then a+=(--mimics "${ST[mimics]}")
    else a+=(--persona "${ST[persona]}"); fi
    if [[ ",${ST[mimics]}," == *,ssh,* ]]; then
      a+=(--listen-port "${ST[ssh_port]}" --decoy-port "${ST[decoy_port]}")
      [[ "${ST[move_ssh]:-}" == yes ]] && a+=(--move-ssh)
    fi
    for m in ${ST[mimics]//,/ }; do
      [[ "$m" == ssh ]] && continue
      k="$(_hed_port_key "$m")"
      [[ -n "${ST[$k]:-}" ]] && a+=("$(_hed_mimic_port_flag "$m")" "${ST[$k]}")
    done
    [[ -n "${ST[domain]:-}" ]] && a+=(--domain "${ST[domain]}")
    [[ -n "${ST[acme_email]:-}" ]] && a+=(--acme-email "${ST[acme_email]}")

    st_save
    if _hed_via_mimic; then
      ui_warn "you are connected through the hedioum SSH mimic: hedioum restarts at the end of"
      ui_note "setup and this session will drop. Reconnect, then open the tunnel → '${ST[name]}' → Show Hedioum token."
    fi
    echo; ui_info "running: hedioum-tunnel ${a[*]/${ST[auth]}/••••}"
    run "$b" "${a[@]}" 2>&1 | tee "$log" | sed 's/^/    /'
    rc=${PIPESTATUS[0]}
    if (( rc != 0 )); then
      ui_err "hedioum setup-foreign failed (exit $rc). Full output: $log"
      [[ "$(_hed_cfg_role)" == foreign ]] || run systemctl disable --now "$HED_UNIT" >/dev/null 2>&1 || true
      return 1
    fi
    [[ "${ST[move_ssh]:-}" == yes ]] && ST[move_ssh]=no   # done once; keep ssh_moved for Delete
  fi
  unset 'ST[adopt]'
  [[ "${MILI_DRYRUN:-0}" == 1 ]] && { st_save; ui_note "dry-run: verification skipped"; return 0; }

  if [[ "$(_hed_cfg_role)" != foreign ]]; then
    ui_err "no foreign config in $HED_CFG after setup — stopping hedioum so it can't crash-loop."
    run systemctl disable --now "$HED_UNIT" >/dev/null 2>&1 || true
    return 1
  fi

  # the pairing token: built from the live config, cross-checked with hedioum's own print
  tok="$(_hed_token_build "${ST[public_ip]}")" || { ui_err "could not build the pairing token from $HED_CFG"; return 1; }
  if [[ -f "$log" ]] && out_tok="$(_hed_token_from_output "$log" "${ST[auth]}")" && [[ "$out_tok" != "$tok" ]]; then
    ui_warn "token differs from the one hedioum printed — using hedioum's."
    tok="$out_tok"
  fi
  ST[token]="$tok"
  st_save

  run systemctl enable "$HED_UNIT" >/dev/null 2>&1 || true
  svc_active "$HED_UNIT" || run systemctl start "$HED_UNIT" >/dev/null 2>&1 || true

  # reconcile port claims with what hedioum actually runs, then verify
  ports_release "$name"
  while read -r m k; do [[ -n "$k" ]] && ports_claim "$name" tcp "$k" 0.0.0.0; done < <(_hed_cfg_mimics)
  _hed_verify_foreign || return 1
  if [[ -n "$old" && "$old" != "$tok" ]]; then
    ui_warn "the pairing token CHANGED — paste the new one on every Iran server using this foreign."
  fi
  return 0
}

_hed_verify_foreign() {
  local m p i who bad=0
  _hed_wait_active 8 || { ui_err "hedioum.service is not running — see: journalctl -u $HED_UNIT -n 30"; return 1; }
  while read -r m p; do
    [[ -z "$p" ]] && continue
    for (( i = 0; i < 6; i++ )); do
      who="$(_hed_port_listener "$p")" && [[ "$who" == hedioum* || "$who" == '?' ]] && break
      who=''; sleep 1
    done
    if [[ -n "$who" ]]; then ui_ok "$m mimic listening on :$p"
    else ui_err "$m mimic NOT listening on :$p$(w="$(_hed_port_listener "$p")" && echo " (held by $w)")"; bad=1; fi
  done < <(_hed_cfg_mimics)
  if [[ "${ST[ssh_moved]:-}" == yes ]]; then
    if _hed_listening "${ST[decoy_port]:-2022}"; then ui_ok "OpenSSH on :${ST[decoy_port]:-2022}"
    else ui_warn "OpenSSH not seen on :${ST[decoy_port]:-2022} — check before closing this session!"; fi
  fi
  (( bad == 0 )) || ui_note "logs: journalctl -u $HED_UNIT -n 50"
  return "$bad"
}

_hed_add_node() {  # uses ST; upserts this node on the hub (add-node == setup-iran)
  local b rc log
  b="$(_hed_bin)" || { ui_err "hedioum binary missing"; return 1; }
  log="$MILI_LOGDIR/hedioum-${ST[name]}.setup.log"; mkdir -p "$MILI_LOGDIR" 2>/dev/null || true
  local -a a=(add-node --alias "$(_hed_alias)" --token "${ST[token]}" --socks-port "${ST[socks_port]}"
              --min "${ST[min]:-10}" --max "${ST[max]:-20}" --bw "${ST[bw]:-8}" --jitter "${ST[jitter]:-2}")
  [[ "${ST[legacy]:-}" == yes ]] && a+=(--target-ip "${ST[exit_ip]}" --persona "${ST[persona]}")
  if [[ "${ST[tun]:-}" == yes ]]; then
    a+=(--tun)
    [[ -n "${ST[tun_name]:-}" ]] && a+=(--tun-name "${ST[tun_name]}")
    [[ -n "${ST[tun_addr]:-}" ]] && a+=(--tun-addr "${ST[tun_addr]}")
    [[ "${ST[dns]:-}" == yes ]] && a+=(--dns)
    [[ "${ST[gateway]:-}" == yes ]] && a+=(--gateway)
  fi
  ui_info "running: hedioum-tunnel add-node --alias $(_hed_alias) --socks-port ${ST[socks_port]} --token ••••"
  run "$b" "${a[@]}" 2>&1 | tee -a "$log" | sed 's/^/    /'
  rc=${PIPESTATUS[0]}
  if (( rc != 0 )); then
    ui_err "hedioum add-node failed (exit $rc). Output: $log"
    [[ "${MILI_DRYRUN:-0}" != 1 ]] && (( $(_hed_cfg_node_count) == 0 )) && run systemctl disable --now "$HED_UNIT" >/dev/null 2>&1
    return 1
  fi
  return 0
}

_hed_provision_iran() {
  local name="$1" i b
  st_save
  _hed_add_node || return 1
  ports_release "$name"
  ports_claim "$name" tcp "${ST[socks_port]}" 127.0.0.1
  fw_loopback_guard "$name" tcp "${ST[socks_port]}"
  [[ "${MILI_DRYRUN:-0}" == 1 ]] && { ui_note "dry-run: verification skipped"; return 0; }
  run systemctl enable "$HED_UNIT" >/dev/null 2>&1 || true
  _hed_wait_active 8 || { ui_err "hedioum.service is not running — see: journalctl -u $HED_UNIT -n 30"; return 1; }
  for (( i = 0; i < 10; i++ )); do _hed_listening "${ST[socks_port]}" && break; sleep 1; done
  if ! _hed_listening "${ST[socks_port]}"; then
    ui_err "SOCKS 127.0.0.1:${ST[socks_port]} is not listening — see: journalctl -u $HED_UNIT -n 30"; return 1
  fi
  ui_ok "SOCKS5 listening on 127.0.0.1:${ST[socks_port]}"
  echo; ui_info "probing every endpoint of the foreign:"
  b="$(_hed_bin)"
  run "$b" probe --node "$(_hed_alias)" 2>&1 | sed 's/^/    /'
  if (( PIPESTATUS[0] != 0 )); then
    ui_warn "some endpoints are unreachable (blocked port or foreign down) — the pool uses the rest."
  fi
  return 0
}

# ============================================================================
# lifecycle (Start / Stop / Restart / Delete never re-run setup)
# ============================================================================
t_hedioum_up() {  # <name>
  st_load "$1"; local name="$1" i
  require_root
  if [[ "${ST[role]}" == foreign ]]; then
    [[ "$(_hed_cfg_role)" == foreign ]] || { ui_err "hedioum foreign config is missing — use Edit to set it up again."; return 1; }
    run systemctl enable --now "$HED_UNIT" >/dev/null 2>&1 || true
    [[ "${MILI_DRYRUN:-0}" == 1 ]] && return 0
    _hed_wait_active 8
    return
  fi
  [[ "$(_hed_cfg_role)" == foreign ]] && { ui_err "this server is a hedioum FOREIGN node"; return 1; }
  if ! _hed_cfg_has_node "$(_hed_alias)"; then
    _hed_bin >/dev/null || _hed_install || return 1
    _hed_add_node || return 1
  fi
  run systemctl enable --now "$HED_UNIT" >/dev/null 2>&1 || true
  ports_claim "$name" tcp "${ST[socks_port]}" 127.0.0.1
  fw_loopback_guard "$name" tcp "${ST[socks_port]}"
  [[ "${MILI_DRYRUN:-0}" == 1 ]] && return 0
  _hed_wait_active 8 || return 1
  for (( i = 0; i < 10; i++ )); do _hed_listening "${ST[socks_port]}" && return 0; sleep 1; done
  ui_err "SOCKS 127.0.0.1:${ST[socks_port]} not listening"; return 1
}

t_hedioum_down() {  # <name>
  st_load "$1"
  if [[ "${ST[role]}" == foreign ]]; then
    [[ "${ST[ssh_moved]:-}" == yes ]] && ui_warn "while hedioum is stopped, SSH only answers on OpenSSH's port ${ST[decoy_port]:-2022}."
    st_set state down; st_save            # saved first: the session may drop below
    _hed_svc disable --now "$HED_UNIT"
    return 0
  fi
  # iran: drop only THIS node; the shared service keeps serving the others
  local b; b="$(_hed_bin 2>/dev/null)"
  if [[ -n "$b" ]] && _hed_cfg_has_node "$(_hed_alias)"; then
    run "$b" remove-node --alias "$(_hed_alias)" >/dev/null 2>&1 || true
  fi
  (( $(_hed_cfg_node_count) == 0 )) && run systemctl disable --now "$HED_UNIT" >/dev/null 2>&1
  fw_remove "$1"
  return 0
}

t_hedioum_restart() {  # <name> : one systemd job (safe even through the SSH mimic)
  st_load "$1"
  if [[ "${ST[role]}" == iran ]] && ! _hed_cfg_has_node "$(_hed_alias)"; then
    t_hedioum_up "$1"; return
  fi
  _hed_svc restart "$HED_UNIT"
  [[ "${MILI_DRYRUN:-0}" == 1 ]] || _hed_via_mimic || _hed_wait_active 8
}

# full teardown for Delete (replaces down+purge)
t_hedioum_remove() {  # <name>
  st_load "$1"
  if [[ "${ST[role]}" != foreign ]]; then t_hedioum_down "$1"; return 0; fi
  local bk="$MILI_ETC/backups"
  mkdir -p "$bk" 2>/dev/null && cp -f "$HED_CFG" "$bk/hedioum-$1-$(date +%s).json" 2>/dev/null \
    && ui_note "hedioum config backed up to $bk/"
  if [[ "${ST[ssh_moved]:-}" == yes && -n "${ST[sshd_orig_port]:-}" ]]; then
    local orig="${ST[sshd_orig_port]}"
    ui_warn "restoring OpenSSH to port $orig (runs detached in ~5s; your SSH session may drop)."
    ui_note "reconnect on :$orig after ~10s. Fallback: ssh -p ${ST[decoy_port]:-2022} ..."
    _hed_detached 5 "systemctl disable --now $HED_UNIT; rm -f $HED_CFG; \
sed -i -E 's/^#?Port[[:space:]]+[0-9]+/Port $orig/' /etc/ssh/sshd_config; \
systemctl restart ssh || systemctl restart sshd"
  else
    _hed_svc disable --now "$HED_UNIT"
    run rm -f "$HED_CFG"
  fi
  return 0
}

t_hedioum_fw_apply() {
  st_load "$1"
  [[ "${ST[role]}" == iran && -n "${ST[socks_port]:-}" ]] && fw_loopback_guard "$1" tcp "${ST[socks_port]}"
}

t_hedioum_health() {  # <name>
  st_load "$1"
  svc_active "$HED_UNIT" || return 1
  if [[ "${ST[role]}" == iran ]]; then
    _hed_listening "${ST[socks_port]:-0}"
  else
    local m p
    while read -r m p; do [[ -n "$p" ]] && { _hed_listening "$p" || return 1; }; done < <(_hed_cfg_mimics 2>/dev/null)
    return 0
  fi
}

t_hedioum_ports() {
  st_load "$1"
  if [[ "${ST[role]}" == iran ]]; then
    [[ -n "${ST[socks_port]:-}" ]] && echo "tcp:${ST[socks_port]}:127.0.0.1"
  else
    local m p; while read -r m p; do [[ -n "$p" ]] && echo "tcp:$p:0.0.0.0"; done < <(_hed_cfg_mimics 2>/dev/null)
  fi
}

t_hedioum_info() {
  st_load "$1"
  if [[ "${ST[role]}" == foreign ]]; then
    ui_kv "role" "foreign (egress) · native hedioum.service"
    ui_kv "public IPv4" "${ST[public_ip]:-?}"
    # hedioum's config is the source of truth; ST is the fallback before setup ran
    local eps persona domain egress
    eps="$(_hed_cfg_mimics 2>/dev/null | awk '{printf "%s%s:%s", (NR>1?", ":""), $1, $2}')"
    persona="$(_hed_cfg_get persona 2>/dev/null)"; persona="${persona:-${ST[persona]:-}}"
    domain="$(_hed_cfg_get domain 2>/dev/null)";   domain="${domain:-${ST[domain]:-}}"
    egress="$(_hed_cfg_get egress_ip_mode 2>/dev/null)"; egress="${egress:-${ST[egress_mode]:-ipv4}}"
    ui_kv "persona" "${persona:-custom}"
    ui_kv "mimics" "${eps:-$(_hed_eps_pretty "$(_hed_plan_eps)")}"
    if [[ "${ST[ssh_moved]:-}" == yes ]]; then ui_kv "OpenSSH" "moved to :${ST[decoy_port]} (restored on Delete)"; fi
    ui_kv "certificate" "$([[ -n "$domain" ]] && echo "Let's Encrypt · $domain" || echo self-signed)"
    ui_kv "egress" "$egress"
    ui_kv "pairing" "$([[ -n "$(_hed_foreign_token 2>/dev/null)" ]] && echo "token ready → 'Show Hedioum token'" || echo 'no token (Edit to set up)')"
  else
    ui_kv "role" "iran (hub) · node '$(_hed_alias)'"
    ui_kv "foreign" "${ST[exit_ip]:-?} · ${ST[persona]:-custom} · $(_hed_eps_count "${ST[eps]:-}") endpoints"
    ui_kv "pool" "min ${ST[min]:-10} · max ${ST[max]:-20} · ${ST[bw]:-8}±${ST[jitter]:-2} Mbps"
    [[ "${ST[tun]:-}" == yes ]] && ui_kv "TUN" "${ST[tun_name]:-auto} ${ST[tun_addr]:-auto}"
    echo; xui_outbound_box "127.0.0.1" "${ST[socks_port]:-?}" "" ""
  fi
}

t_hedioum_xui() {
  st_load "$1"
  if [[ "${ST[role]}" == iran ]]; then
    xui_help_socks "$1" "127.0.0.1" "${ST[socks_port]}" "" ""
  else
    ui_warn "the Hedioum SOCKS endpoint lives on the IRAN hub (127.0.0.1:<socks-port>)."
  fi
}

t_hedioum_test() {
  st_load "$1"
  local b; b="$(_hed_bin 2>/dev/null)"
  if svc_active "$HED_UNIT"; then ui_ok "hedioum.service active"; else ui_err "hedioum.service not active"; fi
  if [[ "${ST[role]}" == iran ]]; then
    [[ -n "$b" ]] && { run "$b" probe --node "$(_hed_alias)" 2>&1 | sed 's/^/    /' || true; }
    doctor_socks 127.0.0.1 "${ST[socks_port]}" || true
  else
    local m p
    while read -r m p; do
      [[ -z "$p" ]] && continue
      if _hed_listening "$p"; then ui_ok "$m :$p listening"; else ui_err "$m :$p NOT listening"; fi
    done < <(_hed_cfg_mimics 2>/dev/null)
    [[ -n "$b" ]] && { run "$b" check-ip 2>&1 | sed 's/^/    /' || true; }
  fi
}

# what to carry to the other server
t_hedioum_handoff() {  # <name>
  st_load "$1"
  if [[ "${ST[role]}" == foreign ]]; then
    local tok
    tok="$(_hed_foreign_token)" || { ui_err "no pairing token yet — the foreign setup did not finish (Edit to retry)."; return 1; }
    pair_present "$tok" "Hedioum pairing token — tunnel '$1'"
    if _hed_token_decode "$tok"; then
      ui_kv "carries" "exit $HT_IP · ${HT_PERSONA:-custom} persona · $(_hed_eps_count "$HT_EPS") endpoints"
    fi
    echo; ui_info "Next, on the IRAN server:"
    ui_note "mili → New tunnel → Hedioum → Iran → paste this token."
    ui_note "(plain hedioum works too: hedioum-tunnel setup-iran --alias NAME --token <token> --socks-port N)"
  else
    ui_head "Hedioum node '$(_hed_alias)' — Iran hub"
    ui_kv "foreign" "${ST[exit_ip]:-?} · ${ST[persona]:-custom} · $(_hed_eps_count "${ST[eps]:-}") endpoints"
    echo; xui_outbound_box "127.0.0.1" "${ST[socks_port]:-?}" "" ""
    ui_note "token in use (copy it to add this foreign to another hub):"
    printf '    %s%s%s\n' "${C_YEL:-}" "${ST[token]}" "${C_RST:-}"
  fi
}

# ===== tunnels/paqet.sh =====
# shellcheck shell=bash
# mili :: tunnels/paqet.sh - hanselime/paqet raw-packet tunnel.
# server = FOREIGN (listens), client = IRAN (dials, exposes local SOCKS5).
# Uses raw pcap packets with TCP-flag cycling + KCP. mili adds the required
# raw NOTRACK + mangle RST-drop in ITS OWN chains (never iptables-persistent).
#
# NOTE: paqet is alpha; the generated config keys follow the documented layout
# and are confirmed against the installed binary at first run (verify-at-impl).
#
# roles: iran (client) | foreign (server)
# config: /etc/mili/engines/paqet/<name>.conf

t_register paqet
feature "tunnel.paqet" free

MILI_PQ_ETC="$MILI_ETC/engines/paqet"

t_paqet_meta() {
  echo "id=paqet"
  echo "title=paqet  (raw packet, anti-DPI)"
  echo "tier=free"
  echo "layer=socks"
  echo "roles=iran foreign"
  echo "primary=foreign"   # foreign = server (listener) generates; iran dials in
  echo "twoway=no"
  echo "cores=paqet"
}

_paqet_guard_port() {  # refuse kernel/x-ui/reserved ports for the raw listener
  local port="$1"
  local r
  for r in 80 443 22 53; do [[ "$port" == "$r" ]] && return 1; done
  ports_xui | grep -qx "$port" && return 1
  return 0
}

t_paqet_wizard() {  # <role> <level>
  local role="$1" level="$2"
  # generator = foreign (server/listener); iran side is created by import
  ST[my_ip]="$(sys_public_ip4)"
  [[ "$level" == advanced ]] && ST[my_ip]="$(ui_ask 'This foreign server public IP (auto-detected)' "${ST[my_ip]}")"
  ui_ok "this foreign server's public IP: ${ST[my_ip]}  (iran will dial it)"
  ST[listen_port]="$(ui_ask 'paqet listen port (foreign, raw)' "${ST[listen_port]:-$(sys_rand_port 20000 29999)}")"
  _paqet_guard_port "${ST[listen_port]}" || { ui_err "that port is reserved / used by x-ui; pick another"; return 1; }
  [[ -z "${ST[secret]:-}" ]] && ST[secret]="$(sys_rand_hex 16)"

  # auto network facts (client side needs iface / local ip / router mac)
  ST[iface]="${ST[iface]:-$(sys_default_iface)}"
  ST[local_ip]="${ST[local_ip]:-$(sys_local_ip4)}"
  ST[router_mac]="${ST[router_mac]:-$(sys_gw_mac 2>/dev/null)}"

  if [[ "$level" == advanced ]]; then
    ST[local_flag]="$(ui_ask 'local TCP flag (e.g. PA/S/A)' "${ST[local_flag]:-PA}")"
    ST[remote_flag]="$(ui_ask 'remote TCP flag' "${ST[remote_flag]:-PA}")"
    echo; ui_info "KCP mode: normal fast fast2 fast3 manual"
    ST[kcp]="$(ui_ask 'kcp mode' "${ST[kcp]:-fast2}")"
    ST[conn]="$(ui_ask 'connection count' "${ST[conn]:-4}")"
    ST[mtu]="$(ui_ask 'mtu' "${ST[mtu]:-1350}")"
    ST[nocongestion]="$(ui_ask 'nocongestion true/false' "${ST[nocongestion]:-true}")"
  else
    ST[local_flag]="${ST[local_flag]:-PA}"; ST[remote_flag]="${ST[remote_flag]:-PA}"
    ST[kcp]="${ST[kcp]:-fast2}"; ST[conn]="${ST[conn]:-4}"; ST[mtu]="${ST[mtu]:-1350}"; ST[nocongestion]="${ST[nocongestion]:-true}"
  fi
  ST[mode]=socks
  return 0
}

t_paqet_render() {  # <name>
  st_load "$1"; local name="$1" f; f="$MILI_PQ_ETC/$name.conf"
  run mkdir -p "$MILI_PQ_ETC"
  [[ "${MILI_DRYRUN:-0}" == 1 ]] && { ui_info "[dry] paqet config for $name (role ${ST[role]})"; return 0; }
  if [[ "${ST[role]}" == foreign ]]; then
    cat >"$f" <<EOF
# mili paqet server (foreign) tunnel $name
mode = server
iface = ${ST[iface]}
local_ip = ${ST[local_ip]}
listen = ${ST[listen_port]}
secret = ${ST[secret]}
local_flag = ${ST[local_flag]}
remote_flag = ${ST[remote_flag]}
kcp_mode = ${ST[kcp]}
conn = ${ST[conn]}
mtu = ${ST[mtu]}
nocongestion = ${ST[nocongestion]}
EOF
  else
    cat >"$f" <<EOF
# mili paqet client (Iran) tunnel $name
mode = client
iface = ${ST[iface]}
local_ip = ${ST[local_ip]}
router_mac = ${ST[router_mac]}
remote = ${ST[foreign_ip]}:${ST[listen_port]}
secret = ${ST[secret]}
local_flag = ${ST[local_flag]}
remote_flag = ${ST[remote_flag]}
kcp_mode = ${ST[kcp]}
conn = ${ST[conn]}
mtu = ${ST[mtu]}
nocongestion = ${ST[nocongestion]}
socks = 127.0.0.1:${ST[socks_port]}
EOF
  fi
  chmod 600 "$f"
}

t_paqet_unit() { echo "mili-paqet@$1.service"; }

t_paqet_fw_apply() {  # <name>
  st_load "$1"; local name="$1"
  # raw NOTRACK + RST-drop on the paqet port (both sides) - mili chains only
  fw_raw_notrack "$name" tcp "${ST[listen_port]}"
  fw_drop_rst "$name" "${ST[listen_port]}"
  if [[ "${ST[role]}" == foreign ]]; then
    fw_allow "$name" tcp "${ST[listen_port]}"; fw_ufw_mirror "$name" tcp "${ST[listen_port]}"
  fi
}

t_paqet_up() {  # <name>
  st_load "$1"; local name="$1"
  require_root; cores_ensure paqet
  sys_apt_ensure libpcap0.8
  t_paqet_render "$name"
  t_paqet_fw_apply "$name"
  svc_up "mili-paqet@$name.service"
  if [[ "${ST[role]}" == foreign ]]; then
    ports_claim "$name" tcp "${ST[listen_port]}" "0.0.0.0"
  else
    ports_claim "$name" tcp "${ST[socks_port]}" "127.0.0.1"
  fi
}

t_paqet_down() {  # <name>
  svc_down "mili-paqet@$1.service" 2>/dev/null || true
  fw_remove "$1"
}

t_paqet_purge() { run rm -f "$MILI_PQ_ETC/$1.conf" 2>/dev/null || true; }

t_paqet_health() {  # <name>
  st_load "$1"
  if [[ "${ST[role]}" == iran ]]; then
    ss -Hlnt 2>/dev/null | awk '{print $4}' | grep -qE ":${ST[socks_port]}\$"
  else
    svc_active "mili-paqet@$1.service"
  fi
}

t_paqet_ports() {
  st_load "$1"
  [[ "${ST[role]}" == foreign ]] && echo "tcp:${ST[listen_port]}:0.0.0.0"
  [[ "${ST[role]}" == iran ]] && echo "tcp:${ST[socks_port]}:127.0.0.1"
}

t_paqet_info() {
  st_load "$1"
  ui_kv "role" "${ST[role]}"
  ui_kv "kcp" "${ST[kcp]} conn=${ST[conn]} mtu=${ST[mtu]}"
  ui_kv "flags" "local=${ST[local_flag]} remote=${ST[remote_flag]}"
  if [[ "${ST[role]}" == foreign ]]; then
    ui_kv "listen" "0.0.0.0:${ST[listen_port]} (raw)"
  else
    ui_kv "dials" "${ST[foreign_ip]}:${ST[listen_port]}"
    echo; xui_outbound_box "127.0.0.1" "${ST[socks_port]}" "" ""
  fi
}

t_paqet_xui() {
  st_load "$1"; local name="$1"
  if [[ "${ST[role]}" == iran ]]; then
    # paqet client socks5 has no auth by default
    xui_help_socks "$name" "127.0.0.1" "${ST[socks_port]}" "" ""
  else
    ui_warn "paqet SOCKS endpoint is on the IRAN (client) server at 127.0.0.1:${ST[socks_port]}."
  fi
}

t_paqet_test() {
  st_load "$1"
  if [[ "${ST[role]}" == iran ]]; then doctor_socks 127.0.0.1 "${ST[socks_port]}"; else t_paqet_health "$1" && ui_ok "paqet server up" || ui_err "down"; fi
}

t_paqet_pair_export() {
  st_load "$1"
  local peerrole; [[ "${ST[role]}" == foreign ]] && peerrole=iran || peerrole=foreign
  cat <<EOF
type=paqet
name=${ST[name]}
role=$peerrole
listen_port=${ST[listen_port]}
secret=${ST[secret]}
foreign_ip=${ST[my_ip]:-${ST[foreign_ip]:-}}
local_flag=${ST[local_flag]}
remote_flag=${ST[remote_flag]}
kcp=${ST[kcp]}
conn=${ST[conn]}
mtu=${ST[mtu]}
nocongestion=${ST[nocongestion]}
EOF
}

t_paqet_pair_import() {
  local p="$1" name role k
  name="$(pair_field "$p" name)"; role="$(pair_field "$p" role)"
  ST=(); ST[name]="$name"; ST[type]=paqet; ST[role]="$role"; ST[mode]=socks
  for k in listen_port secret foreign_ip local_flag remote_flag kcp conn mtu nocongestion; do
    ST[$k]="$(pair_field "$p" "$k")"
  done
  ST[iface]="$(sys_default_iface)"; ST[local_ip]="$(sys_local_ip4)"; ST[router_mac]="$(sys_gw_mac 2>/dev/null)"
  [[ "$role" == foreign ]] && ST[my_ip]="$(sys_public_ip4)"
  [[ "$role" == iran ]] && ST[socks_port]="$(ports_alloc_socks)"
  st_save
  t_paqet_up "$name"; st_set state up; st_save
}

# ===== main.sh =====
# mili - unified anti-DPI tunnel manager (Iran <-> Foreign), 3x-ui friendly.
# This is the entry point. In a built dist/mili.sh all lib/* and tunnels/* are
# concatenated ABOVE this marker by build.sh; when run from source it sources
# them relative to this file.
#
# 0.1.0 is replaced by build.sh.
MILI_VERSION="0.1.0"
[[ "$MILI_VERSION" == @*@ ]] && MILI_VERSION="0.0.0-dev"

set -o pipefail

# ---- source libs when running from source tree -----------------------------
if [[ -z "${MILI_BUNDLED:-}" ]]; then
  _self="${BASH_SOURCE[0]}"
  _dir="$(cd "$(dirname "$_self")" && pwd)"
  for _f in ui log sys state sysctl ports fw svc features fetch cores pair socks xui watchdog doctor optimize backup; do
    # shellcheck disable=SC1090
    . "$_dir/lib/$_f.sh"
  done
  for _f in "$_dir"/tunnels/*.sh; do [[ -e "$_f" ]] && . "$_f"; done
fi

ui_init
sys_detect_os
sys_detect_arch

# ============================================================================
# generic tunnel lifecycle
# ============================================================================

# bring a tunnel up: render configs, claim resources, firewall, start services.
mili_up() {   # <name>
  local name="$1" type
  st_load "$name" || { ui_err "unknown tunnel: $name"; return 1; }
  type="$(st_get type)"
  fw_init
  t_has "$type" render && t_call "$type" render "$name"
  if t_call "$type" up "$name"; then
    st_set state up; st_save; ui_ok "tunnel '$name' is up"
  else
    st_set state down; st_save; ui_warn "tunnel '$name' did not come up (see messages above)"
    return 1
  fi
}

mili_down() {  # <name>
  local name="$1" type
  st_load "$name" || { ui_err "unknown tunnel: $name"; return 1; }
  type="$(st_get type)"
  t_call "$type" down "$name"
  st_set state down; st_save
  ui_ok "tunnel '$name' stopped"
}

mili_restart() {  # <name> : module 'restart' hook if present, else down+up
  local name="$1" type
  st_load "$name" || { ui_err "unknown tunnel: $name"; return 1; }
  type="$(st_get type)"
  if t_has "$type" restart; then
    if t_call "$type" restart "$name"; then
      st_load "$name"; st_set state up; st_save; ui_ok "tunnel '$name' restarted"
    else
      st_load "$name"; st_set state down; st_save; ui_warn "tunnel '$name' did not come back up"; return 1
    fi
    return 0
  fi
  mili_down "$name" >/dev/null 2>&1; mili_up "$name"
}

mili_delete() {  # <name>
  local name="$1" type
  st_load "$name" || { ui_err "unknown tunnel: $name"; return 1; }
  type="$(st_get type)"
  ui_warn "deleting tunnel '$name' (type $type) - removes its services, firewall rules and config"
  ui_confirm "really delete '$name'?" n || return 1
  if t_has "$type" remove; then
    t_call "$type" remove "$name" || true       # module owns its full teardown
  else
    t_call "$type" down "$name" >/dev/null 2>&1 || true
    t_has "$type" purge && t_call "$type" purge "$name" >/dev/null 2>&1 || true
  fi
  fw_remove "$name"
  ports_release "$name"
  pool_meta_release "$name"
  socks_remove "$name"
  st_delete_file "$name"
  ui_ok "tunnel '$name' deleted"
}

# ============================================================================
# new tunnel wizard (generic driver; per-type wizard fills ST)
# ============================================================================
# short role descriptions (kept narrow so the selector never wraps)
_role_hint() {  # <type> <role>
  case "$2" in
    iran)    printf 'entry · next to 3x-ui' ;;
    foreign) printf 'exit · egress abroad' ;;
    *)       printf '%s' "$2" ;;
  esac
}

mili_new_tunnel() {
  ui_clear; ui_head "New tunnel"
  ui_note "You configure THIS server here, then carry ONE code/token to the other server."
  echo

  # ---- 1) tunnel type (arrow) ----
  local -a order=(gre grefrp backhaul paqet hedioum frp "${MILI_TYPES[@]}")
  local -a types=() labels=(); local t seen='' title tier badge star
  for t in "${order[@]}"; do
    [[ " $seen " == *" $t "* ]] && continue
    declare -F "t_${t}_meta" >/dev/null 2>&1 || continue
    types+=("$t"); seen="$seen $t"
    title="$(t_meta_field "$t" title)"; tier="$(t_meta_field "$t" tier)"
    star=''; case "$t" in gre|grefrp|backhaul|paqet|hedioum) star='★ ';; esac
    badge=''; [[ "$tier" == premium ]] && badge='premium'
    labels+=("$star$title"$'\t'"$badge")
  done
  labels+=("Cancel"$'\t')
  ui_select 0 "${labels[@]}"
  (( SEL==0 || SEL > ${#types[@]} )) && return 0
  local type="${types[$((SEL-1))]}"
  feature_gate "tunnel.$type" || { ui_pause; return 1; }
  local native=0; [[ "$(t_meta_field "$type" pairing)" == native ]] && native=1

  # ---- 2) which server is THIS one (arrow) ----
  local roles; roles="$(t_meta_field "$type" roles)"; roles="${roles:-iran foreign}"
  local -a rarr=($roles) rlabels=()
  local r pre=0 idx=0
  for r in "${rarr[@]}"; do
    rlabels+=("$(printf '%s' "${r^}")"$'\t'"$(_role_hint "$type" "$r")")
    [[ "$r" == "${MILI_DEFAULT_ROLE:-}" ]] && pre=$idx
    ((idx++))
  done
  echo
  (( native )) && [[ -n "$(t_meta_field "$type" first_hint)" ]] && ui_note "$(t_meta_field "$type" first_hint)"
  ui_info "Which server is this?"
  ui_select "$pre" "${rlabels[@]}"
  (( SEL==0 )) && return 0
  local role="${rarr[$((SEL-1))]}"

  # ---- mili-code tunnels: only the PRIMARY side generates the code ----
  if (( !native )); then
    local primary; primary="$(t_meta_field "$type" primary)"; primary="${primary:-foreign}"
    if [[ "$role" != "$primary" ]]; then
      ui_clear; ui_head "New $(t_meta_field "$type" title) — $(printf '%s' "${role^}") side"
      ui_info "This is the SECOND server. Set up the $primary server first;"
      ui_info "it prints a pairing code. Paste that code here to finish this side."
      echo
      mili_import_code
      return
    fi
  fi
  mili_create "$type" "$role"
}

# mili_create <type> <role> : name -> wizard -> summary -> apply -> handoff
# Native-pairing types (meta pairing=native) run their own wizard on BOTH sides
# and hand over the core's own token instead of a mili pairing code.
mili_create() {
  local type="$1" role="$2" native=0
  [[ "$(t_meta_field "$type" pairing)" == native ]] && native=1
  ui_clear; ui_head "New $(t_meta_field "$type" title) — $(printf '%s' "${role^}") side"

  # ---- 3) name ----
  local name
  while :; do
    name="$(ui_ask 'Tunnel name (a-z0-9, max 10)' "$type$(sys_rand_hex 1)")"
    st_valid_name "$name" || { ui_err "invalid name"; continue; }
    st_exists "$name" && { ui_err "name already exists"; continue; }
    break
  done

  # ---- 4) basic/advanced (mili-code types only; native types ask their core's own list) ----
  local level=full
  if (( !native )); then
    echo; ui_info "Option detail:"
    ui_select 0 $'Basic\trecommended defaults, fewest questions' $'Advanced\texpose transport / tuning knobs'
    level=basic; [[ "$SEL" == 2 ]] && level=advanced
  fi

  # ---- 5) role-specific wizard ----
  ST=(); ST[name]="$name"; ST[type]="$type"; ST[role]="$role"; ST[created]="$(date -Iseconds 2>/dev/null || date)"
  echo; ui_head "Configure $(t_meta_field "$type" title) — $(printf '%s' "${role^}") side"
  t_call "$type" wizard "$role" "$level" || { ui_err "wizard aborted"; ui_pause; return 1; }

  # ---- 6) summary ----
  echo; ui_head "Summary"
  mili_summary "$type"
  echo
  ui_confirm "Apply and start this tunnel now?" y || { ui_warn "not applied"; ui_pause; return 1; }

  st_save
  require_root
  fw_init
  svc_install_templates
  local ok=0
  if t_has "$type" provision; then
    t_call "$type" provision "$name" && ok=1
  else
    t_has "$type" render && t_call "$type" render "$name"
    t_call "$type" up "$name" && ok=1
  fi
  if (( ok )); then
    st_set state up; st_save; ui_ok "tunnel '$name' created and started"
  else
    st_set state down; st_save
    ui_warn "tunnel '$name' saved but NOT running — fix the issue above, then Manage → $name → Edit."
    ui_pause; return 1
  fi

  # ---- 7) hand over to the other server ----
  echo
  if (( native )) && t_has "$type" handoff; then
    t_call "$type" handoff "$name"
  elif t_has "$type" pair_export; then
    mili_export_code "$name"
    local tw; tw="$(t_meta_field "$type" twoway)"
    echo
    if [[ "$tw" == yes ]]; then
      ui_info "Next steps:"
      ui_note "1) On the OTHER server: mili → New tunnel → $(t_meta_field "$type" title) → the other side → paste this code."
      ui_note "2) That server prints a REPLY code. Bring it back here:"
      ui_note "   mili → 'Import pairing code' → paste the reply. Then this tunnel comes up."
    else
      ui_info "Next: on the OTHER server run mili → New tunnel → pick the other side → paste this code. Done."
    fi
  else
    ui_note "This tunnel type needs no pairing."
  fi
  ui_pause
}

# summary of ST: module hook, else generic key list (secrets masked)
mili_summary() {  # <type>
  local type="$1" k
  if t_has "$type" summary; then t_call "$type" summary; return; fi
  for k in $(printf '%s\n' "${!ST[@]}" | sort); do
    [[ "$k" =~ (PASS|SECRET|KEY|PSK|TOKEN|pass|secret|psk|token|auth) ]] && { ui_kv "$k" "••••••••"; continue; }
    ui_kv "$k" "${ST[$k]}"
  done
}

# Edit an existing native-pairing tunnel: same wizard (prefilled), then re-provision
mili_native_edit() {  # <name>
  local name="$1" type
  st_load "$name" || return 1
  type="$(st_get type)"
  ui_clear; ui_head "Edit $(t_meta_field "$type" title) — '$name'"
  t_call "$type" wizard "$(st_get role)" full || { ui_warn "edit aborted"; return 1; }
  echo; ui_head "Summary"; mili_summary "$type"; echo
  ui_confirm "Apply these changes now?" y || { ui_warn "not applied"; return 1; }
  st_save; require_root; fw_init
  if t_call "$type" provision "$name"; then
    st_set state up; st_save; ui_ok "tunnel '$name' updated"
    echo; t_has "$type" handoff && t_call "$type" handoff "$name"
  else
    st_set state down; st_save; ui_warn "tunnel '$name' NOT running after the edit (see above)"; return 1
  fi
}

# ============================================================================
# pairing
# ============================================================================
mili_export_code() {  # <name>
  local name="$1" type payload pass=''
  st_load "$name" || { ui_err "unknown tunnel"; return 1; }
  type="$(st_get type)"
  # native-pairing types hand over their core's own token, never a mili code
  if [[ "$(t_meta_field "$type" pairing)" == native ]]; then
    t_has "$type" handoff && t_call "$type" handoff "$name"; return
  fi
  t_has "$type" pair_export || { ui_warn "$type has no pairing"; return 1; }
  payload="$(t_call "$type" pair_export "$name")"
  if ui_confirm "Encrypt the pairing code with a passphrase?" n; then
    pass="$(ui_ask_secret 'Passphrase')"
  fi
  local code; code="$(printf '%s' "$payload" | pair_encode "$pass")"
  pair_present "$code" "Pairing code for tunnel '$name'"
}

mili_import_code() {  # [code]
  ui_head "Import pairing / reply code"
  local code="${1:-}" pass=''
  [[ -z "$code" ]] && code="$(ui_ask 'Paste the code or token' '')"
  code="$(printf '%s' "$code" | tr -d '[:space:]')"
  [[ -z "$code" ]] && return 1

  # not a mili code? maybe a core's own token (native pairing, e.g. a Hedioum token)
  if [[ "$code" != mili1:* && "$code" != mili1e:* ]]; then
    local nt nrole
    for nt in "${MILI_TYPES[@]}"; do
      t_has "$nt" accepts_token || continue
      nrole="$(t_call "$nt" accepts_token "$code")" || continue
      ui_ok "recognized a $(t_meta_field "$nt" title) token -> setting up the ${nrole^} side"
      MILI_PREFILL_TOKEN="$code"
      mili_create "$nt" "$nrole"
      MILI_PREFILL_TOKEN=''
      return
    done
    ui_err "not a mili pairing code or a recognized tunnel token"; ui_pause; return 1
  fi
  [[ "$code" == mili1e:* ]] && pass="$(ui_ask_secret 'Passphrase')"
  local payload; payload="$(pair_decode "$code" "$pass")" || { ui_pause; return 1; }
  local type name reply
  type="$(pair_field "$payload" type)"
  name="$(pair_field "$payload" name)"
  reply="$(pair_field "$payload" reply)"
  [[ -z "$type" || -z "$name" ]] && { ui_err "code missing type/name"; ui_pause; return 1; }
  t_has "$type" pair_import || { ui_err "unknown tunnel type in code: $type"; ui_pause; return 1; }
  require_root; fw_init; svc_install_templates

  # ---- a REPLY code: finalize the tunnel WE generated earlier ----
  if [[ "$reply" == 1 ]]; then
    st_exists "$name" || { ui_err "no local tunnel '$name' to finalize (generate it here first)"; ui_pause; return 1; }
    t_has "$type" pair_finalize || { ui_err "$type has no finalize step"; ui_pause; return 1; }
    ui_info "finalizing tunnel '$name' with the peer's address"
    t_call "$type" pair_finalize "$payload" || { ui_err "finalize failed"; ui_pause; return 1; }
    ui_ok "tunnel '$name' is now fully paired and up"
    ui_pause; return 0
  fi

  # ---- a normal pairing code: configure THIS (second) side ----
  ui_info "importing $type tunnel '$name'"
  t_call "$type" pair_import "$payload" || { ui_err "import failed"; ui_pause; return 1; }
  ui_ok "imported tunnel '$name'"

  # two-way tunnels: hand back a reply code carrying this side's address
  local tw; tw="$(t_meta_field "$type" twoway)"
  if [[ "$tw" == yes ]] && t_has "$type" pair_reply; then
    echo; ui_head "REPLY code — paste this on the FIRST server"
    ui_note "That server is waiting for it (mili → Import pairing code)."
    echo
    local rp; rp="$(t_call "$type" pair_reply "$name" | pair_encode "")"
    printf '%s%s%s\n' "${C_YEL:-}" "$rp" "${C_RST:-}"
    if sys_has qrencode && [[ -t 1 ]]; then echo; qrencode -t ANSIUTF8 "$rp" 2>/dev/null || true; fi
  fi
  ui_pause
}

# ============================================================================
# tunnel management screen
# ============================================================================
mili_manage() {
  local sel=0
  while :; do
    ui_clear; ui_head "Tunnels"
    local names=(); mapfile -t names < <(st_list)
    if [[ ${#names[@]} -eq 0 ]]; then ui_note "no tunnels yet — create one from the main menu"; ui_pause; return; fi
    printf '  %s↑/↓ select · Enter open · q back%s\n\n' "$C_GRY" "$C_RST"
    local n type st labels=()
    for n in "${names[@]}"; do
      st_load "$n"; type="$(st_get type)"
      if t_has "$type" health && t_call "$type" health "$n" >/dev/null 2>&1; then st="${C_GRN}● up${C_RST}"; else st="${C_RED}● down${C_RST}"; fi
      labels+=("$(printf '%-12s %b' "$n" "$st")"$'\t'"$type · ${ST[role]:-}")
    done
    labels+=("Back"$'\t')
    ui_select "$sel" "${labels[@]}"
    sel=$(( SEL>0 ? SEL-1 : sel ))
    (( SEL==0 || SEL > ${#names[@]} )) && return
    mili_tunnel_actions "${names[$((SEL-1))]}"
  done
}

mili_tunnel_actions() {  # <name>
  local name="$1" type sel=0
  st_load "$name"; type="$(st_get type)"
  while :; do
    ui_clear; ui_head "Tunnel: $name  ($type)"
    # live connection status banner
    local hstate hcolor hicon
    if t_has "$type" health && t_call "$type" health "$name" >/dev/null 2>&1; then
      hstate="CONNECTED"; hcolor="$C_GRN"; hicon="●"
    else
      hstate="NOT CONNECTED"; hcolor="$C_RED"; hicon="●"
    fi
    local plabel='Show pairing code' native=0
    if [[ "$(t_meta_field "$type" pairing)" == native ]]; then
      native=1; plabel="$(t_meta_field "$type" handoff_label)"; plabel="${plabel:-Show pairing token}"
    fi
    printf '  %s %s LINK: %s %s%s\n' "$hcolor" "$hicon" "$hstate" "$(grep -q '^state=up' "$MILI_TUNDIR/$name.conf" 2>/dev/null && printf '(started)' || printf '(stopped)')" "$C_RST"
    ui_hr 64
    t_has "$type" info && t_call "$type" info "$name"
    echo
    ui_select "$sel" \
      $'Start' $'Stop' $'Restart' \
      $'Logs (follow)' \
      $'3x-ui JSON helper' \
      $'Test (socks / ping)' \
      "$plabel" \
      $'Edit / re-render' \
      $'Delete' \
      $'Back'
    sel=$(( SEL>0 ? SEL-1 : sel ))
    case "$SEL" in
      1) mili_up "$name"; ui_pause ;;
      2) mili_down "$name"; ui_pause ;;
      3) mili_restart "$name"; ui_pause ;;
      4) local u; u="$(t_has "$type" unit && t_call "$type" unit "$name")"; [[ -n "$u" ]] && svc_logs_follow "$u" || { ui_warn "no unit"; ui_pause; } ;;
      5) st_load "$name"; t_has "$type" xui && t_call "$type" xui "$name"; ui_pause ;;
      6) t_has "$type" test && t_call "$type" test "$name" || ui_warn "no test for $type"; ui_pause ;;
      7) mili_export_code "$name"; ui_pause ;;
      8) if (( native )) && t_has "$type" provision; then mili_native_edit "$name"
         elif t_has "$type" wizard; then st_load "$name"; t_call "$type" wizard "$(st_get role)" advanced && st_save && mili_restart "$name"; fi
         ui_pause ;;
      9) mili_delete "$name" && return ;;
      10|0) return ;;
    esac
    st_load "$name"
  done
}

# ============================================================================
# dashboard header + main menu
# ============================================================================
# Fast header: counts come from the stored `state` field (no live probing, no
# per-tunnel systemctl calls). Public IPv4 is cached after the first call.
mili_header() {
  ui_clear
  ui_banner "unified anti-DPI tunnel manager  v$MILI_VERSION"
  local total=0 up=0 n
  while read -r n; do
    [[ -z "$n" ]] && continue
    ((total++))
    grep -q '^state=up' "$MILI_TUNDIR/$n.conf" 2>/dev/null && ((up++))
  done < <(st_list)
  echo
  printf '  %s  %s  %s\n' "$(mili_edition_badge)" \
    "$(ui_badge "$(hostname -s 2>/dev/null || hostname)" "$C_BLU")" \
    "$(ui_badge "x-ui: $(xui_status_line)" "$C_MAG")"
  ui_kv "Public IPv4" "$(sys_public_ip4)"
  [[ "${MILI_PUBIP6:-}" != "" && "${MILI_PUBIP6:-}" != none ]] && ui_kv "Public IPv6" "$MILI_PUBIP6"
  ui_kv "Role default" "${MILI_DEFAULT_ROLE:-not set}"
  ui_kv "Tunnels" "$(printf '%s%s up%s / %s%s stopped%s  (%s total)' "$C_GRN" "$up" "$C_RST" "$C_GRY" "$((total-up))" "$C_RST" "$total")"
  if [[ -n "${MILI_PORT_ALERT:-}" ]]; then
    ui_err "PORT CONFLICT detected - open 'Ports & conflicts'"
  fi
  ui_hr 64
}

mili_menu() {
  require_root
  st_dir_init; ports_db_init
  # one-shot public IP fetch so the first draw isn't blocked repeatedly
  sys_public_ip4 >/dev/null 2>&1 &
  local sel=0
  while :; do
    # cheap port-conflict flag, refreshed once per full redraw
    ports_audit >/dev/null 2>&1 && MILI_PORT_ALERT='' || MILI_PORT_ALERT=1
    mili_header
    printf '  %snavigate %s↑/↓%s   select %sEnter%s   quit %sq%s\n\n' \
      "$C_GRY" "$C_CYN" "$C_GRY" "$C_CYN" "$C_GRY" "$C_CYN" "$C_RST"
    ui_select "$sel" \
      $'★ New tunnel\tcreate + get pairing code' \
      $'Import pairing code\tpaste code from the other server' \
      $'Manage tunnels\tstart · stop · logs · x-ui JSON · delete' \
      $'3x-ui helper\tdetected panel / inbounds / recipes' \
      $'Ports & conflicts\tregistry + live audit' \
      $'Cores (binaries)\tinstall · update · rollback · offline' \
      $'Network optimizer\tBBR · fq · MTU finder' \
      $'Diagnostics\tdoctor · connectivity · bundle' \
      $'Backup & restore' \
      $'Settings' \
      $'Edition / License' \
      $'Update mili' \
      $'Uninstall' \
      $'Exit'
    sel=$(( SEL>0 ? SEL-1 : sel ))
    case "$SEL" in
      1) mili_new_tunnel ;;
      2) mili_import_code ;;
      3) mili_manage ;;
      4) mili_menu_xui ;;
      5) mili_menu_ports ;;
      6) mili_menu_cores ;;
      7) mili_menu_optimize ;;
      8) doctor_run; ui_pause ;;
      9) mili_menu_backup ;;
      10) mili_menu_settings ;;
      11) mili_menu_edition ;;
      12) mili_update; ui_pause ;;
      13) mili_menu_uninstall ;;
      14) ui_clear; exit 0 ;;
      0) ui_confirm "Quit mili?" y && { ui_clear; exit 0; } ;;
    esac
  done
}

mili_menu_xui() {
  ui_clear; ui_head "3x-ui helper"
  if ! xui_installed; then ui_warn "3x-ui not detected"; else
    ui_kv "status" "$(xui_status_line)"
    echo; ui_info "inbounds:"
    xui_inbounds 2>/dev/null | while IFS='|' read -r t p pr; do ui_note "- $t (port $p, $pr)"; done
    echo; ui_info "mili tunnels with ready SOCKS outbound JSON: open each tunnel -> '3x-ui JSON helper'"
  fi
  ui_pause
}

mili_menu_ports() {
  ui_clear; ui_head "Ports & conflicts"
  ui_info "mili-claimed ports:"
  if [[ -s "$MILI_PORTSDB" ]]; then
    awk -F'|' 'NF>=3 && $3 ~ /^[0-9]+$/ {printf "  %-12s %-5s %-6s %s\n",$1,$2,$3,$4}' "$MILI_PORTSDB"
  else ui_note "none"; fi
  echo; ui_info "audit:"
  if ports_audit; then ui_ok "no conflicts"; fi
  echo; ui_info "reserved (never used): ${MILI_RESERVED[*]}"
  echo; if ui_confirm "Find a free public port?" n; then ui_kv "free public" "$(ports_alloc_public)"; fi
  ui_pause
}

mili_menu_cores() {
  local cores=(frp backhaul paqet hedioum gost rathole hysteria singbox) sel=0
  while :; do
    ui_clear; ui_head "Cores (binaries)"
    ui_note "Enter on a core installs/updates it to the pinned version."
    echo
    local c v inst labels=()
    for c in "${cores[@]}"; do
      v="$(cores_version "$c")"; inst="$(cores_installed_version "$c" 2>/dev/null)"
      if [[ -n "$inst" ]]; then labels+=("$(printf '%-10s' "$c")"$'\t'"v$v · ${C_GRN}installed $inst${C_RST}")
      else labels+=("$(printf '%-10s' "$c")"$'\t'"v$v · not installed"); fi
    done
    labels+=("Build offline bundle"$'\t' "Import offline bundle"$'\t' \
             "Peer serve (foreign)"$'\t' "Peer pull (iran)"$'\t' "Back"$'\t')
    ui_select "$sel" "${labels[@]}"
    sel=$(( SEL>0 ? SEL-1 : sel ))
    local base=${#cores[@]}
    if (( SEL>=1 && SEL<=base )); then require_root; cores_install "${cores[$((SEL-1))]}"; ui_pause
    else case $(( SEL-base )) in
      1) fetch_bundle; ui_pause ;;
      2) local t; t="$(ui_ask 'Path to bundle tar.gz' '')"; fetch_bundle_import "$t"; ui_pause ;;
      3) fetch_peer_serve; ui_pause ;;
      4) local code; code="$(ui_ask 'Pull code' '')"; fetch_peer_pull "$code"; ui_pause ;;
      *) return ;;
    esac; fi
  done
}

mili_menu_optimize() {
  ui_clear; ui_head "Network optimizer"
  optimize_status; echo
  ui_select 0 $'Apply tuning\tBBR + fq + buffers' $'Revert tuning' $'MTU finder' $'Back'
  case "$SEL" in
    1) require_root; optimize_apply; ui_pause ;;
    2) require_root; optimize_revert; ui_pause ;;
    3) local h; h="$(ui_ask 'Target host/IP' '1.1.1.1')"; doctor_mtu "$h"; ui_pause ;;
  esac
}

mili_menu_backup() {
  ui_clear; ui_head "Backup & restore"
  ui_select 0 $'Create backup' $'List backups' $'Restore' $'Back'
  case "$SEL" in
    1) require_root; backup_create >/dev/null; ui_pause ;;
    2) backup_list; ui_pause ;;
    3) local t; t="$(ui_ask 'Backup path' "$(backup_list 2>/dev/null | head -n1)")"; require_root; backup_restore "$t"; ui_pause ;;
  esac
}

mili_menu_settings() {
  ui_clear; ui_head "Settings"
  ui_kv "Default role"   "${MILI_DEFAULT_ROLE:-(unset)}"
  ui_kv "GH proxies"     "$MILI_GH_PROXIES"
  ui_kv "Mirror"         "${MILI_MIRROR:-(none)}"
  ui_kv "Color mode"     "$MILI_COLORMODE"
  echo
  ui_select 0 $'Set default role\tiran / foreign' $'Set GitHub proxy prefixes' $'Set mirror base URL' $'Back'
  case "$SEL" in
    1) ui_select 0 $'iran' $'foreign'; [[ "$SEL" == 1 ]] && mili_conf_set MILI_DEFAULT_ROLE iran; [[ "$SEL" == 2 ]] && mili_conf_set MILI_DEFAULT_ROLE foreign; ui_pause ;;
    2) local p; p="$(ui_ask 'Space-separated proxy prefixes' "$MILI_GH_PROXIES")"; mili_conf_set MILI_GH_PROXIES "$p"; ui_pause ;;
    3) local m; m="$(ui_ask 'Mirror base URL' "$MILI_MIRROR")"; mili_conf_set MILI_MIRROR "$m"; ui_pause ;;
  esac
}

mili_conf_set() {  # <KEY> <VALUE> : persist to mili.conf
  st_dir_init
  local key="$1" val="$2" tmp; tmp="$(mktemp)"
  { grep -vE "^$key=" "$MILI_CONF" 2>/dev/null; printf '%s=%q\n' "$key" "$val"; } >"$tmp"
  mv -f "$tmp" "$MILI_CONF"; chmod 600 "$MILI_CONF" 2>/dev/null || true
  export "$key=$val"
  ui_ok "saved $key"
}

mili_menu_edition() {
  ui_clear; ui_head "Edition / License"
  ui_kv "Edition" "$(mili_edition)"
  echo; ui_note "All features are FREE in this version."
  ui_note "Premium tier (reserved features, licensing) is planned - hooks are in place."
  ui_pause
}

mili_menu_uninstall() {
  ui_clear; ui_head "Uninstall"
  ui_select 0 $'Remove ONE tunnel\topens Manage → Delete' $'Remove EVERYTHING\tall tunnels + mili (x-ui untouched)' $'Back'
  case "$SEL" in
    1) mili_manage ;;
    2) mili_uninstall_all ;;
  esac
}

# ============================================================================
# install / update / uninstall
# ============================================================================
mili_update() {
  require_root
  ui_info "re-running install bootstrap to fetch the latest mili"
  local url="${MILI_SELF_URL:-https://raw.githubusercontent.com/yaldoughie/mili/main/install.sh}"
  if curl -fsSL "$url" -o /tmp/mili-install.sh 2>/dev/null; then
    bash /tmp/mili-install.sh && ui_ok "mili updated"
  else
    ui_warn "could not reach update URL (set MILI_SELF_URL); current version kept"
  fi
}

mili_uninstall_all() {
  ui_err "This removes ALL mili tunnels, services, firewall rules, sysctl files and /etc/mili."
  ui_warn "3x-ui and its data are NOT touched."
  ui_confirm "Type-confirm: remove everything mili?" n || return 1
  require_root
  local n type
  while read -r n; do
    [[ -z "$n" ]] && continue
    st_load "$n"; type="$(st_get type)"
    t_call "$type" down "$n" >/dev/null 2>&1 || true
    t_has "$type" purge && t_call "$type" purge "$n" >/dev/null 2>&1 || true
  done < <(st_list)
  # stop & remove units
  systemctl stop 'mili-*' 2>/dev/null || true
  systemctl disable mili-fw.service mili-watchdog.timer 2>/dev/null || true
  rm -f /etc/systemd/system/mili-*.service /etc/systemd/system/mili-*.timer 2>/dev/null || true
  systemctl daemon-reload 2>/dev/null || true
  fw_teardown
  sysctl_remove_all; run sysctl --system >/dev/null 2>&1 || true
  rm -rf /opt/mili /etc/mili /var/log/mili /etc/logrotate.d/mili 2>/dev/null || true
  rm -f /usr/local/bin/mili 2>/dev/null || true
  ui_ok "mili fully removed. Verify: iptables-save | grep -i mili ; systemctl list-units 'mili*'"
}

# ============================================================================
# hidden service dispatchers (called by systemd units)
# ============================================================================
# mili _svc <engine> <name> : exec the engine in foreground for its unit
mili_svc_exec() {
  local engine="$1" name="$2"
  case "$engine" in
    socks)    socks_exec "$name" ;;
    frps|frpc)
      local _cfg="$MILI_ETC/engines/$engine/$name.toml" _bin
      _bin="$(cores_path "$engine")"
      [[ -x "$_bin" ]] || die "frp core not installed"
      [[ -f "$_cfg" ]] || die "frp config missing: $_cfg"
      exec "$_bin" -c "$_cfg" ;;
    backhaul)
      local _cfg="$MILI_ETC/engines/backhaul/$name.toml" _bin
      _bin="$(cores_path backhaul)"
      [[ -x "$_bin" && -f "$_cfg" ]] || die "backhaul core/config missing"
      exec "$_bin" -c "$_cfg" ;;
    paqet)
      local _cfg="$MILI_ETC/engines/paqet/$name.conf" _bin
      _bin="$(cores_path paqet)"
      [[ -x "$_bin" && -f "$_cfg" ]] || die "paqet core/config missing"
      exec "$_bin" -c "$_cfg" ;;
    *)
      # generic: module provides t_<type>_svc_exec that execs the core
      local type; st_load "$name" >/dev/null 2>&1 && type="$(st_get type)"
      if [[ -n "${type:-}" ]] && t_has "$type" svc_exec; then
        t_call "$type" svc_exec "$name" "$engine"
      else
        die "no svc_exec for engine $engine / tunnel $name"
      fi ;;
  esac
}

mili_fw_restore() {
  st_dir_init; fw_init
  local n type
  while read -r n; do
    [[ -z "$n" ]] && continue
    st_load "$n"; type="$(st_get type)"
    t_has "$type" fw_apply && t_call "$type" fw_apply "$n" || true
  done < <(st_list)
}

# ============================================================================
# CLI
# ============================================================================
mili_cli() {
  local cmd="$1"; shift || true
  case "$cmd" in
    status|list)
      local n type st
      printf '%-12s %-10s %-6s\n' NAME TYPE STATE
      while read -r n; do
        [[ -z "$n" ]] && continue
        st_load "$n"; type="$(st_get type)"
        if t_has "$type" health && t_call "$type" health "$n" >/dev/null 2>&1; then st=up; else st=down; fi
        printf '%-12s %-10s %-6s\n' "$n" "$type" "$st"
      done < <(st_list) ;;
    up)      mili_up "$1" ;;
    down)    mili_down "$1" ;;
    restart) mili_restart "$1" ;;
    logs)    st_load "$1"; local ty; ty="$(st_get type)"; local u; u="$(t_call "$ty" unit "$1")"; svc_logs_follow "$u" ;;
    import)  mili_import_code "$1" ;;
    export)  mili_export_code "$1" ;;
    ports)   ports_audit && ui_ok "no conflicts" ;;
    doctor)  doctor_run ;;
    cores)   case "$1" in install) cores_install "$2";; bundle) fetch_bundle "$2";; *) ui_info "cores: install <c> | bundle";; esac ;;
    update)  mili_update ;;
    uninstall) mili_uninstall_all ;;
    version) echo "mili $MILI_VERSION" ;;
    _svc)        mili_svc_exec "$@" ;;
    _l3)         local _op="$1" _nm="$2"; st_load "$_nm" || die "unknown tunnel $_nm"; t_call "$(st_get type)" "if$_op" "$_nm" ;;
    _up)         mili_up "$1" ;;
    _down)       mili_down "$1" ;;
    _watchdog)   watchdog_run ;;
    _fw-restore) mili_fw_restore ;;
    ''|menu) mili_menu ;;
    *) ui_err "unknown command: $cmd"; echo "try: mili status|up|down|restart|logs|import|export|ports|doctor|cores|update|uninstall|version"; return 1 ;;
  esac
}

# load persisted config
[[ -r "$MILI_CONF" ]] && { set -a; . "$MILI_CONF"; set +a; }

mili_cli "$@"
